@Test
public void serializeClient() throws URISyntaxException {
    String endpoint = "iceberg-test-oss.aliyun.com";
    String accessKeyId = UUID.randomUUID().toString();
    String accessSecret = UUID.randomUUID().toString();
    SerializableSupplier<OSS> pre = () -> new OSSClientBuilder().build(endpoint, accessKeyId, accessSecret);
    byte[] data = SerializationUtil.serializeToBytes(pre);
    SerializableSupplier<OSS> post = SerializationUtil.deserializeFromBytes(data);
    OSS client = post.get();
    assertThat(client).as("Should be instance of oss client").isInstanceOf(OSSClient.class);
    OSSClient oss = (OSSClient) client;
    assertThat(oss.getEndpoint()).as("Should have expected endpoint").isEqualTo(new URI("http://" + endpoint));
    assertThat(oss.getCredentialsProvider().getCredentials().getAccessKeyId()).as("Should have expected access key").isEqualTo(accessKeyId);
    assertThat(oss.getCredentialsProvider().getCredentials().getSecretAccessKey()).as("Should have expected secret key").isEqualTo(accessSecret);
    assertThat(oss.getCredentialsProvider().getCredentials().getSecurityToken()).as("Should have no security token").isNull();
}

