@Test
public void testLoadDefault() {
    assertThat(AliyunClientFactories.defaultFactory()).as("Default client should be singleton").isEqualTo(AliyunClientFactories.defaultFactory());
    AliyunClientFactory defaultFactory = AliyunClientFactories.from(Maps.newHashMap());
    assertThat(defaultFactory).as("Should load default when factory impl not configured").isInstanceOf(AliyunClientFactories.DefaultAliyunClientFactory.class);
    assertThat(defaultFactory.aliyunProperties().accessKeyId()).as("Should have no Aliyun properties set").isNull();
    assertThat(defaultFactory.aliyunProperties().securityToken()).as("Should have no security token").isNull();
    AliyunClientFactory defaultFactoryWithConfig = AliyunClientFactories.from(ImmutableMap.of(AliyunProperties.CLIENT_ACCESS_KEY_ID, "key", AliyunProperties.CLIENT_SECURITY_TOKEN, "token"));
    assertThat(defaultFactoryWithConfig).as("Should load default when factory impl not configured").isInstanceOf(AliyunClientFactories.DefaultAliyunClientFactory.class);
    assertThat(defaultFactoryWithConfig.aliyunProperties().accessKeyId()).as("Should have access key set").isEqualTo("key");
    assertThat(defaultFactoryWithConfig.aliyunProperties().securityToken()).as("Should have security token set").isEqualTo("token");
}

