    assertThatThrownBy(() -> in("x", 5, 6).literal()).isInstanceOf(IllegalArgumentException.class).hasMessage("IN predicate cannot return a literal");
    assertThatThrownBy(() -> in("x", 1, 2, null)).isInstanceOf(NullPointerException.class).hasMessage("Cannot create expression literal from null");
    assertThatThrownBy(() -> new Evaluator(STRUCT, in("x", 7, 8, 9.1))).isInstanceOf(ValidationException.class).hasMessageContaining("Invalid value for conversion to type int");
    assertThatThrownBy(() -> predicate(Expression.Operation.IN, "x")).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot create IN predicate without a value");
    assertThatThrownBy(() -> new Evaluator(STRUCT, predicate(Expression.Operation.IN, "x", 5.1))).isInstanceOf(ValidationException.class).hasMessageContaining("Invalid value for conversion to type int");
}

