@Test
public void testIdenticalExpressionIsEquivalent() {
    Expression[] exprs = new Expression[] { Expressions.isNull("data"), Expressions.notNull("data"), Expressions.isNaN("measurement"), Expressions.notNaN("measurement"), Expressions.lessThan("id", 5), Expressions.lessThanOrEqual("id", 5), Expressions.greaterThan("id", 5), Expressions.greaterThanOrEqual("id", 5), Expressions.equal("id", 5), Expressions.notEqual("id", 5), Expressions.in("id", 5, 6), Expressions.notIn("id", 5, 6), Expressions.startsWith("data", "aaa"), Expressions.notStartsWith("data", "aaa"), Expressions.alwaysTrue(), Expressions.alwaysFalse(), Expressions.and(Expressions.lessThan("id", 5), Expressions.notNull("data")), Expressions.or(Expressions.lessThan("id", 5), Expressions.notNull("data")) };
    for (Expression expr : exprs) {
        assertThat(ExpressionUtil.equivalent(expr, expr, STRUCT, true)).as("Should accept identical expression: " + expr).isTrue();
        for (Expression other : exprs) {
            if (expr != other) {
                assertThat(ExpressionUtil.equivalent(expr, other, STRUCT, true)).isFalse();
            }
        }
    }
}

@Test
public void testIdenticalTermIsEquivalent() {
    UnboundTerm<?>[] terms = new UnboundTerm<?>[] { Expressions.ref("id"), Expressions.truncate("id", 2), Expressions.bucket("id", 16), Expressions.year("ts"), Expressions.month("ts"), Expressions.day("ts"), Expressions.hour("ts") };
    for (UnboundTerm<?> term : terms) {
        BoundTerm<?> bound = term.bind(STRUCT, true);
        assertThat(bound.isEquivalentTo(bound)).as("Should accept identical expression: " + term).isTrue();
        for (UnboundTerm<?> other : terms) {
            if (term != other) {
                assertThat(bound.isEquivalentTo(other.bind(STRUCT, true))).isFalse();
            }
        }
    }
}

