@Test
public void testNegativeStringToTimestampLiteral() {
    // use Avro's timestamp conversion to validate the result
    Schema avroSchema = LogicalTypes.timestampMicros().addToSchema(Schema.create(Schema.Type.LONG));
    TimeConversions.TimestampMicrosConversion avroConversion = new TimeConversions.TimestampMicrosConversion();
    // Timestamp with explicit UTC offset, +00:00
    Literal<CharSequence> timestampStr = Literal.of("1969-12-31T23:59:58.999999+00:00");
    Literal<Long> timestamp = timestampStr.to(Types.TimestampType.withZone());
    long avroValue = avroConversion.toLong(LocalDateTime.of(1969, 12, 31, 23, 59, 58, 999999 * 1_000).toInstant(ZoneOffset.UTC), avroSchema, avroSchema.getLogicalType());
    assertThat((long) timestamp.value()).as("Timestamp should match").isEqualTo(avroValue).as("Timestamp should be -1_000_001").isEqualTo(-1_000_001);
    // Timestamp without an explicit zone should be UTC (equal to the previous converted value)
    timestampStr = Literal.of("1969-12-31T23:59:58.999999");
    timestamp = timestampStr.to(Types.TimestampType.withoutZone());
    assertThat((long) timestamp.value()).as("Timestamp without zone should match UTC").isEqualTo(avroValue);
    // Timestamp with an explicit offset should be adjusted to UTC
    timestampStr = Literal.of("1969-12-31T16:59:58.999999-07:00");
    timestamp = timestampStr.to(Types.TimestampType.withZone());
    avroValue = avroConversion.toLong(LocalDateTime.of(1969, 12, 31, 23, 59, 58, 999999 * 1_000).toInstant(ZoneOffset.UTC), avroSchema, avroSchema.getLogicalType());
    assertThat((long) timestamp.value()).as("Timestamp without zone should match UTC").isEqualTo(avroValue).as("Timestamp without zone should be -1_000_001").isEqualTo(-1_000_001);
}

