@Test
public void testStruct() {
    Schema schema = new Schema(Types.NestedField.required(1, "id", Types.StringType.get()), Types.NestedField.optional(2, "location", Types.StructType.of(Types.NestedField.required(11, "lat", Types.FloatType.get()), Types.NestedField.required(12, "long", Types.FloatType.get()))));
    SortOrder latOnlyAsc = SortOrder.builderFor(schema).asc("location.lat").build();
    TestHelpers.Row lessLat = TestHelpers.Row.of("id4", TestHelpers.Row.of(1.0f, 1.0f));
    TestHelpers.Row greaterLat = TestHelpers.Row.of("id3", TestHelpers.Row.of(2.0f, 1.0f));
