    assertComparesCorrectly(schema, latOnlyAsc, lessLat, greaterLat, lessLatCopy, nullLat);
    SortOrder longOnlyDesc = SortOrder.builderFor(schema).desc("location.long", NullOrder.NULLS_LAST).build();
    TestHelpers.Row lessLong = TestHelpers.Row.of("id4", TestHelpers.Row.of(1.0f, 1.0f));
    TestHelpers.Row greaterLong = TestHelpers.Row.of("id3", TestHelpers.Row.of(1.0f, 2.0f));
    TestHelpers.Row lessLongCopy = TestHelpers.Row.of("id2", TestHelpers.Row.of(1.0f, 1.0f));
    TestHelpers.Row nullLong = TestHelpers.Row.of("id1", TestHelpers.Row.of(1.0f, null));
    assertComparesCorrectly(schema, longOnlyDesc, lessLong, greaterLong, lessLongCopy, nullLong);
    SortOrder twoFieldsSortOrder = SortOrder.builderFor(schema).asc("location.lat").asc("location.long").build();
    TestHelpers.Row lessTwoSortFields = TestHelpers.Row.of("id4", TestHelpers.Row.of(1.0f, 1.0f));
    TestHelpers.Row greaterLatTwoSortFields = TestHelpers.Row.of("id3", TestHelpers.Row.of(2.0f, 1.0f));
    TestHelpers.Row greaterLongTwoSortFields = TestHelpers.Row.of("id3", TestHelpers.Row.of(1.0f, 2.0f));
    TestHelpers.Row greaterBothTwoSortFields = TestHelpers.Row.of("id3", TestHelpers.Row.of(2.0f, 2.0f));
    TestHelpers.Row lessTwoSortFieldsCopy = TestHelpers.Row.of("id2", TestHelpers.Row.of(1.0f, 1.0f));
    TestHelpers.Row nullLatTwoSortFields = TestHelpers.Row.of("id1", TestHelpers.Row.of(null, 1.0f));
    TestHelpers.Row nullLongTwoSortFields = TestHelpers.Row.of("id1", TestHelpers.Row.of(1.0f, null));
    TestHelpers.Row nullBothTowSortFields = TestHelpers.Row.of("id1", TestHelpers.Row.of(null, null));
    assertComparesCorrectly(schema, twoFieldsSortOrder, lessTwoSortFields, greaterLatTwoSortFields, lessTwoSortFieldsCopy, nullLatTwoSortFields);
    assertComparesCorrectly(schema, twoFieldsSortOrder, lessTwoSortFields, greaterLongTwoSortFields, lessTwoSortFieldsCopy, nullLongTwoSortFields);
    assertComparesCorrectly(schema, twoFieldsSortOrder, lessTwoSortFields, greaterBothTwoSortFields, lessTwoSortFieldsCopy, nullBothTowSortFields);
}

@Test
public void testStructTransform() {
    Schema schema = new Schema(Types.NestedField.required(1, "id", Types.StringType.get()), Types.NestedField.optional(2, "struct", Types.StructType.of(Types.NestedField.required(11, "left", Types.BinaryType.get()), Types.NestedField.required(12, "right", Types.BinaryType.get()))));
    Transform<ByteBuffer, ByteBuffer> bucket = Transforms.truncate(2);
    SerializableFunction<ByteBuffer, ByteBuffer> transform = bucket.bind(Types.BinaryType.get());
    assertThat(transform.apply(ByteBuffer.wrap(new byte[] { 2, 3, 4 }))).isLessThan(transform.apply(ByteBuffer.wrap(new byte[] { 9, 3, 4 })));
    assertThat(transform.apply(ByteBuffer.wrap(new byte[] { 2, 3, 4 }))).isEqualTo(transform.apply(ByteBuffer.wrap(new byte[] { 2, 3, 9 })));
    TestHelpers.Row less = TestHelpers.Row.of("id4", TestHelpers.Row.of(ByteBuffer.wrap(new byte[] { 1 }), ByteBuffer.wrap(new byte[] { 2, 3, 4 })));
    TestHelpers.Row greater = TestHelpers.Row.of("id3", TestHelpers.Row.of(ByteBuffer.wrap(new byte[] { 1 }), ByteBuffer.wrap(new byte[] { 9, 3, 4 })));
    TestHelpers.Row lessCopy = TestHelpers.Row.of("id2", TestHelpers.Row.of(ByteBuffer.wrap(new byte[] { 1 }), ByteBuffer.wrap(new byte[] { 2, 3, 9 })));
    TestHelpers.Row nullRight = TestHelpers.Row.of("id1", TestHelpers.Row.of(ByteBuffer.wrap(new byte[] { 1 }), null));
    SortOrder sortOrder = SortOrder.builderFor(schema).sortBy(Expressions.truncate("struct.left", 2), SortDirection.ASC, NullOrder.NULLS_FIRST).sortBy(Expressions.truncate("struct.right", 2), SortDirection.ASC, NullOrder.NULLS_FIRST).build();
    assertComparesCorrectly(schema, sortOrder, less, greater, lessCopy, nullRight);
}

