@Test
public void testSpecValues() {
    assertThat(BucketUtil.hash(1)).as("Spec example: hash(true) = 1392991556").isEqualTo(1392991556);
    assertThat(BucketUtil.hash(34)).as("Spec example: hash(34) = 2017239379").isEqualTo(2017239379);
    assertThat(BucketUtil.hash(34L)).as("Spec example: hash(34L) = 2017239379").isEqualTo(2017239379);
    assertThat(BucketUtil.hash(1.0F)).as("Spec example: hash(17.11F) = -142385009").isEqualTo(-142385009);
    assertThat(BucketUtil.hash(1.0D)).as("Spec example: hash(17.11D) = -142385009").isEqualTo(-142385009);
    assertThat(BucketUtil.hash(0.0F)).as("Spec example: hash(0.0F) = 1669671676").isEqualTo(1669671676);
    assertThat(BucketUtil.hash(-0.0F)).as("Spec example: hash(-0.0F) = 1669671676").isEqualTo(1669671676);
    assertThat(BucketUtil.hash(0.0)).as("Spec example: hash(0.0) = 1669671676").isEqualTo(1669671676);
    assertThat(BucketUtil.hash(-0.0)).as("Spec example: hash(-0.0) = 1669671676").isEqualTo(1669671676);
    assertThat(BucketUtil.hash(new BigDecimal("14.20"))).as("Spec example: hash(decimal2(14.20)) = -500754589").isEqualTo(-500754589).as("Spec example: hash(decimal2(14.20)) = -500754589").isEqualTo(-500754589);
    Literal<Integer> date = Literal.of("2017-11-16").to(Types.DateType.get());
    assertThat(BucketUtil.hash(date.value())).as("Spec example: hash(2017-11-16) = -653330422").isEqualTo(-653330422);
    Literal<Long> timeValue = Literal.of("22:31:08").to(Types.TimeType.get());
    assertThat(BucketUtil.hash(timeValue.value())).as("Spec example: hash(22:31:08) = -662762989").isEqualTo(-662762989);
    Literal<Long> timestampVal = Literal.of("2017-11-16T22:31:08").to(Types.TimestampType.withoutZone());
    assertThat(BucketUtil.hash(timestampVal.value())).as("Spec example: hash(2017-11-16T22:31:08) = -2047944441").isEqualTo(-2047944441);
    Literal<Long> timestamptzVal = Literal.of("2017-11-16T14:31:08-08:00").to(Types.TimestampType.withZone());
    assertThat(BucketUtil.hash(timestamptzVal.value())).as("Spec example: hash(2017-11-16T14:31:08-08:00) = -2047944441").isEqualTo(-2047944441);
    assertThat(BucketUtil.hash("iceberg")).as("Spec example: hash(\"iceberg\") = 1210000089").isEqualTo(1210000089);
    assertThat(BucketUtil.hash(new Utf8("iceberg"))).as("Spec example: hash(\"iceberg\") = 1210000089").isEqualTo(1210000089);
    Literal<UUID> uuid = Literal.of("f79c3e09-677c-4bbd-a479-3f349cb785e7").to(Types.UUIDType.get());
    assertThat(BucketUtil.hash(uuid.value())).as("Spec example: hash(f79c3e09-677c-4bbd-a479-3f349cb785e7) = 1488055340").isEqualTo(1488055340);
    ByteBuffer bytes = ByteBuffer.wrap(new byte[] { 0, 1, 2, 3 });
    assertThat(BucketUtil.hash(bytes)).as("Spec example: hash([00 01 02 03]) = -188683207").isEqualTo(-188683207);
    // another assertion for confirming that hashing a ByteBuffer again doesnt modify its value.
    assertThat(BucketUtil.hash(bytes)).as("Spec example: hash([00 01 02 03]) = -188683207").isEqualTo(-188683207);
}

