    PartitionSpec spec = PartitionSpec.builderFor(SCHEMA).truncate(COLUMN, 4).build();
    assertProjectionInclusive(spec, startsWith(COLUMN, "ab"), "ab", Expression.Operation.STARTS_WITH);
    assertProjectionInclusive(spec, startsWith(COLUMN, "abab"), "abab", Expression.Operation.EQ);
    assertProjectionInclusive(spec, startsWith(COLUMN, "ababab"), "abab", Expression.Operation.STARTS_WITH);
    assertProjectionStrict(spec, startsWith(COLUMN, "ab"), "ab", Expression.Operation.STARTS_WITH);
    assertProjectionStrict(spec, startsWith(COLUMN, "abab"), "abab", Expression.Operation.EQ);
    Expression projection = Projections.strict(spec).project(startsWith(COLUMN, "ababab"));
    assertThat(projection).isInstanceOf(False.class);
}

@Test
@SuppressWarnings("unchecked")
public void testTruncateString() {
    Truncate<String> trunc = Truncate.get(2);
    Expression expr = startsWith(COLUMN, "abcde");
    BoundPredicate<String> boundExpr = (BoundPredicate<String>) Binder.bind(SCHEMA.asStruct(), expr, false);
    UnboundPredicate<String> projected = trunc.project(COLUMN, boundExpr);
    Evaluator evaluator = new Evaluator(SCHEMA.asStruct(), projected);
    assertThat(evaluator.eval(TestHelpers.Row.of("abcdg"))).as("startsWith(abcde, truncate(abcdg,2))  => true").isTrue();
}

@Test
@SuppressWarnings("deprecation")
public void testDeprecatedTimestampTransform() {
    Types.TimestampType type = Types.TimestampType.withoutZone();
    Literal<Long> ts = Literal.of("2017-12-01T10:12:55.038194").to(type);
    Literal<Long> pts = Literal.of("1970-01-01T00:00:01.000001").to(type);
    Literal<Long> nts = Literal.of("1969-12-31T23:59:58.999999").to(type);
    Transform<Long, Integer> years = Transforms.year(type);
    assertThat((int) years.apply(ts.value())).as("Should produce 2017 - 1970 = 47").isEqualTo(47);
    assertThat((int) years.apply(pts.value())).as("Should produce 1970 - 1970 = 0").isZero();
    assertThat((int) years.apply(nts.value())).as("Should produce 1969 - 1970 = -1").isEqualTo(-1);
    Transform<Long, Integer> months = Transforms.month(type);
    assertThat((int) months.apply(ts.value())).as("Should produce 47 * 12 + 11 = 575").isEqualTo(575);
    assertThat((int) months.apply(pts.value())).as("Should produce 0 * 12 + 0 = 0").isZero();
    assertThat((int) months.apply(nts.value())).isEqualTo(-1);
    Transform<Long, Integer> days = Transforms.day(type);
    assertThat((int) days.apply(ts.value())).as("Should produce 17501").isEqualTo(17501);
    assertThat((int) days.apply(pts.value())).as("Should produce 0 * 365 + 0 = 0").isZero();
    assertThat((int) days.apply(nts.value())).isEqualTo(-1);
    Transform<Long, Integer> hours = Transforms.hour(type);
    assertThat((int) hours.apply(ts.value())).as("Should produce 17501 * 24 + 10").isEqualTo(420034);
    assertThat((int) hours.apply(pts.value())).as("Should produce 0 * 24 + 0 = 0").isZero();
    assertThat((int) hours.apply(nts.value())).isEqualTo(-1);
}

