@Test
public void testSeqLength() {
    String s1 = "abc";
    String s2 = "abcd";
    Comparator<CharSequence> cmp = Literal.of(s1).comparator();
    // Sanity check that String.compareTo gives the same result
    assertThat(s1).as("When one string is a substring of the other, the longer is greater").isLessThan(s2);
    assertThat(s2).as("When one string is a substring of the other, the longer is greater").isGreaterThan(s1);
    // Test the comparator
    assertThat(cmp.compare(s1, s2)).as("When one string is a substring of the other, the longer is greater").isLessThan(0);
    assertThat(cmp.compare(s2, s1)).as("When one string is a substring of the other, the longer is greater").isGreaterThan(0);
}

@Test
public void testCharOrderBeforeLength() {
    // abcd < adc even though abcd is longer
    String s1 = "adc";
    String s2 = "abcd";
    Comparator<CharSequence> cmp = Literal.of(s1).comparator();
    // Sanity check that String.compareTo gives the same result
    assertThat(s1).as("First difference takes precedence over length").isGreaterThan(s2);
    assertThat(s2).as("First difference takes precedence over length").isLessThan(s1);
    // Test the comparator
    assertThat(cmp.compare(s1, s2)).as("First difference takes precedence over length").isGreaterThan(0);
    assertThat(cmp.compare(s2, s1)).as("First difference takes precedence over length").isLessThan(0);
}

