@Test
public void testDeleteTableWithPurge() {
    String namespace = createNamespace();
    String tableName = createTable(namespace);
    Table table = glueCatalog.loadTable(TableIdentifier.of(namespace, tableName));
    DataFile testFile = DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-unpartitioned-a.parquet").withFileSizeInBytes(1).withRecordCount(1).build();
    int numFilesToCreate = 31;
    int commitFrequency = 5;
    Transaction txn = table.newTransaction();
    for (int i = 1; i <= numFilesToCreate; i++) {
        AppendFiles appendFiles = txn.newFastAppend().appendFile(testFile);
        appendFiles.commit();
        // Every "commitFrequency" appends commit the transaction and start a new one so we can have
        // multiple manifests
        if (i % commitFrequency == 0) {
            txn.commitTransaction();
            txn = table.newTransaction();
        }
    }
    txn.commitTransaction();
    glueCatalog.dropTable(TableIdentifier.of(namespace, tableName));
    assertThatThrownBy(() -> glueCatalog.loadTable(TableIdentifier.of(namespace, tableName))).isInstanceOf(NoSuchTableException.class).as("should not have table").hasMessageContaining("Table does not exist");
    String warehouseLocation = glueCatalog.defaultWarehouseLocation(TableIdentifier.of(namespace, tableName));
    String prefix = warehouseLocation.split(TEST_BUCKET_NAME + "/", -1)[1];
    ListObjectsV2Response response = S3.listObjectsV2(ListObjectsV2Request.builder().bucket(TEST_BUCKET_NAME).prefix(prefix).build());
    if (response.hasContents()) {
        // might have directory markers left
        for (S3Object s3Object : response.contents()) {
            Optional<Long> size = s3Object.getValueForField("Size", Long.class);
            assertThat(size.isPresent()).isTrue();
            assertThat(size.get()).isEqualTo(0);
        }
    }
}

