@Test
public void testLakeFormationEnabledGlueCatalog() throws Exception {
    String glueArnPrefix = "arn:aws:glue:*:" + AwsIntegTestUtil.testAccountId();
    iam.putRolePolicy(PutRolePolicyRequest.builder().roleName(roleName).policyName(policyName).policyDocument("{" + "\"Version\":\"2012-10-17\"," + "\"Statement\":[{" + "\"Sid\":\"policy1\"," + "\"Effect\":\"Allow\"," + "\"Action\":[\"glue:CreateDatabase\",\"glue:DeleteDatabase\"," + "\"glue:Get*\",\"lakeformation:GetDataAccess\"]," + "\"Resource\":[\"" + glueArnPrefix + ":catalog\"," + "\"" + glueArnPrefix + ":database/allowed_*\"," + "\"" + glueArnPrefix + ":table/allowed_*/*\"," + "\"" + glueArnPrefix + ":userDefinedFunction/allowed_*/*\"]}]}").build());
    Awaitility.await().pollDelay(Duration.ofSeconds(1)).atMost(Duration.ofSeconds(10)).untilAsserted(() -> assertThat(iam.getRolePolicy(GetRolePolicyRequest.builder().roleName(roleName).policyName(policyName).build())).isNotNull());
    GlueCatalog glueCatalog = new GlueCatalog();
    assumeRoleProperties.put("warehouse", "s3://path");
    glueCatalog.initialize("test", assumeRoleProperties);
    Namespace deniedNamespace = Namespace.of("denied_" + UUID.randomUUID().toString().replace("-", ""));
    try {
        assertThatThrownBy(() -> glueCatalog.createNamespace(deniedNamespace)).isInstanceOf(AccessDeniedException.class);
    } catch (AssertionError e) {
        glueCatalog.dropNamespace(deniedNamespace);
        throw e;
    }
    Namespace allowedNamespace = Namespace.of("allowed_" + UUID.randomUUID().toString().replace("-", ""));
    try {
        assertThatNoException().isThrownBy(() -> glueCatalog.createNamespace(allowedNamespace));
    } finally {
        glueCatalog.dropNamespace(allowedNamespace);
        try {
            glueCatalog.close();
        } catch (Exception e) {
            // swallow exception during closing
            LOG.error("Error closing GlueCatalog", e);
        }
    }
}

