public void testRenameTableWithStorageDescriptor() {
    AtomicInteger counter = new AtomicInteger(1);
    Map<String, String> parameters = Maps.newHashMap();
    parameters.put(BaseMetastoreTableOperations.TABLE_TYPE_PROP, BaseMetastoreTableOperations.ICEBERG_TABLE_TYPE_VALUE);
    Map<String, String> storageDescriptorParameters = Maps.newHashMap();
    storageDescriptorParameters.put("key_0", "value_0");
    StorageDescriptor storageDescriptor = StorageDescriptor.builder().parameters(storageDescriptorParameters).build();
    Mockito.doReturn(GetTableResponse.builder().table(Table.builder().databaseName("db").name("t_renamed").parameters(parameters).storageDescriptor(storageDescriptor).build()).build()).when(glue).getTable(Mockito.any(GetTableRequest.class));
