    assertThat(map).containsEntry(S3FileIOProperties.ENDPOINT, s3FileIOProperties.endpoint());
    assertThat(map).containsEntry(S3FileIOProperties.PRELOAD_CLIENT_ENABLED, String.valueOf(s3FileIOProperties.isPreloadClientEnabled()));
    assertThat(map).containsEntry(S3FileIOProperties.DUALSTACK_ENABLED, String.valueOf(s3FileIOProperties.isDualStackEnabled()));
    assertThat(map).containsEntry(S3FileIOProperties.PATH_STYLE_ACCESS, String.valueOf(s3FileIOProperties.isPathStyleAccess()));
    assertThat(map).containsEntry(S3FileIOProperties.USE_ARN_REGION_ENABLED, String.valueOf(s3FileIOProperties.isUseArnRegionEnabled()));
    assertThat(map).containsEntry(S3FileIOProperties.ACCELERATION_ENABLED, String.valueOf(s3FileIOProperties.isAccelerationEnabled()));
    assertThat(map).containsEntry(S3FileIOProperties.REMOTE_SIGNING_ENABLED, String.valueOf(s3FileIOProperties.isRemoteSigningEnabled()));
    assertThat(map).containsEntry(S3FileIOProperties.MULTIPART_UPLOAD_THREADS, String.valueOf(s3FileIOProperties.multipartUploadThreads()));
    assertThat(map).containsEntry(S3FileIOProperties.MULTIPART_SIZE, String.valueOf(s3FileIOProperties.multiPartSize()));
    assertThat(map).containsEntry(S3FileIOProperties.MULTIPART_THRESHOLD_FACTOR, String.valueOf(s3FileIOProperties.multipartThresholdFactor()));
    assertThat(map).containsEntry(S3FileIOProperties.DELETE_BATCH_SIZE, String.valueOf(s3FileIOProperties.deleteBatchSize()));
    assertThat(map).containsEntry(S3FileIOProperties.STAGING_DIRECTORY, String.valueOf(s3FileIOProperties.stagingDirectory()));
