@Test
public void signRequestWithoutBody() {
    HttpRequest request = HttpRequest.request().withMethod("GET").withPath("/v1/config").// Require SigV4 Authorization
    withHeader(Header.header(HttpHeaders.AUTHORIZATION, "AWS4-HMAC-SHA256.*")).// Require that conflicting auth header is relocated
    withHeader(Header.header(RESTSigV4Signer.RELOCATED_HEADER_PREFIX + HttpHeaders.AUTHORIZATION)).// Require the empty body checksum
    withHeader(Header.header(SignerConstant.X_AMZ_CONTENT_SHA256, RESTSigV4Signer.EMPTY_BODY_SHA256));
    mockServer.when(request).respond(HttpResponse.response().withStatusCode(HttpStatus.SC_OK).withBody("{}"));
    ConfigResponse response = client.get("v1/config", ConfigResponse.class, ImmutableMap.of(), e -> {
    });
    mockServer.verify(request, VerificationTimes.exactly(1));
    assertThat(response).isNotNull();
}

@Test
public void signRequestWithBody() {
    HttpRequest request = HttpRequest.request().withMethod("POST").withPath("/v1/oauth/token").// Require SigV4 Authorization
    withHeader(Header.header(HttpHeaders.AUTHORIZATION, "AWS4-HMAC-SHA256.*")).// Require that conflicting auth header is relocated
    withHeader(Header.header(RESTSigV4Signer.RELOCATED_HEADER_PREFIX + HttpHeaders.AUTHORIZATION)).// Require a body checksum is set
    withHeader(Header.header(SignerConstant.X_AMZ_CONTENT_SHA256));
    mockServer.when(request).respond(HttpResponse.response().withStatusCode(HttpStatus.SC_OK).withBody(OAuth2Util.tokenResponseToJson(OAuthTokenResponse.builder().withToken("fake_token").withTokenType("bearer").withIssuedTokenType("n/a").build())));
    Map<String, String> formData = Maps.newHashMap();
    formData.put("client_id", "asdfasd");
    formData.put("client_secret", "asdfasdf");
    formData.put("scope", "catalog");
    OAuthTokenResponse response = client.postForm("v1/oauth/token", formData, OAuthTokenResponse.class, ImmutableMap.of(), e -> {
    });
    mockServer.verify(request, VerificationTimes.exactly(1));
    assertThat(response).isNotNull();
}

