@Test
public void testNoOpAfterDetection() {
    MetricCollector metrics1 = MetricCollector.create(METRICS_NAME);
    metrics1.reportMetric(CoreMetric.RETRY_COUNT, 1);
    MetricCollection metrics1Spy = Mockito.spy(metrics1.collect());
    MetricCollector metrics2 = MetricCollector.create(METRICS_NAME);
    metrics2.reportMetric(CoreMetric.RETRY_COUNT, 0);
    MetricCollection metrics2Spy = Mockito.spy(metrics2.collect());
    RetryDetector detector = new RetryDetector();
    detector.publish(metrics1Spy);
    assertThat(detector.retried()).as("Should detect retries if RETRY_COUNT is zero").isTrue();
    detector.publish(metrics2Spy);
    assertThat(detector.retried()).as("Should remain true once a retry is detected").isTrue();
    Mockito.verify(metrics1Spy).metricValues(Mockito.eq(CoreMetric.RETRY_COUNT));
    Mockito.verifyNoMoreInteractions(metrics1Spy, metrics2Spy);
}

@Test
public void testFileOperations() throws IOException {
    String path = "path/to/file";
    String location = AZURITE_CONTAINER.location(path);
    ADLSFileIO io = createFileIO();
    DataLakeFileClient fileClient = AZURITE_CONTAINER.fileClient(path);
    assertThat(fileClient.exists()).isFalse();
    OutputFile outputFile = io.newOutputFile(location);
    try (OutputStream out = outputFile.create()) {
        out.write(123);
    }
    assertThat(fileClient.exists()).isTrue();
    InputFile inputFile = io.newInputFile(location);
    try (InputStream in = inputFile.newStream()) {
        int byteVal = in.read();
        assertThat(byteVal).isEqualTo(123);
    }
    io.deleteFile(location);
    assertThat(fileClient.exists()).isFalse();
}

