@Test
public void testRangeRead() throws Exception {
    int dataSize = 1024 * 1024 * 10;
    byte[] expected = randomData(dataSize);
    byte[] actual = new byte[dataSize];
    long position;
    int offset;
    int length;
    setupData(expected);
    try (RangeReadable in = new ADLSInputStream(fileClient(), null, azureProperties, MetricsContext.nullMetrics())) {
        // first 1k
        position = 0;
        offset = 0;
        length = 1024;
        readAndCheckRanges(in, expected, position, actual, offset, length);
        // last 1k
        position = dataSize - 1024;
        offset = dataSize - 1024;
        readAndCheckRanges(in, expected, position, actual, offset, length);
        // middle 2k
        position = dataSize / 2 - 1024;
        offset = dataSize / 2 - 1024;
        length = 1024 * 2;
        readAndCheckRanges(in, expected, position, actual, offset, length);
    }
}

