    C catalog = catalog();
    // the catalog may automatically create a default namespace
    List<Namespace> starting = catalog.listNamespaces();
    Namespace parent = Namespace.of("parent");
    Namespace child1 = Namespace.of("parent", "child1");
    Namespace child2 = Namespace.of("parent", "child2");
    catalog.createNamespace(parent);
    assertThat(catalog.listNamespaces()).as("Should include parent").hasSameElementsAs(concat(starting, parent));
    assertThat(catalog.listNamespaces(parent)).as("Should have no children in newly created parent namespace").isEmpty();
    catalog.createNamespace(child1);
    assertThat(catalog.listNamespaces(parent)).as("Should include child1").hasSameElementsAs(ImmutableList.of(child1));
    catalog.createNamespace(child2);
    assertThat(catalog.listNamespaces(parent)).as("Should include child1 and child2").hasSameElementsAs(ImmutableList.of(child1, child2));
    assertThat(catalog.listNamespaces()).as("Should not change listing the root").hasSameElementsAs(concat(starting, parent));
    catalog.dropNamespace(child1);
    assertThat(catalog.listNamespaces(parent)).as("Should include only child2").hasSameElementsAs(ImmutableList.of(child2));
    catalog.dropNamespace(child2);
    assertThat(catalog.listNamespaces(parent)).as("Should be empty").isEmpty();
}

