@Test
public void testRegisterTable() {
    C catalog = catalog();
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    Map<String, String> properties = ImmutableMap.of("user", "someone", "created-at", "2023-01-15T00:00:01");
    Table originalTable = catalog.buildTable(TABLE, SCHEMA).withPartitionSpec(SPEC).withSortOrder(WRITE_ORDER).withProperties(properties).create();
    originalTable.newFastAppend().appendFile(FILE_A).commit();
    originalTable.newFastAppend().appendFile(FILE_B).commit();
    originalTable.newDelete().deleteFile(FILE_A).commit();
    originalTable.newFastAppend().appendFile(FILE_C).commit();
    TableOperations ops = ((BaseTable) originalTable).operations();
    String metadataLocation = ops.current().metadataFileLocation();
    catalog.dropTable(TABLE, false);
    Table registeredTable = catalog.registerTable(TABLE, metadataLocation);
    assertThat(registeredTable).isNotNull();
    assertThat(catalog.tableExists(TABLE)).as("Table must exist").isTrue();
    assertThat(registeredTable.properties()).as("Props must match").containsAllEntriesOf(properties);
    assertThat(registeredTable.schema().asStruct()).as("Schema must match").isEqualTo(originalTable.schema().asStruct());
    assertThat(registeredTable.specs()).as("Specs must match").isEqualTo(originalTable.specs());
    assertThat(registeredTable.sortOrders()).as("Sort orders must match").isEqualTo(originalTable.sortOrders());
    assertThat(registeredTable.currentSnapshot()).as("Current snapshot must match").isEqualTo(originalTable.currentSnapshot());
    assertThat(registeredTable.snapshots()).as("Snapshots must match").isEqualTo(originalTable.snapshots());
    assertThat(registeredTable.history()).as("History must match").isEqualTo(originalTable.history());
    TestHelpers.assertSameSchemaMap(registeredTable.schemas(), originalTable.schemas());
    assertFiles(registeredTable, FILE_B, FILE_C);
    registeredTable.newFastAppend().appendFile(FILE_A).commit();
    assertFiles(registeredTable, FILE_B, FILE_C, FILE_A);
    assertThat(catalog.loadTable(TABLE)).isNotNull();
    assertThat(catalog.dropTable(TABLE)).isTrue();
    assertThat(catalog.tableExists(TABLE)).isFalse();
}

