    CloseableIterable<StructLike> rows = CloseableIterable.withNoopClose(Lists.newArrayList(Row.of(0L, "a"), Row.of(1L, "b"), Row.of(2L, "c"), Row.of(3L, "d"), Row.of(4L, "e"), Row.of(5L, "f"), Row.of(6L, "g"), Row.of(7L, "h"), Row.of(8L, "i"), Row.of(9L, "j")));
    CloseableIterable<Long> deletes = CloseableIterable.withNoopClose(Lists.newArrayList(0L, 3L, 4L, 7L, 9L));
    Predicate<StructLike> shouldKeep = row -> !Deletes.toPositionIndex(deletes).isDeleted(row.get(0, Long.class));
    CloseableIterable<StructLike> actual = CloseableIterable.filter(rows, shouldKeep);
    assertThat(Iterables.transform(actual, row -> row.get(0, Long.class))).as("Filter should produce expected rows").containsExactlyElementsOf(Lists.newArrayList(1L, 2L, 5L, 6L, 8L));
}

@ParameterizedTest
@MethodSource("executorServiceProvider")
public void testCombinedPositionSetRowFilter(ExecutorService executorService) {
    CloseableIterable<StructLike> positionDeletes1 = CloseableIterable.withNoopClose(Lists.newArrayList(Row.of("file_a.avro", 0L), Row.of("file_a.avro", 3L), Row.of("file_a.avro", 9L), Row.of("file_b.avro", 5L), Row.of("file_b.avro", 6L)));
    CloseableIterable<StructLike> positionDeletes2 = CloseableIterable.withNoopClose(Lists.newArrayList(Row.of("file_a.avro", 3L), Row.of("file_a.avro", 4L), Row.of("file_a.avro", 7L), Row.of("file_b.avro", 2L)));
    CloseableIterable<StructLike> rows = CloseableIterable.withNoopClose(Lists.newArrayList(Row.of(0L, "a"), Row.of(1L, "b"), Row.of(2L, "c"), Row.of(3L, "d"), Row.of(4L, "e"), Row.of(5L, "f"), Row.of(6L, "g"), Row.of(7L, "h"), Row.of(8L, "i"), Row.of(9L, "j")));
    Predicate<StructLike> isDeleted = row -> Deletes.toPositionIndex("file_a.avro", ImmutableList.of(positionDeletes1, positionDeletes2), executorService).isDeleted(row.get(0, Long.class));
    CloseableIterable<StructLike> actual = CloseableIterable.filter(rows, isDeleted.negate());
    assertThat(Iterables.transform(actual, row -> row.get(0, Long.class))).as("Filter should produce expected rows").containsExactlyElementsOf(Lists.newArrayList(1L, 2L, 5L, 6L, 8L));
}

@Test
public void testClosePositionStreamRowDeleteMarker() {
    List<Long> deletes = Lists.newArrayList(1L, 2L);
    List<StructLike> records = Lists.newArrayList(Row.of(29, "a", 1L), Row.of(43, "b", 2L), Row.of(61, "c", 3L), Row.of(89, "d", 4L));
    CheckingClosableIterable<StructLike> data = new CheckingClosableIterable<>(records);
    CheckingClosableIterable<Long> deletePositions = new CheckingClosableIterable<>(deletes);
    CloseableIterable<StructLike> posDeletesIterable = Deletes.streamingFilter(data, row -> row.get(2, Long.class), deletePositions);
    // end iterator is always wrapped with FilterIterator
    CloseableIterable<StructLike> eqDeletesIterable = Deletes.filterDeleted(posDeletesIterable, i -> false, new DeleteCounter());
    List<StructLike> result = Lists.newArrayList(eqDeletesIterable.iterator());
    // as first two records deleted, expect only last two records
    assertThat(Iterables.transform(result, row -> row.get(2, Long.class))).as("Filter should produce expected rows").containsExactlyElementsOf(Lists.newArrayList(3L, 4L));
    assertThat(data.isClosed).isTrue();
    assertThat(deletePositions.isClosed).isTrue();
}

@Test
public void testDeleteMarkerFileClosed() {
    List<Long> deletes = Lists.newArrayList(1L, 2L);
    List<StructLike> records = Lists.newArrayList(Row.of(29, "a", 1L, false), Row.of(43, "b", 2L, false), Row.of(61, "c", 3L, false), Row.of(89, "d", 4L, false));
    CheckingClosableIterable<StructLike> data = new CheckingClosableIterable<>(records);
    CheckingClosableIterable<Long> deletePositions = new CheckingClosableIterable<>(deletes);
    CloseableIterable<StructLike> resultIterable = Deletes.streamingMarker(data, row -> row.get(2, Long.class), deletePositions, row -> row.set(3, true));
    // end iterator is always wrapped with FilterIterator
    CloseableIterable<StructLike> eqDeletesIterable = Deletes.filterDeleted(resultIterable, i -> false, new DeleteCounter());
    List<StructLike> result = Lists.newArrayList(eqDeletesIterable.iterator());
    // as first two records deleted, expect only those two records marked
    assertThat(Iterables.transform(result, row -> row.get(3, Boolean.class))).as("Filter should produce expected rows").containsExactlyElementsOf(Lists.newArrayList(true, true, false, false));
    assertThat(data.isClosed).isTrue();
