@Test
public void testSimpleExpressions() {
    Expression[] expressions = new Expression[] { Expressions.alwaysFalse(), Expressions.alwaysTrue(), Expressions.equal("id", 100), Expressions.equal("data", "abcd"), Expressions.equal("b", false), Expressions.equal("i", 34), Expressions.equal("l", 34L), Expressions.equal("f", 100.0f), Expressions.equal("d", 100.0d), Expressions.equal("date", "2022-08-14"), Expressions.equal("ts", "2022-08-14T10:00:00.123456"), Expressions.equal("uuid", UUID.randomUUID()), Expressions.equal("fixed", new byte[] { 1, 2, 3, 4, 5, 6, 7 }), Expressions.equal("bytes", ByteBuffer.wrap(new byte[] { 1, 3, 5 })), Expressions.equal("dec_11_2", new BigDecimal("34.56")), Expressions.equal("time", "23:59:59.654321"), Expressions.lessThan("id", 100), Expressions.lessThanOrEqual("id", 100), Expressions.greaterThan("id", 100), Expressions.greaterThanOrEqual("id", 100), Expressions.isNull("data"), Expressions.notNull("data"), Expressions.isNaN("d"), Expressions.notNaN("f"), Expressions.startsWith("s", "crackle"), Expressions.notStartsWith("s", "tackle"), Expressions.equal(Expressions.day("date"), "2022-08-14"), Expressions.equal(Expressions.bucket("id", 100), 0), Expressions.and(Expressions.or(Expressions.equal("data", UUID.randomUUID().toString()), Expressions.isNull("data")), Expressions.greaterThanOrEqual("id", 66)), Expressions.or(Expressions.greaterThan(Expressions.day("ts"), "2022-08-14"), Expressions.equal("date", "2022-08-14")), Expressions.not(Expressions.in("l", 1, 2, 3, 4)) };
    for (Expression expr : expressions) {
        Expression bound = Binder.bind(SUPPORTED_PRIMITIVES, expr);
        String boundJson = ExpressionParser.toJson(bound, true);
        String unboundJson = ExpressionParser.toJson(expr, true);
        assertThat(boundJson).as("Bound and unbound should produce identical json").isEqualTo(unboundJson);
        Expression parsed = ExpressionParser.fromJson(boundJson, SCHEMA);
