    Transaction createTxn = catalog.buildTable(tableIdent, SCHEMA).withPartitionSpec(SPEC).withProperty("key1", "value1").withProperty(TableProperties.FORMAT_VERSION, String.valueOf(formatVersion)).createOrReplaceTransaction();
    createTxn.newAppend().appendFile(FILE_A).commit();
