    Table table = hadoopCatalog().buildTable(tableIdent, SCHEMA).withPartitionSpec(SPEC).withSortOrder(order).create();
    SortOrder sortOrder = table.sortOrder();
    assertThat(sortOrder.orderId()).as("Order ID must match").isEqualTo(1);
    assertThat(sortOrder.fields().size()).as("Order must have 1 field").isEqualTo(1);
    assertThat(sortOrder.fields().get(0).direction()).as("Direction must match").isEqualTo(ASC);
    assertThat(sortOrder.fields().get(0).nullOrder()).as("Null order must match").isEqualTo(NULLS_FIRST);
    Transform<?, ?> transform = Transforms.identity();
    assertThat(sortOrder.fields().get(0).transform()).as("Transform must match").isEqualTo(transform);
}

