@Test
public void testTablePropsDefinedAtCatalogLevel() throws IOException {
    TableIdentifier tableIdent = TableIdentifier.of("db", "ns1", "ns2", "tbl");
    ImmutableMap<String, String> catalogProps = ImmutableMap.of("table-default.key1", "catalog-default-key1", "table-default.key2", "catalog-default-key2", "table-default.key3", "catalog-default-key3", "table-override.key3", "catalog-override-key3", "table-override.key4", "catalog-override-key4");
    Table table = hadoopCatalog(catalogProps).buildTable(tableIdent, SCHEMA).withPartitionSpec(SPEC).withProperties(null).withProperty("key2", "table-key2").withProperty("key3", "table-key3").withProperty("key5", "table-key5").create();
    assertThat(table.properties().get("key1")).as("Table defaults set for the catalog must be added to the table properties.").isEqualTo("catalog-default-key1");
    assertThat(table.properties().get("key2")).as("Table property must override table default properties set at catalog level.").isEqualTo("table-key2");
    assertThat(table.properties().get("key3")).as("Table property override set at catalog level must override table default" + " properties set at catalog level and table property specified.").isEqualTo("catalog-override-key3");
    assertThat(table.properties().get("key4")).as("Table override not in table props or defaults should be added to table properties").isEqualTo("catalog-override-key4");
    assertThat(table.properties().get("key5")).as("Table properties without any catalog level default or override should be added to table" + " properties.").isEqualTo("table-key5");
}

