    createTxn.newAppend().appendFile(fileA).commit();
    createTxn.commitTransaction();
    Table table = catalog.loadTable(tableIdent);
    assertThat(table.currentSnapshot()).isNotNull();
    Transaction replaceTxn = catalog.buildTable(tableIdent, SCHEMA).withProperty("key2", "value2").replaceTransaction();
    replaceTxn.commitTransaction();
    table = catalog.loadTable(tableIdent);
    assertThat(table.currentSnapshot()).isNull();
    if (formatVersion == 1) {
        PartitionSpec v1Expected = PartitionSpec.builderFor(table.schema()).alwaysNull("data", "data_bucket").withSpecId(1).build();
        assertThat(table.spec()).as("Table should have a spec with one void field").isEqualTo(v1Expected);
    } else {
        assertThat(table.spec().isUnpartitioned()).as("Table spec must be unpartitioned").isTrue();
    }
    assertThat(table.properties()).containsEntry("key1", "value1").containsEntry("key2", "value2");
