@Test
public void testDeserializeInvalidResponse() {
    // Invalid top-level types
    String jsonInvalidTypeOnRemovedField = "{\"removed\":{\"foo\":true},\"updated\":[\"owner\"],\"missing\":[\"bar\"]}";
    assertThatThrownBy(() -> deserialize(jsonInvalidTypeOnRemovedField)).isInstanceOf(JsonProcessingException.class).hasMessageContaining("Cannot deserialize value of type `java.util.ArrayList<java.lang.String>`");
    String jsonInvalidTypeOnUpdatedField = "{\"updated\":\"owner\",\"missing\":[\"bar\"]}";
    assertThatThrownBy(() -> deserialize(jsonInvalidTypeOnUpdatedField)).isInstanceOf(JsonProcessingException.class).hasMessageContaining("Cannot construct instance of `java.util.ArrayList`");
