@Test
public void testConfigRoute() throws IOException {
    RESTClient testClient = new RESTCatalogAdapter(backendCatalog) {

        @Override
        public <T extends RESTResponse> T get(String path, Map<String, String> queryParams, Class<T> responseType, Map<String, String> headers, Consumer<ErrorResponse> errorHandler) {
            if ("v1/config".equals(path)) {
                return castResponse(responseType, ConfigResponse.builder().withDefaults(ImmutableMap.of(CatalogProperties.CLIENT_POOL_SIZE, "1")).withOverrides(ImmutableMap.of(CatalogProperties.CACHE_ENABLED, "false", CatalogProperties.WAREHOUSE_LOCATION, queryParams.get(CatalogProperties.WAREHOUSE_LOCATION) + "warehouse")).build());
            }
            return super.get(path, queryParams, responseType, headers, errorHandler);
        }
    };
    RESTCatalog restCat = new RESTCatalog((config) -> testClient);
    Map<String, String> initialConfig = ImmutableMap.of(CatalogProperties.URI, "http://localhost:8080", CatalogProperties.CACHE_ENABLED, "true", CatalogProperties.WAREHOUSE_LOCATION, "s3://bucket/");
    restCat.setConf(new Configuration());
    restCat.initialize("prod", initialConfig);
    assertThat(restCat.properties().get(CatalogProperties.CACHE_ENABLED)).as("Catalog properties after initialize should use the server's override properties").isEqualTo("false");
    assertThat(restCat.properties().get(CatalogProperties.CLIENT_POOL_SIZE)).as("Catalog after initialize should use the server's default properties if not specified").isEqualTo("1");
    assertThat(restCat.properties().get(CatalogProperties.WAREHOUSE_LOCATION)).as("Catalog should return final warehouse location").isEqualTo("s3://bucket/warehouse");
    restCat.close();
}

