@Test
public void fullTableNameWithDifferentValues() {
    String uriTypeCatalogName = "thrift://host:port/db.table";
    String namespace = "ns";
    String nameSpaceWithTwoLevels = "ns.l2";
    String tableName = "tbl";
    TableIdentifier tableIdentifier = TableIdentifier.of(namespace, tableName);
    assertThat(CatalogUtil.fullTableName(uriTypeCatalogName, tableIdentifier)).isEqualTo(uriTypeCatalogName + "/" + namespace + "." + tableName);
    tableIdentifier = TableIdentifier.of(nameSpaceWithTwoLevels, tableName);
    assertThat(CatalogUtil.fullTableName(uriTypeCatalogName, tableIdentifier)).isEqualTo(uriTypeCatalogName + "/" + nameSpaceWithTwoLevels + "." + tableName);
    assertThat(CatalogUtil.fullTableName(uriTypeCatalogName + "/", tableIdentifier)).isEqualTo(uriTypeCatalogName + "/" + nameSpaceWithTwoLevels + "." + tableName);
    String nonUriCatalogName = "test.db.catalog";
    assertThat(CatalogUtil.fullTableName(nonUriCatalogName, tableIdentifier)).isEqualTo(nonUriCatalogName + "." + nameSpaceWithTwoLevels + "." + tableName);
    String pathStyleCatalogName = "/test/db";
    assertThat(CatalogUtil.fullTableName(pathStyleCatalogName, tableIdentifier)).isEqualTo(pathStyleCatalogName + "/" + nameSpaceWithTwoLevels + "." + tableName);
}

@Test
public void testRetrySucceedsWithinMaxAttempts() throws Exception {
    int maxRetries = 5;
    int succeedAfterAttempts = 3;
    try (MockClientPoolImpl mockClientPool = new MockClientPoolImpl(2, RetryableException.class, true, maxRetries)) {
        // initial the client pool with a client, so that we can verify the client is replaced
        MockClient firstClient = mockClientPool.newClient();
        mockClientPool.clients().add(firstClient);
        int actions = mockClientPool.run(client -> client.succeedAfter(succeedAfterAttempts));
        assertThat(actions).as("There should be exactly one successful action invocation").isEqualTo(1);
        assertThat(mockClientPool.reconnectionAttempts()).isEqualTo(succeedAfterAttempts - 1);
        assertThat(mockClientPool.clients().peekFirst().equals(firstClient)).isFalse();
    }
}

@Test
public void testRetriesExhaustedAndSurfacesFailure() {
    int maxRetries = 3;
    int succeedAfterAttempts = 5;
    try (MockClientPoolImpl mockClientPool = new MockClientPoolImpl(2, RetryableException.class, true, maxRetries)) {
        assertThatThrownBy(() -> mockClientPool.run(client -> client.succeedAfter(succeedAfterAttempts))).isInstanceOf(RetryableException.class);
        assertThat(mockClientPool.reconnectionAttempts()).isEqualTo(maxRetries);
    }
}

