    String test7_1_expected = "\uD83D\uDE03";
    Comparator<CharSequence> cmp = Literal.of(test1).comparator();
    assertThat(cmp.compare(truncateStringMax(Literal.of(test1), 4).value(), test1)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test1), 7).value(), test1)).as("No truncation required as truncate length is equal to the input size").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test1), 2).value(), test1_2_expected)).as("Output must have two characters and the second character of the input must " + "be incremented").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test1), 3).value(), test1_3_expected)).as("Output must have three characters and the third character of the input must " + "be incremented").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test1), 8).value(), test1)).as("No truncation required as truncate length is greater than the input size").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test2), 8).value(), test2)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test2), 7).value(), test2_7_expected)).as("Output must have seven characters and the seventh character of the input must be incremented").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test3), 3).value(), test3)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test3), 3).value(), test3_3_expected)).as("Output must have three characters and the third character of the input must " + "be incremented. The second perceivable character in this string is actually a glyph. It consists of " + "two unicode characters").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test4), 1).value(), test4)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test4), 1).value(), test4_1_expected)).as("Output must have one character. Since the first character is the max 3 byte " + "UTF-8 character, it should be incremented to the lowest 4 byte UTF-8 character").isEqualTo(0);
    assertThat(truncateStringMax(Literal.of(test5), 1)).as("An upper bound doesn't exist since the first two characters are max UTF-8 characters").isNull();
    assertThat(cmp.compare(truncateStringMax(Literal.of(test6), 2).value(), test6)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test6), 1).value(), test6_2_expected)).as("Test 4 byte UTF-8 character increment. Output must have one character with " + "the first character incremented").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test7), 2).value(), test7)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test7), 2).value(), test7_2_expected)).as("Test input with multiple 4 byte UTF-8 character where the second unicode character should be incremented").isEqualTo(0);
    assertThat(cmp.compare(truncateStringMax(Literal.of(test7), 1).value(), test7_1_expected)).as("Test input with multiple 4 byte UTF-8 character where the first unicode character should be incremented").isEqualTo(0);
}

