    assertThatThrownBy(() -> new Schema(testSchema.asStruct().fields(), ImmutableSet.of(999))).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add fieldId 999 as an identifier field: field does not exist");
    assertThatThrownBy(() -> new Schema(testSchema.asStruct().fields(), ImmutableSet.of(1))).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field id as an identifier field: not a required field");
    assertThatThrownBy(() -> new Schema(testSchema.asStruct().fields(), ImmutableSet.of(2))).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field float as an identifier field: must not be float or double field");
    assertThatThrownBy(() -> new Schema(testSchema.asStruct().fields(), ImmutableSet.of(3))).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field double as an identifier field: must not be float or double field");
    assertThatThrownBy(() -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("unknown").apply()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field unknown as an identifier field: not found in current schema or added columns");
    assertThatThrownBy(() -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("locations").apply()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field locations as an identifier field: not a primitive type field");
    assertThatThrownBy(() -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("data").apply()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field data as an identifier field: not a required field");
    assertThatThrownBy(() -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("locations.key.zip").apply()).isInstanceOf(IllegalArgumentException.class).hasMessageStartingWith("Cannot add field zip as an identifier field: must not be nested in " + SCHEMA.findField("locations"));
    assertThatThrownBy(() -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("points.element.x").apply()).isInstanceOf(IllegalArgumentException.class).hasMessageStartingWith("Cannot add field x as an identifier field: must not be nested in " + SCHEMA.findField("points"));
    Schema newSchema = new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).allowIncompatibleChanges().addRequiredColumn("col_float", Types.FloatType.get()).addRequiredColumn("col_double", Types.DoubleType.get()).addRequiredColumn("new", Types.StructType.of(Types.NestedField.required(SCHEMA_LAST_COLUMN_ID + 4, "fields", Types.ListType.ofRequired(SCHEMA_LAST_COLUMN_ID + 5, Types.StructType.of(Types.NestedField.required(SCHEMA_LAST_COLUMN_ID + 6, "nested", Types.StringType.get())))))).addRequiredColumn("new_map", Types.MapType.ofRequired(SCHEMA_LAST_COLUMN_ID + 8, SCHEMA_LAST_COLUMN_ID + 9, Types.StructType.of(required(SCHEMA_LAST_COLUMN_ID + 10, "key_col", Types.StringType.get())), Types.StructType.of(required(SCHEMA_LAST_COLUMN_ID + 11, "val_col", Types.StringType.get()))), "map of address to coordinate").addRequiredColumn("required_list", Types.ListType.ofRequired(SCHEMA_LAST_COLUMN_ID + 13, Types.StructType.of(required(SCHEMA_LAST_COLUMN_ID + 14, "x", Types.LongType.get()), required(SCHEMA_LAST_COLUMN_ID + 15, "y", Types.LongType.get())))).apply();
    int lastColId = SCHEMA_LAST_COLUMN_ID + 15;
    assertThatThrownBy(() -> new SchemaUpdate(newSchema, lastColId).setIdentifierFields("required_list.element.x").apply()).isInstanceOf(IllegalArgumentException.class).hasMessageStartingWith("Cannot add field x as an identifier field: must not be nested in " + newSchema.findField("required_list"));
    assertThatThrownBy(() -> new SchemaUpdate(newSchema, lastColId).setIdentifierFields("col_double").apply()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field col_double as an identifier field: must not be float or double field");
    assertThatThrownBy(() -> new SchemaUpdate(newSchema, lastColId).setIdentifierFields("col_float").apply()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field col_float as an identifier field: must not be float or double field");
    assertThatThrownBy(() -> new SchemaUpdate(newSchema, lastColId).setIdentifierFields("new_map.value.val_col").apply()).isInstanceOf(IllegalArgumentException.class).hasMessageStartingWith("Cannot add field val_col as an identifier field: must not be nested in " + newSchema.findField("new_map"));
    assertThatThrownBy(() -> new SchemaUpdate(newSchema, lastColId).setIdentifierFields("new.fields.element.nested").apply()).isInstanceOf(IllegalArgumentException.class).hasMessageStartingWith("Cannot add field nested as an identifier field: must not be nested in " + newSchema.findField("new.fields"));
    assertThatThrownBy(() -> new SchemaUpdate(newSchema, lastColId).setIdentifierFields("preferences.feature1").apply()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot add field feature1 as an identifier field: must not be nested in an optional field " + newSchema.findField("preferences"));
}

