    String invalidSnapshotId = "{\"snapshot-id\":\"invalid-snapshot-id\",\"type\":\"not-a-valid-tag-type\"}";
    assertThatThrownBy(() -> SnapshotRefParser.fromJson(invalidSnapshotId)).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot parse to a long value: snapshot-id: \"invalid-snapshot-id\"");
    String invalidTagType = "{\"snapshot-id\":1,\"type\":\"not-a-valid-tag-type\"}";
    assertThatThrownBy(() -> SnapshotRefParser.fromJson(invalidTagType)).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid snapshot ref type: not-a-valid-tag-type");
    String invalidRefAge = "{\"snapshot-id\":1,\"type\":\"tag\",\"max-ref-age-ms\":\"not-a-valid-value\"}";
    assertThatThrownBy(() -> SnapshotRefParser.fromJson(invalidRefAge)).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot parse to a long value: max-ref-age-ms: \"not-a-valid-value\"");
    String invalidSnapshotsToKeep = "{\"snapshot-id\":1,\"type\":\"branch\", " + "\"min-snapshots-to-keep\":\"invalid-number\"}";
    assertThatThrownBy(() -> SnapshotRefParser.fromJson(invalidSnapshotsToKeep)).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot parse to an integer value: min-snapshots-to-keep: \"invalid-number\"");
    String invalidMaxSnapshotAge = "{\"snapshot-id\":1,\"type\":\"branch\", " + "\"max-snapshot-age-ms\":\"invalid-age\"}";
    assertThatThrownBy(() -> SnapshotRefParser.fromJson(invalidMaxSnapshotAge)).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot parse to a long value: max-snapshot-age-ms: \"invalid-age\"");
}

@Test
@SuppressWarnings("MethodLength")
public void testJsonConversion() throws Exception {
    long previousSnapshotId = System.currentTimeMillis() - new Random(1234).nextInt(3600);
    String manifestList = createManifestListWithManifestFile(previousSnapshotId, null, "file:/tmp/manifest1.avro");
    Snapshot previousSnapshot = new BaseSnapshot(0, previousSnapshotId, null, previousSnapshotId, null, null, null, manifestList);
    long currentSnapshotId = System.currentTimeMillis();
    manifestList = createManifestListWithManifestFile(currentSnapshotId, previousSnapshotId, "file:/tmp/manifest2.avro");
    Snapshot currentSnapshot = new BaseSnapshot(0, currentSnapshotId, previousSnapshotId, currentSnapshotId, null, null, 7, manifestList);
    List<HistoryEntry> snapshotLog = ImmutableList.<HistoryEntry>builder().add(new SnapshotLogEntry(previousSnapshot.timestampMillis(), previousSnapshot.snapshotId())).add(new SnapshotLogEntry(currentSnapshot.timestampMillis(), currentSnapshot.snapshotId())).build();
    Schema schema = new Schema(6, Types.NestedField.required(10, "x", Types.StringType.get()));
    Map<String, SnapshotRef> refs = ImmutableMap.of("main", SnapshotRef.branchBuilder(currentSnapshotId).build(), "previous", SnapshotRef.tagBuilder(previousSnapshotId).build(), "test", SnapshotRef.branchBuilder(previousSnapshotId).build());
    List<StatisticsFile> statisticsFiles = ImmutableList.of(new GenericStatisticsFile(11L, "/some/stats/file.puffin", 100, 42, ImmutableList.of(new GenericBlobMetadata("some-stats", 11L, 2, ImmutableList.of(4), ImmutableMap.of()))));
    List<PartitionStatisticsFile> partitionStatisticsFiles = ImmutableList.of(ImmutableGenericPartitionStatisticsFile.builder().snapshotId(11L).path("/some/partition/stats/file.parquet").fileSizeInBytes(42L).build());
    TableMetadata expected = new TableMetadata(null, 2, UUID.randomUUID().toString(), TEST_LOCATION, SEQ_NO, System.currentTimeMillis(), 3, 7, ImmutableList.of(TEST_SCHEMA, schema), 5, ImmutableList.of(SPEC_5), SPEC_5.lastAssignedFieldId(), 3, ImmutableList.of(SORT_ORDER_3), ImmutableMap.of("property", "value"), currentSnapshotId, Arrays.asList(previousSnapshot, currentSnapshot), null, snapshotLog, ImmutableList.of(), refs, statisticsFiles, partitionStatisticsFiles, ImmutableList.of());
    String asJson = TableMetadataParser.toJson(expected);
    TableMetadata metadata = TableMetadataParser.fromJson(asJson);
    assertThat(metadata.formatVersion()).isEqualTo(expected.formatVersion());
    assertThat(metadata.uuid()).isEqualTo(expected.uuid());
    assertThat(metadata.location()).isEqualTo(expected.location());
    assertThat(metadata.lastSequenceNumber()).isEqualTo(expected.lastSequenceNumber());
    assertThat(metadata.lastColumnId()).isEqualTo(expected.lastColumnId());
    assertThat(metadata.currentSchemaId()).isEqualTo(expected.currentSchemaId());
    assertSameSchemaList(expected.schemas(), metadata.schemas());
    assertThat(metadata.spec().toString()).isEqualTo(expected.spec().toString());
    assertThat(metadata.defaultSpecId()).isEqualTo(expected.defaultSpecId());
    assertThat(metadata.specs()).isEqualTo(expected.specs());
    assertThat(metadata.lastAssignedPartitionId()).isEqualTo(expected.spec().lastAssignedFieldId());
    assertThat(metadata.defaultSortOrderId()).isEqualTo(expected.defaultSortOrderId());
    assertThat(metadata.sortOrder()).isEqualTo(expected.sortOrder());
    assertThat(metadata.sortOrders()).isEqualTo(expected.sortOrders());
    assertThat(metadata.properties()).isEqualTo(expected.properties());
    assertThat(metadata.snapshotLog()).isEqualTo(expected.snapshotLog());
    assertThat(metadata.currentSnapshot().snapshotId()).isEqualTo(currentSnapshotId);
    assertThat(metadata.currentSnapshot().parentId()).isEqualTo(previousSnapshotId);
    assertThat(metadata.currentSnapshot().allManifests(ops.io())).isEqualTo(currentSnapshot.allManifests(ops.io()));
    assertThat(metadata.currentSnapshot().schemaId()).isEqualTo(7);
    assertThat(metadata.snapshot(previousSnapshotId).snapshotId()).isEqualTo(previousSnapshotId);
    assertThat(metadata.snapshot(previousSnapshotId).allManifests(ops.io())).isEqualTo(previousSnapshot.allManifests(ops.io()));
    assertThat(metadata.snapshot(previousSnapshotId).schemaId()).isNull();
    assertThat(metadata.statisticsFiles()).isEqualTo(statisticsFiles);
    assertThat(metadata.partitionStatisticsFiles()).isEqualTo(partitionStatisticsFiles);
    assertThat(metadata.refs()).isEqualTo(refs);
}

@Test
public void testBackwardCompat() throws Exception {
    PartitionSpec spec = PartitionSpec.builderFor(TEST_SCHEMA).identity("x").withSpecId(6).build();
    SortOrder sortOrder = SortOrder.unsorted();
    Schema schema = new Schema(TableMetadata.INITIAL_SCHEMA_ID, TEST_SCHEMA.columns());
    long previousSnapshotId = System.currentTimeMillis() - new Random(1234).nextInt(3600);
    String manifestList = createManifestListWithManifestFile(previousSnapshotId, null, "file:/tmp/manifest1.avro");
    Snapshot previousSnapshot = new BaseSnapshot(0, previousSnapshotId, null, previousSnapshotId, null, null, null, manifestList);
    long currentSnapshotId = System.currentTimeMillis();
    manifestList = createManifestListWithManifestFile(currentSnapshotId, previousSnapshotId, "file:/tmp/manifest2.avro");
    Snapshot currentSnapshot = new BaseSnapshot(0, currentSnapshotId, previousSnapshotId, currentSnapshotId, null, null, null, manifestList);
    TableMetadata expected = new TableMetadata(null, 1, null, TEST_LOCATION, 0, System.currentTimeMillis(), 3, TableMetadata.INITIAL_SCHEMA_ID, ImmutableList.of(schema), 6, ImmutableList.of(spec), spec.lastAssignedFieldId(), TableMetadata.INITIAL_SORT_ORDER_ID, ImmutableList.of(sortOrder), ImmutableMap.of("property", "value"), currentSnapshotId, Arrays.asList(previousSnapshot, currentSnapshot), null, ImmutableList.of(), ImmutableList.of(), ImmutableMap.of(), ImmutableList.of(), ImmutableList.of(), ImmutableList.of());
    String asJson = toJsonWithoutSpecAndSchemaList(expected);
    TableMetadata metadata = TableMetadataParser.fromJson(asJson);
    assertThat(metadata.formatVersion()).isEqualTo(expected.formatVersion());
    assertThat(metadata.uuid()).as("Table UUID should not be assigned").isNull();
    assertThat(metadata.location()).isEqualTo(expected.location());
    assertThat(metadata.lastSequenceNumber()).as("Last sequence number should default to 0").isEqualTo(expected.lastSequenceNumber());
    assertThat(metadata.lastColumnId()).isEqualTo(expected.lastColumnId());
    assertThat(metadata.currentSchemaId()).as("Current schema ID should be default to TableMetadata.INITIAL_SCHEMA_ID").isEqualTo(TableMetadata.INITIAL_SCHEMA_ID);
    assertThat(metadata.schemas()).hasSize(1);
    assertThat(metadata.schemas().get(0).asStruct()).isEqualTo(schema.asStruct());
    assertThat(metadata.spec().toString()).isEqualTo(expected.spec().toString());
    assertThat(metadata.defaultSpecId()).isEqualTo(TableMetadata.INITIAL_SPEC_ID);
    assertThat(metadata.specs()).hasSize(1);
    assertThat(metadata.specs()).first().satisfies(partitionSpec -> partitionSpec.compatibleWith(spec));
    assertThat(metadata.specs().get(0).specId()).isEqualTo(TableMetadata.INITIAL_SPEC_ID);
    assertThat(metadata.lastAssignedPartitionId()).isEqualTo(expected.spec().lastAssignedFieldId());
    assertThat(metadata.properties()).isEqualTo(expected.properties());
    assertThat(metadata.snapshotLog()).isEqualTo(expected.snapshotLog());
    assertThat(metadata.currentSnapshot().snapshotId()).isEqualTo(currentSnapshotId);
    assertThat(metadata.currentSnapshot().parentId()).isEqualTo(previousSnapshotId);
    assertThat(metadata.currentSnapshot().allManifests(ops.io())).as("Current snapshot files should match").isEqualTo(currentSnapshot.allManifests(ops.io()));
    assertThat(metadata.currentSnapshot().schemaId()).isNull();
    assertThat(metadata.snapshot(previousSnapshotId).snapshotId()).isEqualTo(previousSnapshotId);
    assertThat(metadata.snapshot(previousSnapshotId).allManifests(ops.io())).isEqualTo(previousSnapshot.allManifests(ops.io()));
    assertThat(metadata.previousFiles()).isEqualTo(expected.previousFiles());
    assertThat(metadata.snapshot(previousSnapshotId).schemaId()).isNull();
}

