@Test
public void testBinPackingLookBack() {
    // lookback state:
    // 1. [5]
    // 2. [5, 1]
    // 3. [5, 1], [5]
    // 4. [5, 1, 1], [5]
    // 5. [5, 1, 1], [5], [5]
    // 6. [5, 1, 1, 1], [5], [5]
    assertThat(pack(list(5, 1, 5, 1, 5, 1), 8)).as("Unlimited look-back: should merge ones into first bin").isEqualTo(list(list(5, 1, 1, 1), list(5), list(5)));
    // lookback state:
    // 1. [5]
    // 2. [5, 1]
    // 3. [5, 1], [5]
    // 4. [5, 1, 1], [5]
    // 5. [5], [5]          ([5, 1, 1] drops out of look-back)
    // 6. [5, 1], [5]
    assertThat(pack(list(5, 1, 5, 1, 5, 1), 8, 2)).as("2 bin look-back: should merge two ones into first bin").isEqualTo(list(list(5, 1, 1), list(5, 1), list(5)));
    // lookback state:
    // 1. [5]
    // 2. [5, 1]
    // 3. [5]               ([5, 1] drops out of look-back)
    // 4. [5, 1]
    // 5. [5]               ([5, 1] #2 drops out of look-back)
    // 6. [5, 1]
    assertThat(pack(list(5, 1, 5, 1, 5, 1), 8, 1)).as("1 bin look-back: should merge ones with fives").isEqualTo(list(list(5, 1), list(5, 1), list(5, 1)));
    assertThat(pack(list(36, 36, 36, 36, 65, 65, 128), 128, 2, true)).as("2 bin look-back: should merge until targetWeight when largestBinFirst is enabled").isEqualTo(list(list(36, 36, 36), list(128), list(36, 65), list(65)));
    assertThat(pack(list(64, 64, 128, 32, 32, 32, 32), 128, 1, true)).as("1 bin look-back: should merge until targetWeight when largestBinFirst is enabled").isEqualTo(list(list(64, 64), list(128), list(32, 32, 32, 32)));
}

