@Test
public void closeParallelIteratorWithoutCompleteIteration() throws IOException, IllegalAccessException, NoSuchFieldException {
    ExecutorService executor = Executors.newFixedThreadPool(1);
    Iterable<CloseableIterable<Integer>> transform = Iterables.transform(Lists.newArrayList(1, 2, 3, 4, 5), item -> new CloseableIterable<Integer>() {

        @Override
        public void close() {
        }

        @Override
        public CloseableIterator<Integer> iterator() {
            return CloseableIterator.withClose(Collections.singletonList(item).iterator());
        }
    });
    ParallelIterable<Integer> parallelIterable = new ParallelIterable<>(transform, executor);
    CloseableIterator<Integer> iterator = parallelIterable.iterator();
    Field queueField = iterator.getClass().getDeclaredField("queue");
    queueField.setAccessible(true);
    ConcurrentLinkedQueue<?> queue = (ConcurrentLinkedQueue<?>) queueField.get(iterator);
    assertThat(iterator.hasNext()).isTrue();
    assertThat(iterator.next()).isNotNull();
    Awaitility.await("Queue is populated").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> queueHasElements(iterator, queue));
    iterator.close();
    Awaitility.await("Queue is cleared").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> assertThat(queue).isEmpty());
}

@Test
public void closeMoreDataParallelIteratorWithoutCompleteIteration() throws IOException, IllegalAccessException, NoSuchFieldException {
    ExecutorService executor = Executors.newFixedThreadPool(1);
    Iterator<Integer> integerIterator = new Iterator<Integer>() {

        private int number = 1;

        @Override
        public boolean hasNext() {
            if (number > 1000) {
                return false;
            }
            number++;
            return true;
        }

        @Override
        public Integer next() {
            try {
                // sleep to control number generate rate
                Thread.sleep(10);
            } catch (InterruptedException e) {
                // Sleep interrupted, we ignore it!
            }
            return number;
        }
    };
    Iterable<CloseableIterable<Integer>> transform = Iterables.transform(Lists.newArrayList(1), item -> new CloseableIterable<Integer>() {

        @Override
        public void close() {
        }

        @Override
        public CloseableIterator<Integer> iterator() {
            return CloseableIterator.withClose(integerIterator);
        }
    });
    ParallelIterable<Integer> parallelIterable = new ParallelIterable<>(transform, executor);
    CloseableIterator<Integer> iterator = parallelIterable.iterator();
    Field queueField = iterator.getClass().getDeclaredField("queue");
    queueField.setAccessible(true);
    ConcurrentLinkedQueue<?> queue = (ConcurrentLinkedQueue<?>) queueField.get(iterator);
    assertThat(iterator.hasNext()).isTrue();
    assertThat(iterator.next()).isNotNull();
    Awaitility.await("Queue is populated").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> queueHasElements(iterator, queue));
    iterator.close();
    Awaitility.await("Queue is cleared").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> assertThat(queue).as("Queue is not empty after cleaning").isEmpty());
}

@Test
public void limitQueueSize() throws IOException, IllegalAccessException, NoSuchFieldException {
    List<Iterable<Integer>> iterables = ImmutableList.of(() -> IntStream.range(0, 100).iterator(), () -> IntStream.range(0, 100).iterator(), () -> IntStream.range(0, 100).iterator());
    Multiset<Integer> expectedValues = IntStream.range(0, 100).boxed().flatMap(i -> Stream.of(i, i, i)).collect(ImmutableMultiset.toImmutableMultiset());
    int maxQueueSize = 20;
    ExecutorService executor = Executors.newCachedThreadPool();
    ParallelIterable<Integer> parallelIterable = new ParallelIterable<>(iterables, executor, maxQueueSize);
    CloseableIterator<Integer> iterator = parallelIterable.iterator();
    Field queueField = iterator.getClass().getDeclaredField("queue");
    queueField.setAccessible(true);
    ConcurrentLinkedQueue<?> queue = (ConcurrentLinkedQueue<?>) queueField.get(iterator);
    Multiset<Integer> actualValues = HashMultiset.create();
    while (iterator.hasNext()) {
        assertThat(queue).as("iterator internal queue").hasSizeLessThanOrEqualTo(maxQueueSize + iterables.size());
        actualValues.add(iterator.next());
    }
    assertThat(actualValues).as("multiset of values returned by the iterator").isEqualTo(expectedValues);
    iterator.close();
    executor.shutdownNow();
}

