    assertThat(ViewMetadata.Builder.updateHistory(ImmutableList.of(three, two, one, two, three), ImmutableSet.of(2, 3))).containsExactly(two, three);
    // two was an invalid entry in the history, so all previous elements are removed
    assertThat(ViewMetadata.Builder.updateHistory(ImmutableList.of(one, two, three, one, three), ImmutableSet.of(1, 3))).containsExactly(three, one, three);
}

