@Test
public void viewVersionHistoryIsCorrectlyRetained() {
    Map<String, String> properties = ImmutableMap.of(ViewProperties.VERSION_HISTORY_SIZE, "2");
    ViewVersion viewVersionOne = newViewVersion(1, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(2, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(3, "select count(*) as count from ns.tbl");
    ViewMetadata originalViewMetadata = ViewMetadata.builder().setProperties(properties).setLocation("location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(viewVersionOne).addVersion(viewVersionTwo).addVersion(viewVersionThree).setCurrentVersionId(3).build();
    assertThat(originalViewMetadata.versions()).hasSize(3).containsExactlyInAnyOrder(viewVersionOne, viewVersionTwo, viewVersionThree);
    assertThat(originalViewMetadata.history()).hasSize(1).first().extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    // rebuild the metadata to expire older versions
    ViewMetadata viewMetadata = ViewMetadata.buildFrom(originalViewMetadata).build();
    assertThat(viewMetadata.versions()).hasSize(2).// there is no requirement about the order of versions
    containsExactlyInAnyOrder(viewVersionThree, viewVersionTwo);
    assertThat(viewMetadata.history()).hasSize(1).first().extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    ViewMetadata updated = ViewMetadata.buildFrom(viewMetadata).setCurrentVersionId(2).build();
    assertThat(updated.versions()).hasSize(2).containsExactlyInAnyOrder(viewVersionTwo, viewVersionThree);
    assertThat(updated.history()).hasSize(2).element(0).extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    assertThat(updated.history()).element(1).extracting(ViewHistoryEntry::versionId).isEqualTo(2);
    ViewMetadata view = ViewMetadata.buildFrom(updated).setCurrentVersionId(3).build();
    assertThat(view.versions()).hasSize(2).containsExactlyInAnyOrder(viewVersionTwo, viewVersionThree);
    assertThat(view.history()).hasSize(3).element(0).extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    assertThat(view.history()).element(1).extracting(ViewHistoryEntry::versionId).isEqualTo(2);
    assertThat(view.history()).element(2).extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    // viewVersionId 1 has been removed from versions, so this should fail
    assertThatThrownBy(() -> ViewMetadata.buildFrom(view).setCurrentVersionId(1).build()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set current version to unknown version: 1");
}

