    ViewVersion trinoAndSpark = ImmutableViewVersion.builder().versionId(3).schemaId(0).timestampMillis(System.currentTimeMillis()).defaultNamespace(Namespace.empty()).addRepresentations(trino).addRepresentations(spark).build();
    // add all different view versions and set it to using sparkOnly
