    setCurrentVersionId(trinoAndSpark.versionId()).setCurrentVersionId(sparkOnly.versionId()).setCurrentVersionId(trinoOnly.versionId()).build()).isInstanceOf(IllegalStateException.class).hasMessage("Cannot replace view due to loss of view dialects (replace.drop-dialect.allowed=false):\n" + "Previous dialects: [spark]\n" + "New dialects: [trino]");
