    // updates are ignored
    setCurrentVersionId(sparkOnly.versionId()).setCurrentVersionId(trinoOnly.versionId()).build()).isInstanceOf(IllegalStateException.class).hasMessage("Cannot replace view due to loss of view dialects (replace.drop-dialect.allowed=false):\n" + "Previous dialects: [trino, spark]\n" + "New dialects: [trino]");
}

@Test
public void droppingDialectAllowedAndThenDisallowed() {
    Schema schema = new Schema(Types.NestedField.required(1, "x", Types.LongType.get()));
    ViewRepresentation spark = ImmutableSQLViewRepresentation.builder().dialect("spark").sql("select * from tbl").build();
    ViewRepresentation trino = ImmutableSQLViewRepresentation.builder().dialect("trino").sql("select * from tbl").build();
    ViewMetadata metadata = ViewMetadata.builder().setLocation("custom-location").addSchema(schema).setCurrentVersion(ImmutableViewVersion.builder().versionId(1).schemaId(0).timestampMillis(System.currentTimeMillis()).defaultNamespace(Namespace.empty()).addRepresentations(spark).build(), schema).build();
    ViewMetadata updated = ViewMetadata.buildFrom(metadata).setCurrentVersion(ImmutableViewVersion.builder().versionId(1).schemaId(0).timestampMillis(System.currentTimeMillis()).defaultNamespace(Namespace.empty()).// this drops spark and is allowed
    addRepresentations(trino).build(), schema).setProperties(ImmutableMap.of(ViewProperties.REPLACE_DROP_DIALECT_ALLOWED, "true")).build();
    assertThat(updated.currentVersion().representations()).containsExactly(trino);
    assertThatThrownBy(() -> ViewMetadata.buildFrom(updated).// switches back to spark and isn't allowed
    setCurrentVersionId(1).setProperties(ImmutableMap.of(ViewProperties.REPLACE_DROP_DIALECT_ALLOWED, "false")).build()).isInstanceOf(IllegalStateException.class).hasMessage("Cannot replace view due to loss of view dialects (replace.drop-dialect.allowed=false):\n" + "Previous dialects: [trino]\n" + "New dialects: [spark]");
}

