    String location = Paths.get(tmp.toString(), fileName).toString();
    OutputFile outputFile = org.apache.iceberg.Files.localOutput(location);
    Schema schema = new Schema(Types.NestedField.required(1, "x", Types.LongType.get()));
    ViewVersion viewVersion = ImmutableViewVersion.builder().schemaId(0).versionId(1).timestampMillis(23L).putSummary("user", "some-user").defaultNamespace(Namespace.of("ns")).build();
    ViewMetadata metadata = ViewMetadata.buildFrom(ViewMetadata.builder().setLocation(location).addSchema(schema).setProperties(ImmutableMap.of(ViewProperties.METADATA_COMPRESSION, codec.name())).addVersion(viewVersion).setCurrentVersionId(1).build()).setMetadataLocation(outputFile.location()).build();
    ViewMetadataParser.write(metadata, outputFile);
    assertThat(Codec.GZIP == codec).isEqualTo(isCompressed(location));
