@ParameterizedTest(name = ".createOrReplace() = {arguments}")
@ValueSource(booleans = { false, true })
public void createOrReplaceView(boolean useCreateOrReplace) {
    TableIdentifier identifier = TableIdentifier.of("ns", "view");
    if (requiresNamespaceCreate()) {
        catalog().createNamespace(identifier.namespace());
    }
    assertThat(catalog().viewExists(identifier)).as("View should not exist").isFalse();
    ViewBuilder viewBuilder = catalog().buildView(identifier).withSchema(SCHEMA).withDefaultNamespace(identifier.namespace()).withQuery("spark", "select * from ns.tbl").withProperty("prop1", "val1").withProperty("prop2", "val2");
    View view = useCreateOrReplace ? viewBuilder.createOrReplace() : viewBuilder.create();
    assertThat(catalog().viewExists(identifier)).as("View should exist").isTrue();
    assertThat(((BaseView) view).operations().current().metadataFileLocation()).isNotNull();
    ViewVersion viewVersion = view.currentVersion();
    assertThat(viewVersion.representations()).containsExactly(ImmutableSQLViewRepresentation.builder().sql("select * from ns.tbl").dialect("spark").build());
    viewBuilder = catalog().buildView(identifier).withSchema(OTHER_SCHEMA).withDefaultNamespace(identifier.namespace()).withQuery("trino", "select count(*) from ns.tbl").withProperty("replacedProp1", "val1").withProperty("replacedProp2", "val2").withProperty(ViewProperties.REPLACE_DROP_DIALECT_ALLOWED, "true");
    View replacedView = useCreateOrReplace ? viewBuilder.createOrReplace() : viewBuilder.replace();
    // validate replaced view settings
    assertThat(replacedView.name()).isEqualTo(ViewUtil.fullViewName(catalog().name(), identifier));
    assertThat(((BaseView) replacedView).operations().current().metadataFileLocation()).isNotNull();
    assertThat(replacedView.properties()).containsEntry("prop1", "val1").containsEntry("prop2", "val2").containsEntry("replacedProp1", "val1").containsEntry("replacedProp2", "val2");
    assertThat(replacedView.history()).hasSize(2).first().extracting(ViewHistoryEntry::versionId).isEqualTo(1);
    assertThat(replacedView.history()).element(1).extracting(ViewHistoryEntry::versionId).isEqualTo(2);
    assertThat(replacedView.schema().schemaId()).isEqualTo(1);
    assertThat(replacedView.schema().asStruct()).isEqualTo(OTHER_SCHEMA.asStruct());
    assertThat(replacedView.schemas()).hasSize(2).containsKey(0).containsKey(1);
    ViewVersion replacedViewVersion = replacedView.currentVersion();
    assertThat(replacedView.versions()).hasSize(2).containsExactly(viewVersion, replacedViewVersion);
    assertThat(replacedViewVersion).isNotNull();
    assertThat(replacedViewVersion.versionId()).isEqualTo(2);
    assertThat(replacedViewVersion.schemaId()).isEqualTo(1);
    assertThat(replacedViewVersion.operation()).isEqualTo("replace");
    assertThat(replacedViewVersion.representations()).containsExactly(ImmutableSQLViewRepresentation.builder().sql("select count(*) from ns.tbl").dialect("trino").build());
    assertThat(catalog().dropView(identifier)).isTrue();
    assertThat(catalog().viewExists(identifier)).as("View should not exist").isFalse();
}

