@Test
public void testMapOfStructStructProjection() {
    DataGenerator dataGenerator = new DataGenerators.MapOfStructStruct();
    Schema schema = dataGenerator.icebergSchema();
    // Project id only.
    Schema idOnly = schema.select("row_id");
    assertThat(idOnly.columns().size()).isGreaterThan(0);
    generateAndValidate(schema, idOnly);
    // Project map only.
    Schema mapOnly = schema.select("map");
    assertThat(mapOnly.columns().size()).isGreaterThan(0);
    generateAndValidate(schema, mapOnly);
    // Project all.
    generateAndValidate(schema, schema);
    // Project partial map key.
    Schema partialMapKey = new Schema(Types.NestedField.optional(2, "map", Types.MapType.ofOptional(101, 102, Types.StructType.of(Types.NestedField.required(201, "key", Types.LongType.get())), Types.StructType.of(Types.NestedField.required(203, "value", Types.LongType.get()), Types.NestedField.required(204, "valueData", Types.StringType.get())))));
    assertThatThrownBy(() -> generateAndValidate(schema, partialMapKey)).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot project a partial map key or value struct.");
    // Project partial map key.
    Schema partialMapValue = new Schema(Types.NestedField.optional(2, "map", Types.MapType.ofOptional(101, 102, Types.StructType.of(Types.NestedField.required(201, "key", Types.LongType.get()), Types.NestedField.required(202, "keyData", Types.StringType.get())), Types.StructType.of(Types.NestedField.required(203, "value", Types.LongType.get())))));
    assertThatThrownBy(() -> generateAndValidate(schema, partialMapValue)).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot project a partial map key or value struct.");
    GenericRowData rowData = dataGenerator.generateFlinkRowData();
    GenericRowData copyRowData = dataGenerator.generateFlinkRowData();
    // modify the map field value
    GenericRowData otherRowData = GenericRowData.of(StringData.fromString("other_row_id_value"), new GenericMapData(ImmutableMap.of(GenericRowData.of(1L, StringData.fromString("other_key_data")), GenericRowData.of(1L, StringData.fromString("other_value_data")))));
    testEqualsAndHashCode(schema, idOnly, rowData, copyRowData, otherRowData);
    testEqualsAndHashCode(schema, mapOnly, rowData, copyRowData, otherRowData);
    testEqualsAndHashCode(schema, schema, rowData, copyRowData, otherRowData);
    GenericRowData rowDataNullOptionalFields = GenericRowData.of(StringData.fromString("row_id_value"), new GenericMapData(ImmutableMap.of(GenericRowData.of(1L, null), GenericRowData.of(1L, null))));
    GenericRowData copyRowDataNullOptionalFields = GenericRowData.of(StringData.fromString("row_id_value"), new GenericMapData(ImmutableMap.of(GenericRowData.of(1L, null), GenericRowData.of(1L, null))));
    // modify the map field value
    GenericRowData otherRowDataNullOptionalFields = GenericRowData.of(StringData.fromString("other_row_id_value"), new GenericMapData(ImmutableMap.of(GenericRowData.of(2L, null), GenericRowData.of(2L, null))));
    testEqualsAndHashCode(schema, idOnly, rowDataNullOptionalFields, copyRowDataNullOptionalFields, otherRowDataNullOptionalFields);
    testEqualsAndHashCode(schema, mapOnly, rowDataNullOptionalFields, copyRowDataNullOptionalFields, otherRowDataNullOptionalFields);
    testEqualsAndHashCode(schema, schema, rowDataNullOptionalFields, copyRowDataNullOptionalFields, otherRowDataNullOptionalFields);
}

