@Test
public void testRenamedAddedField() throws Exception {
    Schema schema = new Schema(Types.NestedField.required(1, "a", Types.LongType.get()), Types.NestedField.required(2, "b", Types.LongType.get()), Types.NestedField.required(3, "d", Types.LongType.get()));
    RowData row = GenericRowData.of(100L, 200L, 300L);
    Schema renamedAdded = new Schema(Types.NestedField.optional(1, "a", Types.LongType.get()), Types.NestedField.optional(2, "b", Types.LongType.get()), Types.NestedField.optional(3, "c", Types.LongType.get()), Types.NestedField.optional(4, "d", Types.LongType.get()));
    RowData projected = writeAndRead("rename_and_add_column_projection", schema, renamedAdded, row);
    assertThat(projected.getLong(0)).as("Should contain the correct value in column 1").isEqualTo(100L);
    assertThat(projected.getLong(1)).as("Should contain the correct value in column 2").isEqualTo(200L);
    assertThat(projected.getLong(2)).as("Should contain the correct value in column 1").isEqualTo(300L);
    assertThat(projected.isNullAt(3)).as("Should contain empty value on new column 4").isTrue();
}

