    MapDataStatistics checkpoint1Subtask1DataStatistic = new MapDataStatistics();
    checkpoint1Subtask1DataStatistic.add(keyA);
    checkpoint1Subtask1DataStatistic.add(keyA);
    checkpoint1Subtask1DataStatistic.add(keyB);
    DataStatisticsEvent<MapDataStatistics, Map<SortKey, Long>> checkpoint1Subtask1DataStatisticEvent = DataStatisticsEvent.create(1, checkpoint1Subtask1DataStatistic, statisticsSerializer);
    // Receive data statistics from all subtasks at checkpoint 1
    AggregatedStatistics<MapDataStatistics, Map<SortKey, Long>> completedStatistics = aggregatedStatisticsTracker.updateAndCheckCompletion(1, checkpoint1Subtask1DataStatisticEvent);
    assertThat(completedStatistics).isNotNull();
    assertThat(completedStatistics.checkpointId()).isEqualTo(1);
    MapDataStatistics globalDataStatistics = (MapDataStatistics) completedStatistics.dataStatistics();
    assertThat((long) globalDataStatistics.statistics().get(keyA)).isEqualTo(checkpoint1Subtask0DataStatistic.statistics().get(keyA) + checkpoint1Subtask1DataStatistic.statistics().get(keyA));
    assertThat((long) globalDataStatistics.statistics().get(keyB)).isEqualTo(checkpoint1Subtask0DataStatistic.statistics().get(keyB) + checkpoint1Subtask1DataStatistic.statistics().get(keyB));
    assertThat(aggregatedStatisticsTracker.inProgressStatistics().checkpointId()).isEqualTo(completedStatistics.checkpointId() + 1);
    MapDataStatistics checkpoint2Subtask0DataStatistic = new MapDataStatistics();
    checkpoint2Subtask0DataStatistic.add(keyA);
    DataStatisticsEvent<MapDataStatistics, Map<SortKey, Long>> checkpoint2Subtask0DataStatisticEvent = DataStatisticsEvent.create(2, checkpoint2Subtask0DataStatistic, statisticsSerializer);
    assertThat(aggregatedStatisticsTracker.updateAndCheckCompletion(0, checkpoint2Subtask0DataStatisticEvent)).isNull();
    assertThat(completedStatistics.checkpointId()).isEqualTo(1);
    MapDataStatistics checkpoint2Subtask1DataStatistic = new MapDataStatistics();
    checkpoint2Subtask1DataStatistic.add(keyB);
    DataStatisticsEvent<MapDataStatistics, Map<SortKey, Long>> checkpoint2Subtask1DataStatisticEvent = DataStatisticsEvent.create(2, checkpoint2Subtask1DataStatistic, statisticsSerializer);
    // Receive data statistics from all subtasks at checkpoint 2
    completedStatistics = aggregatedStatisticsTracker.updateAndCheckCompletion(1, checkpoint2Subtask1DataStatisticEvent);
    assertThat(completedStatistics).isNotNull();
    assertThat(completedStatistics.checkpointId()).isEqualTo(2);
    assertThat(aggregatedStatisticsTracker.inProgressStatistics().checkpointId()).isEqualTo(completedStatistics.checkpointId() + 1);
}

