@Test
public void testBoundedTableFactory() {
    List<List<Row>> dataSet = ImmutableList.of(ImmutableList.of(insertRow(1, "aaa"), deleteRow(1, "aaa"), insertRow(1, "bbb"), insertRow(2, "aaa"), deleteRow(2, "aaa"), insertRow(2, "bbb")), ImmutableList.of(updateBeforeRow(2, "bbb"), updateAfterRow(2, "ccc"), deleteRow(2, "ccc"), insertRow(2, "ddd")), ImmutableList.of(deleteRow(1, "bbb"), insertRow(1, "ccc"), deleteRow(1, "ccc"), insertRow(1, "ddd")));
    String dataId = BoundedTableFactory.registerDataSet(dataSet);
    sql("CREATE TABLE %s(id INT, data STRING) WITH ('connector'='BoundedSource', 'data-id'='%s')", tableName, dataId);
    List<Row> rowSet = dataSet.stream().flatMap(Streams::stream).collect(Collectors.toList());
    assertThat(sql("SELECT * FROM %s", tableName)).isEqualTo(rowSet);
    assertThat(sql("SELECT * FROM %s WHERE data='aaa'", tableName)).isEqualTo(rowSet.stream().filter(r -> Objects.equals(r.getField(1), "aaa")).collect(Collectors.toList()));
}

