@Test
public void testEvenlyDividableWithClosingFileCost() {
    MapRangePartitioner partitioner = new MapRangePartitioner(TestFixtures.SCHEMA, SORT_ORDER, mapDataStatistics, 5.0);
    int numPartitions = 8;
    // target subtask weight is 100 before close file cost factored in.
    // close file cost is 5 = 5% * 100.
    // key weights before and after close file cost factored in
    // before:     350, 230, 120, 40, 10, 10, 10, 10, 10, 10
    // close-cost:  20,  15,  10,  5,  5,  5,  5,  5,  5,  5
    // after:      370, 245, 130, 45, 15, 15, 15, 15, 15, 15
    // target subtask weight with close cost per subtask is 110 (880/8)
    Map<SortKey, MapRangePartitioner.KeyAssignment> expectedAssignment = ImmutableMap.of(SORT_KEYS[0], new MapRangePartitioner.KeyAssignment(ImmutableList.of(0, 1, 2, 3), ImmutableList.of(110L, 110L, 110L, 40L), 5L), SORT_KEYS[1], new MapRangePartitioner.KeyAssignment(ImmutableList.of(3, 4, 5), ImmutableList.of(70L, 110L, 65L), 5L), SORT_KEYS[2], new MapRangePartitioner.KeyAssignment(ImmutableList.of(5, 6), ImmutableList.of(45L, 85L), 5L), SORT_KEYS[3], new MapRangePartitioner.KeyAssignment(ImmutableList.of(6, 7), ImmutableList.of(25L, 20L), 5L), SORT_KEYS[4], new MapRangePartitioner.KeyAssignment(ImmutableList.of(7), ImmutableList.of(15L), 5L), SORT_KEYS[5], new MapRangePartitioner.KeyAssignment(ImmutableList.of(7), ImmutableList.of(15L), 5L), SORT_KEYS[6], new MapRangePartitioner.KeyAssignment(ImmutableList.of(7), ImmutableList.of(15L), 5L), SORT_KEYS[7], new MapRangePartitioner.KeyAssignment(ImmutableList.of(7), ImmutableList.of(15L), 5L), SORT_KEYS[8], new MapRangePartitioner.KeyAssignment(ImmutableList.of(7), ImmutableList.of(15L), 5L), SORT_KEYS[9], new MapRangePartitioner.KeyAssignment(ImmutableList.of(7), ImmutableList.of(15L), 5L));
    Map<SortKey, MapRangePartitioner.KeyAssignment> actualAssignment = partitioner.assignment(numPartitions);
    assertThat(actualAssignment).isEqualTo(expectedAssignment);
    // key: subtask id
    // value pair: first is the assigned weight (excluding close file cost) for the subtask,
    // second is the number of keys assigned to the subtask
    Map<Integer, Pair<Long, Integer>> expectedAssignmentInfo = ImmutableMap.of(0, Pair.of(105L, 1), 1, Pair.of(105L, 1), 2, Pair.of(105L, 1), 3, Pair.of(100L, 2), 4, Pair.of(105L, 1), 5, Pair.of(100L, 2), 6, Pair.of(100L, 2), 7, Pair.of(75L, 7));
    Map<Integer, Pair<Long, Integer>> actualAssignmentInfo = partitioner.assignmentInfo();
    assertThat(actualAssignmentInfo).isEqualTo(expectedAssignmentInfo);
    Map<Integer, Pair<AtomicLong, Set<RowData>>> partitionResults = runPartitioner(partitioner, numPartitions);
    validatePartitionResults(expectedAssignmentInfo, partitionResults, 5.0);
}

