    // before:     350, 230, 120, 40, 10, 10, 10, 10, 10, 10
    // close-cost:  20,  15,  10,  5,  5,  5,  5,  5,  5,  5
    // after:      370, 245, 130, 45, 15, 15, 15, 15, 15, 15
    // target subtask weight per subtask is 98 ceiling(880/9)
    Map<SortKey, MapRangePartitioner.KeyAssignment> expectedAssignment = ImmutableMap.of(SORT_KEYS[0], new MapRangePartitioner.KeyAssignment(ImmutableList.of(0, 1, 2, 3), ImmutableList.of(98L, 98L, 98L, 76L), 5L), SORT_KEYS[1], new MapRangePartitioner.KeyAssignment(ImmutableList.of(3, 4, 5, 6), ImmutableList.of(22L, 98L, 98L, 27L), 5L), SORT_KEYS[2], new MapRangePartitioner.KeyAssignment(ImmutableList.of(6, 7), ImmutableList.of(71L, 59L), 5L), SORT_KEYS[3], new MapRangePartitioner.KeyAssignment(ImmutableList.of(7, 8), ImmutableList.of(39L, 6L), 5L), SORT_KEYS[4], new MapRangePartitioner.KeyAssignment(ImmutableList.of(8), ImmutableList.of(15L), 5L), SORT_KEYS[5], new MapRangePartitioner.KeyAssignment(ImmutableList.of(8), ImmutableList.of(15L), 5L), SORT_KEYS[6], new MapRangePartitioner.KeyAssignment(ImmutableList.of(8), ImmutableList.of(15L), 5L), SORT_KEYS[7], new MapRangePartitioner.KeyAssignment(ImmutableList.of(8), ImmutableList.of(15L), 5L), SORT_KEYS[8], new MapRangePartitioner.KeyAssignment(ImmutableList.of(8), ImmutableList.of(15L), 5L), SORT_KEYS[9], new MapRangePartitioner.KeyAssignment(ImmutableList.of(8), ImmutableList.of(15L), 5L));
    Map<SortKey, MapRangePartitioner.KeyAssignment> actualAssignment = partitioner.assignment(numPartitions);
    assertThat(actualAssignment).isEqualTo(expectedAssignment);
    // key: subtask id
    // value pair: first is the assigned weight for the subtask, second is the number of keys
    // assigned to the subtask
    Map<Integer, Pair<Long, Integer>> expectedAssignmentInfo = ImmutableMap.of(0, Pair.of(93L, 1), 1, Pair.of(93L, 1), 2, Pair.of(93L, 1), 3, Pair.of(88L, 2), 4, Pair.of(93L, 1), 5, Pair.of(93L, 1), 6, Pair.of(88L, 2), 7, Pair.of(88L, 2), 8, Pair.of(61L, 7));
    Map<Integer, Pair<Long, Integer>> actualAssignmentInfo = partitioner.assignmentInfo();
    assertThat(actualAssignmentInfo).isEqualTo(expectedAssignmentInfo);
    Map<Integer, Pair<AtomicLong, Set<RowData>>> partitionResults = runPartitioner(partitioner, numPartitions);
    // drift threshold is high for non-dividable scenario with close cost
    validatePartitionResults(expectedAssignmentInfo, partitionResults, 10.0);
}

