@Test
public void testReadingFromBranch() throws Exception {
    String branch = "b1";
    GenericAppenderHelper dataAppender = new GenericAppenderHelper(TABLE_EXTENSION.table(), FileFormat.PARQUET, temporaryFolder);
    List<Record> batchBase = RandomGenericData.generate(TABLE_EXTENSION.table().schema(), 2, randomSeed.incrementAndGet());
    dataAppender.appendToTable(batchBase);
    // create branch
    TABLE_EXTENSION.table().manageSnapshots().createBranch(branch, TABLE_EXTENSION.table().currentSnapshot().snapshotId()).commit();
    // snapshot1 to branch
    List<Record> batch1 = RandomGenericData.generate(TABLE_EXTENSION.table().schema(), 2, randomSeed.incrementAndGet());
    dataAppender.appendToTable(branch, batch1);
    // snapshot2 to branch
    List<Record> batch2 = RandomGenericData.generate(TABLE_EXTENSION.table().schema(), 2, randomSeed.incrementAndGet());
    dataAppender.appendToTable(branch, batch2);
    List<Record> branchExpectedRecords = Lists.newArrayList();
    branchExpectedRecords.addAll(batchBase);
    branchExpectedRecords.addAll(batch1);
    branchExpectedRecords.addAll(batch2);
    // reads from branch: it should contain the first snapshot (before the branch creation) followed
    // by the next 2 snapshots added
    ScanContext scanContext = ScanContext.builder().streaming(true).monitorInterval(Duration.ofMillis(10L)).startingStrategy(StreamingStartingStrategy.TABLE_SCAN_THEN_INCREMENTAL).useBranch(branch).build();
    try (CloseableIterator<Row> iter = createStream(scanContext).executeAndCollect(getClass().getSimpleName())) {
        List<Row> resultMain = waitForResult(iter, 6);
        TestHelpers.assertRecords(resultMain, branchExpectedRecords, TABLE_EXTENSION.table().schema());
        // snapshot3 to branch
        List<Record> batch3 = RandomGenericData.generate(TABLE_EXTENSION.table().schema(), 2, randomSeed.incrementAndGet());
        dataAppender.appendToTable(branch, batch3);
        List<Row> result3 = waitForResult(iter, 2);
        TestHelpers.assertRecords(result3, batch3, TABLE_EXTENSION.table().schema());
        // snapshot4 to branch
        List<Record> batch4 = RandomGenericData.generate(TABLE_EXTENSION.table().schema(), 2, randomSeed.incrementAndGet());
        dataAppender.appendToTable(branch, batch4);
        List<Row> result4 = waitForResult(iter, 2);
        TestHelpers.assertRecords(result4, batch4, TABLE_EXTENSION.table().schema());
    }
    // read only from main branch. Should contain only the first snapshot
    scanContext = ScanContext.builder().streaming(true).monitorInterval(Duration.ofMillis(10L)).startingStrategy(StreamingStartingStrategy.TABLE_SCAN_THEN_INCREMENTAL).build();
    try (CloseableIterator<Row> iter = createStream(scanContext).executeAndCollect(getClass().getSimpleName())) {
        List<Row> resultMain = waitForResult(iter, 2);
        TestHelpers.assertRecords(resultMain, batchBase, TABLE_EXTENSION.table().schema());
        List<Record> batchMain2 = RandomGenericData.generate(TABLE_EXTENSION.table().schema(), 2, randomSeed.incrementAndGet());
        dataAppender.appendToTable(batchMain2);
        resultMain = waitForResult(iter, 2);
        TestHelpers.assertRecords(resultMain, batchMain2, TABLE_EXTENSION.table().schema());
    }
}

