@Test
public void testTwoLevelList() throws IOException {
    Schema schema = new Schema(optional(1, "arraybytes", Types.ListType.ofRequired(3, Types.BinaryType.get())), optional(2, "topbytes", Types.BinaryType.get()));
    org.apache.avro.Schema avroSchema = AvroSchemaUtil.convert(schema.asStruct());
    File testFile = File.createTempFile("junit", null, temp.toFile());
    assertThat(testFile.delete()).isTrue();
    ParquetWriter<GenericRecord> writer = AvroParquetWriter.<GenericRecord>builder(new Path(testFile.toURI())).withDataModel(GenericData.get()).withSchema(avroSchema).config("parquet.avro.add-list-element-records", "true").config("parquet.avro.write-old-list-structure", "true").build();
    GenericRecordBuilder recordBuilder = new GenericRecordBuilder(avroSchema);
    List<ByteBuffer> expectedByteList = Lists.newArrayList();
    byte[] expectedByte = { 0x00, 0x01 };
    ByteBuffer expectedBinary = ByteBuffer.wrap(expectedByte);
    expectedByteList.add(expectedBinary);
    recordBuilder.set("arraybytes", expectedByteList);
    recordBuilder.set("topbytes", expectedBinary);
    GenericData.Record expectedRecord = recordBuilder.build();
    writer.write(expectedRecord);
    writer.close();
    try (CloseableIterable<RowData> reader = Parquet.read(Files.localInput(testFile)).project(schema).createReaderFunc(type -> FlinkParquetReaders.buildReader(schema, type)).build()) {
        Iterator<RowData> rows = reader.iterator();
        assertThat(rows).hasNext();
        RowData rowData = rows.next();
        assertThat(rowData.getArray(0).getBinary(0)).isEqualTo(expectedByte);
        assertThat(rowData.getBinary(1)).isEqualTo(expectedByte);
        assertThat(rows).isExhausted();
    }
}

