@Test
void testMaxReadBack() {
    sql.exec("CREATE TABLE %s (id int, data varchar)", TABLE_NAME);
    sql.exec("INSERT INTO %s VALUES (1, 'a')", TABLE_NAME);
    sql.exec("INSERT INTO %s VALUES (2, 'b')", TABLE_NAME);
    sql.exec("INSERT INTO %s VALUES (3, 'c')", TABLE_NAME);
    TableLoader tableLoader = sql.tableLoader(TABLE_NAME);
    tableLoader.open();
    MonitorSource.TableChangeIterator iterator = new MonitorSource.TableChangeIterator(tableLoader, null, 1);
    // For a single maxReadBack we only get a single change
    assertThat(iterator.next().commitNum()).isEqualTo(1);
    iterator = new MonitorSource.TableChangeIterator(tableLoader, null, 2);
    // Expecting 2 commits/snapshots for maxReadBack=2
    assertThat(iterator.next().commitNum()).isEqualTo(2);
    iterator = new MonitorSource.TableChangeIterator(tableLoader, null, Long.MAX_VALUE);
    // For maxReadBack Long.MAX_VALUE we get every change
    assertThat(iterator.next().commitNum()).isEqualTo(3);
}

@Test
void testSkipReplace() {
    sql.exec("CREATE TABLE %s (id int, data varchar)", TABLE_NAME);
    sql.exec("INSERT INTO %s VALUES (1, 'a')", TABLE_NAME);
    TableLoader tableLoader = sql.tableLoader(TABLE_NAME);
    tableLoader.open();
    MonitorSource.TableChangeIterator iterator = new MonitorSource.TableChangeIterator(tableLoader, null, Long.MAX_VALUE);
    // Read the current snapshot
    assertThat(iterator.next().commitNum()).isEqualTo(1);
    // Create a DataOperations.REPLACE snapshot
    Table table = tableLoader.loadTable();
    DataFile dataFile = table.snapshots().iterator().next().addedDataFiles(table.io()).iterator().next();
    RewriteFiles rewrite = tableLoader.loadTable().newRewrite();
    // Replace the file with itself for testing purposes
    rewrite.deleteFile(dataFile);
    rewrite.addFile(dataFile);
    rewrite.commit();
    // Check that the rewrite is ignored
    assertThat(iterator.next()).isEqualTo(EMPTY_EVENT);
}

@ParameterizedTest
@EnumSource(StatisticsType.class)
public void receiveNewerStatisticsEvent(StatisticsType type) {
    AggregatedStatisticsTracker tracker = createTracker(type);
    StatisticsEvent checkpoint1Subtask0StatisticsEvent = createStatisticsEvent(type, TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("a"));
    CompletedStatistics completedStatistics = tracker.updateAndCheckCompletion(0, checkpoint1Subtask0StatisticsEvent);
    assertThat(completedStatistics).isNull();
    assertThat(tracker.aggregationsPerCheckpoint().keySet()).containsExactlyInAnyOrder(1L);
    AggregatedStatisticsTracker.Aggregation aggregation = tracker.aggregationsPerCheckpoint().get(1L);
    assertThat(aggregation.currentType()).isEqualTo(StatisticsUtil.collectType(type));
    if (StatisticsUtil.collectType(type) == StatisticsType.Map) {
        assertThat(aggregation.mapStatistics()).isEqualTo(ImmutableMap.of(CHAR_KEYS.get("a"), 1L));
    } else {
