public void testSingleFileWithMultipleBatches() throws Exception {
    List<Record> records = RandomGenericData.generate(TestFixtures.SCHEMA, 5, 1);
    FileScanTask fileTask = ReaderUtil.createFileTask(records, File.createTempFile("junit", null, temporaryFolder.toFile()), FILE_FORMAT, appenderFactory);
