        out.writeObject(manifest);
        out.writeObject(manifest.copy());
        out.writeObject(GenericManifestFile.copyOf(manifest).build());
    }
    try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
        for (int i = 0; i < 3; i += 1) {
