/**
 * Verify that Nessie always returns the globally-current global-content w/ only DMLs.
 */
@Test
public void verifyStateMovesForDML() throws Exception {
    //  1. initialize view
    View icebergView = catalog.loadView(VIEW_IDENTIFIER);
    icebergView.replaceVersion().withQuery("spark", "some query").withSchema(SCHEMA).withDefaultNamespace(VIEW_IDENTIFIER.namespace()).commit();
    //  2. create 2nd branch
    String testCaseBranch = "verify-global-moving";
    api.createReference().sourceRefName(BRANCH).reference(Branch.of(testCaseBranch, catalog.currentHash())).create();
    IcebergView contentInitialMain = getView(BRANCH, KEY);
    IcebergView contentInitialBranch = getView(testCaseBranch, KEY);
    View viewInitialMain = catalog.loadView(VIEW_IDENTIFIER);
    // verify view-metadata-location + version-id
    assertThat(contentInitialMain).as("global-contents + snapshot-id equal on both branches in Nessie").isEqualTo(contentInitialBranch);
    assertThat(viewInitialMain.currentVersion().versionId()).isEqualTo(2);
    //  3. modify view in "main" branch
    icebergView.replaceVersion().withQuery("trino", "some other query").withSchema(SCHEMA).withDefaultNamespace(VIEW_IDENTIFIER.namespace()).commit();
    IcebergView contentsAfter1Main = getView(KEY);
    IcebergView contentsAfter1Branch = getView(testCaseBranch, KEY);
    View viewAfter1Main = catalog.loadView(VIEW_IDENTIFIER);
    //  --> assert getValue() against both branches returns the updated metadata-location
    // verify view-metadata-location
    assertThat(contentInitialMain.getMetadataLocation()).describedAs("metadata-location must change on %s", BRANCH).isNotEqualTo(contentsAfter1Main.getMetadataLocation());
    assertThat(contentInitialBranch.getMetadataLocation()).describedAs("metadata-location must not change on %s", testCaseBranch).isEqualTo(contentsAfter1Branch.getMetadataLocation());
    assertThat(contentsAfter1Main).extracting(IcebergView::getSchemaId).describedAs("schema ID must be same across branches").isEqualTo(contentsAfter1Branch.getSchemaId());
    // verify updates
    assertThat(viewAfter1Main.currentVersion().versionId()).isEqualTo(3);
    assertThat(((SQLViewRepresentation) viewAfter1Main.currentVersion().representations().get(0)).dialect()).isEqualTo("trino");
    //  4. modify view in "main" branch again
    icebergView.replaceVersion().withQuery("flink", "some query").withSchema(SCHEMA).withDefaultNamespace(VIEW_IDENTIFIER.namespace()).commit();
    IcebergView contentsAfter2Main = getView(KEY);
    IcebergView contentsAfter2Branch = getView(testCaseBranch, KEY);
    View viewAfter2Main = catalog.loadView(VIEW_IDENTIFIER);
    //  --> assert getValue() against both branches returns the updated metadata-location
    // verify view-metadata-location
    assertThat(contentsAfter2Main.getVersionId()).isEqualTo(4);
    assertThat(contentsAfter2Main.getMetadataLocation()).describedAs("metadata-location must change on %s", BRANCH).isNotEqualTo(contentsAfter1Main.getMetadataLocation());
    assertThat(contentsAfter1Main.getVersionId()).isEqualTo(3);
    assertThat(contentsAfter2Branch.getMetadataLocation()).describedAs("on-reference-state must not change on %s", testCaseBranch).isEqualTo(contentsAfter1Branch.getMetadataLocation());
    assertThat(viewAfter2Main.currentVersion().versionId()).isEqualTo(4);
    assertThat(((SQLViewRepresentation) viewAfter2Main.currentVersion().representations().get(0)).dialect()).isEqualTo("flink");
}

