@Test
public void testPrimitiveTypes() {
    Schema schema = new Schema(required(1, "int", Types.IntegerType.get()), required(2, "long", Types.LongType.get()), required(3, "float", Types.FloatType.get()), required(4, "double", Types.DoubleType.get()), required(5, "boolean", Types.BooleanType.get()), required(6, "string", Types.StringType.get()), required(7, "date", Types.DateType.get()), required(8, "time", Types.TimeType.get()), required(9, "tsTz", Types.TimestampType.withZone()), required(10, "ts", Types.TimestampType.withoutZone()), required(11, "decimal", Types.DecimalType.of(38, 2)), required(12, "float2", Types.FloatType.get()), required(13, "double2", Types.DoubleType.get()));
    Expression expr = and(and(and(lessThan("int", 1), lessThanOrEqual("long", 100)), and(greaterThan("float", 5.0), greaterThanOrEqual("double", 500.0))), and(and(equal("boolean", true), notEqual("string", "test")), and(in("decimal", BigDecimal.valueOf(-12345, 2), BigDecimal.valueOf(12345, 2)), notIn("time", 100L, 200L))), and(isNaN("float2"), notNaN("double2")));
    Expression boundFilter = Binder.bind(schema.asStruct(), expr, true);
    SearchArgument expected = SearchArgumentFactory.newBuilder().startAnd().lessThan("`int`", Type.LONG, 1L).lessThanEquals("`long`", Type.LONG, 100L).startNot().lessThanEquals("`float`", Type.FLOAT, 5.0).end().startNot().lessThan("`double`", Type.FLOAT, 500.0).end().equals("`boolean`", Type.BOOLEAN, true).startOr().isNull("`string`", Type.STRING).startNot().equals("`string`", Type.STRING, "test").end().end().in("`decimal`", Type.DECIMAL, new HiveDecimalWritable("-123.45"), new HiveDecimalWritable("123.45")).startOr().isNull("`time`", Type.LONG).startNot().in("`time`", Type.LONG, 100L, 200L).end().end().equals("`float2`", Type.FLOAT, Double.NaN).startOr().isNull("`double2`", Type.FLOAT).startNot().equals("`double2`", Type.FLOAT, Double.NaN).end().end().end().build();
    SearchArgument actual = ExpressionToSearchArgument.convert(boundFilter, ORCSchemaUtil.convert(schema));
    assertThat(actual.toString()).isEqualTo(expected.toString());
}

@Test
public void testTimezoneSensitiveTypes() {
    TimeZone currentTz = TimeZone.getDefault();
    try {
        for (String timezone : new String[] { "America/New_York", "Asia/Kolkata", "UTC/Greenwich" }) {
            TimeZone.setDefault(TimeZone.getTimeZone(timezone));
            OffsetDateTime tsTzPredicate = OffsetDateTime.parse("2019-10-02T00:47:28.207366Z");
            OffsetDateTime tsPredicate = OffsetDateTime.parse("1968-01-16T13:07:59.048625Z");
            OffsetDateTime epoch = Instant.ofEpochSecond(0).atOffset(ZoneOffset.UTC);
            Schema schema = new Schema(required(1, "date", Types.DateType.get()), required(2, "tsTz", Types.TimestampType.withZone()), required(3, "ts", Types.TimestampType.withoutZone()));
            Expression expr = and(and(equal("date", 10L), equal("tsTz", ChronoUnit.MICROS.between(epoch, tsTzPredicate))), equal("ts", ChronoUnit.MICROS.between(epoch, tsPredicate)));
            Expression boundFilter = Binder.bind(schema.asStruct(), expr, true);
            SearchArgument expected = SearchArgumentFactory.newBuilder().startAnd().equals("`date`", Type.DATE, Date.valueOf(LocalDate.parse("1970-01-11", DateTimeFormatter.ISO_LOCAL_DATE))).equals("`tsTz`", Type.TIMESTAMP, Timestamp.from(tsTzPredicate.toInstant())).equals("`ts`", Type.TIMESTAMP, Timestamp.from(tsPredicate.toInstant())).end().build();
            SearchArgument actual = ExpressionToSearchArgument.convert(boundFilter, ORCSchemaUtil.convert(schema));
            assertThat(actual.toString()).isEqualTo(expected.toString());
        }
    } finally {
        TimeZone.setDefault(currentTz);
    }
}

