    ImmutableMap<String, String> properties = ImmutableMap.of(TableProperties.DELETE_ORC_STRIPE_SIZE_BYTES, String.valueOf(stripeSizeBytes), TableProperties.DELETE_ORC_BLOCK_SIZE_BYTES, String.valueOf(blockSizeBytes), TableProperties.DELETE_ORC_COMPRESSION, codecAsString, TableProperties.DELETE_ORC_COMPRESSION_STRATEGY, strategyAsString, TableProperties.DEFAULT_FILE_FORMAT, FileFormat.ORC.name());
    String warehouse = folder.getAbsolutePath();
    String tablePath = warehouse.concat("/test");
    assertThat(new File(tablePath).mkdir()).as("Should create the table path correctly.").isTrue();
    PartitionSpec spec = PartitionSpec.unpartitioned();
    Table table = new HadoopTables().create(SCHEMA, spec, properties, tablePath);
    assertThat(testFile.delete()).isTrue();
    EqualityDeleteWriter<Object> deleteWriter = ORC.writeDeletes(Files.localOutput(testFile)).forTable(table).equalityFieldIds(1).createWriterFunc(GenericOrcWriter::buildWriter).buildEqualityWriter();
    DynFields.BoundField<OrcFileAppender<Record>> writer = DynFields.builder().hiddenImpl(deleteWriter.getClass(), "appender").build(deleteWriter);
    OrcFileAppender<Record> orcFileAppender = writer.get();
    DynFields.BoundField<Configuration> confField = DynFields.builder().hiddenImpl(orcFileAppender.getClass(), "conf").build(orcFileAppender);
    Configuration configuration = confField.get();
    assertThat(OrcConf.BLOCK_SIZE.getLong(configuration)).isEqualTo(blockSizeBytes);
    assertThat(OrcConf.STRIPE_SIZE.getLong(configuration)).isEqualTo(stripeSizeBytes);
    assertThat(OrcConf.COMPRESS.getString(configuration)).isEqualTo(codecAsString);
    assertThat(OrcConf.COMPRESSION_STRATEGY.getString(configuration)).isEqualTo(strategyAsString);
    assertThat(configuration.get(TableProperties.DEFAULT_FILE_FORMAT)).isEqualTo(FileFormat.ORC.name());
}

