        for (int i = 0; i < records.size(); i += 1) {
            int pos = i * 3 + 2;
            writer.write(positionDelete.set(deletePath, pos, null));
            expectedDeleteRecords.add(posDelete.copy(ImmutableMap.of("file_path", deletePath, "pos", (long) pos)));
        }
    }
    DeleteFile metadata = deleteWriter.toDeleteFile();
    assertThat(metadata.format()).as("Format should be Parquet").isEqualTo(FileFormat.PARQUET);
    assertThat(metadata.content()).as("Should be position deletes").isEqualTo(FileContent.POSITION_DELETES);
    assertThat(metadata.recordCount()).as("Record count should be correct").isEqualTo(records.size());
    assertThat(metadata.partition().size()).as("Partition should be empty").isEqualTo(0);
    assertThat(metadata.keyMetadata()).as("Key metadata should be null").isNull();
    List<Record> deletedRecords;
    try (CloseableIterable<Record> reader = Parquet.read(out.toInputFile()).project(deleteSchema).createReaderFunc(fileSchema -> GenericParquetReaders.buildReader(deleteSchema, fileSchema)).build()) {
        deletedRecords = Lists.newArrayList(reader);
    }
    assertThat(deletedRecords).as("Deleted records should match expected").isEqualTo(expectedDeleteRecords);
}

