@Test
public void testSchemaDoesntExistNoSchemaFoundException() throws SQLException {
    when(mockResultSet.next()).// The Database exists check should pass, followed by Error code 2003 for Schema exists
    thenReturn(true).thenReturn(false).thenThrow(new SQLException("Schema does not exist", "2000", 2003, null)).// The Database exists check should pass, followed by Error code 2043 for Schema exists
    thenReturn(true).thenReturn(false).thenThrow(new SQLException("Schema does not exist, or operation cannot be performed", "2000", 2043, null)).// The Database exists check should pass, followed by Error code 2001 for Schema exists
    thenReturn(true).thenReturn(false).thenThrow(new SQLException("Schema does not exist or not authorized", "2000", 2001, null));
    when(mockResultSet.getString("name")).thenReturn("DB1").thenReturn("SCHEMA1");
    when(mockResultSet.getString("database_name")).thenReturn("DB1");
    // Error code 2003
    assertThat(snowflakeClient.schemaExists(SnowflakeIdentifier.ofSchema("DB_1", "SCHEMA_2"))).isFalse();
    // Error code 2043
    assertThat(snowflakeClient.schemaExists(SnowflakeIdentifier.ofSchema("DB_1", "SCHEMA_2"))).isFalse();
    // Error code 2001
    assertThat(snowflakeClient.schemaExists(SnowflakeIdentifier.ofSchema("DB_1", "SCHEMA_2"))).isFalse();
}

