@Test
public void testGetS3TableMetadata() throws SQLException {
    when(mockResultSet.next()).thenReturn(true);
    when(mockResultSet.getString("METADATA")).thenReturn("{\"metadataLocation\":\"s3://tab1/metadata/v3.metadata.json\",\"status\":\"success\"}");
    SnowflakeTableMetadata actualMetadata = snowflakeClient.loadTableMetadata(SnowflakeIdentifier.ofTable("DB_1", "SCHEMA_1", "TABLE_1"));
    verify(mockQueryHarness).query(eq(mockConnection), eq("SELECT SYSTEM$GET_ICEBERG_TABLE_INFORMATION(?) AS METADATA"), any(JdbcSnowflakeClient.ResultSetParser.class), eq("DB_1.SCHEMA_1.TABLE_1"));
    SnowflakeTableMetadata expectedMetadata = new SnowflakeTableMetadata("s3://tab1/metadata/v3.metadata.json", "s3://tab1/metadata/v3.metadata.json", "success", null);
    assertThat(actualMetadata).isEqualTo(expectedMetadata);
}

