@Test
public void testCompareToFileList() throws IOException, InterruptedException {
    Table table = TABLES.create(SCHEMA, PartitionSpec.unpartitioned(), Maps.newHashMap(), tableLocation);
    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(1, "AAAAAAAAAA", "AAAA"));
    Dataset<Row> df = spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1);
    df.select("c1", "c2", "c3").write().format("iceberg").mode("append").save(tableLocation);
    df.select("c1", "c2", "c3").write().format("iceberg").mode("append").save(tableLocation);
    Path dataPath = new Path(tableLocation + "/data");
    FileSystem fs = dataPath.getFileSystem(spark.sessionState().newHadoopConf());
    List<FilePathLastModifiedRecord> validFiles = Arrays.stream(fs.listStatus(dataPath, HiddenPathFilter.get())).filter(FileStatus::isFile).map(file -> new FilePathLastModifiedRecord(file.getPath().toString(), new Timestamp(file.getModificationTime()))).collect(Collectors.toList());
    Assert.assertEquals("Should be 2 valid files", 2, validFiles.size());
    df.write().mode("append").parquet(tableLocation + "/data");
    List<FilePathLastModifiedRecord> allFiles = Arrays.stream(fs.listStatus(dataPath, HiddenPathFilter.get())).filter(FileStatus::isFile).map(file -> new FilePathLastModifiedRecord(file.getPath().toString(), new Timestamp(file.getModificationTime()))).collect(Collectors.toList());
    Assert.assertEquals("Should be 3 files", 3, allFiles.size());
    List<FilePathLastModifiedRecord> invalidFiles = Lists.newArrayList(allFiles);
    invalidFiles.removeAll(validFiles);
    List<String> invalidFilePaths = invalidFiles.stream().map(FilePathLastModifiedRecord::getFilePath).collect(Collectors.toList());
    Assert.assertEquals("Should be 1 invalid file", 1, invalidFiles.size());
    // sleep for 1 second to ensure files will be old enough
    waitUntilAfter(System.currentTimeMillis());
    SparkActions actions = SparkActions.get();
    Dataset<Row> compareToFileList = spark.createDataFrame(allFiles, FilePathLastModifiedRecord.class).withColumnRenamed("filePath", "file_path").withColumnRenamed("lastModified", "last_modified");
    DeleteOrphanFiles.Result result1 = actions.deleteOrphanFiles(table).compareToFileList(compareToFileList).deleteWith(s -> {
    }).execute();
    Assert.assertTrue("Default olderThan interval should be safe", Iterables.isEmpty(result1.orphanFileLocations()));
    DeleteOrphanFiles.Result result2 = actions.deleteOrphanFiles(table).compareToFileList(compareToFileList).olderThan(System.currentTimeMillis()).deleteWith(s -> {
    }).execute();
    Assert.assertEquals("Action should find 1 file", invalidFilePaths, result2.orphanFileLocations());
    Assert.assertTrue("Invalid file should be present", fs.exists(new Path(invalidFilePaths.get(0))));
    DeleteOrphanFiles.Result result3 = actions.deleteOrphanFiles(table).compareToFileList(compareToFileList).olderThan(System.currentTimeMillis()).execute();
    Assert.assertEquals("Action should delete 1 file", invalidFilePaths, result3.orphanFileLocations());
    Assert.assertFalse("Invalid file should not be present", fs.exists(new Path(invalidFilePaths.get(0))));
    List<ThreeColumnRecord> expectedRecords = Lists.newArrayList();
    expectedRecords.addAll(records);
    expectedRecords.addAll(records);
    Dataset<Row> resultDF = spark.read().format("iceberg").load(tableLocation);
    List<ThreeColumnRecord> actualRecords = resultDF.as(Encoders.bean(ThreeColumnRecord.class)).collectAsList();
    Assert.assertEquals("Rows must match", expectedRecords, actualRecords);
    List<FilePathLastModifiedRecord> outsideLocationMockFiles = Lists.newArrayList(new FilePathLastModifiedRecord("/tmp/mock1", new Timestamp(0L)));
    Dataset<Row> compareToFileListWithOutsideLocation = spark.createDataFrame(outsideLocationMockFiles, FilePathLastModifiedRecord.class).withColumnRenamed("filePath", "file_path").withColumnRenamed("lastModified", "last_modified");
    DeleteOrphanFiles.Result result4 = actions.deleteOrphanFiles(table).compareToFileList(compareToFileListWithOutsideLocation).deleteWith(s -> {
    }).execute();
    Assert.assertEquals("Action should find nothing", Lists.newArrayList(), result4.orphanFileLocations());
}

@Test
public void testRemoveOrphanFilesWithStatisticFiles() throws Exception {
    Table table = TABLES.create(SCHEMA, PartitionSpec.unpartitioned(), ImmutableMap.of(TableProperties.FORMAT_VERSION, "2"), tableLocation);
    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(1, "AAAAAAAAAA", "AAAA"));
    Dataset<Row> df = spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1);
    df.select("c1", "c2", "c3").write().format("iceberg").mode("append").save(tableLocation);
    table.refresh();
    long snapshotId = table.currentSnapshot().snapshotId();
    long snapshotSequenceNumber = table.currentSnapshot().sequenceNumber();
    File statsLocation = new File(new URI(tableLocation)).toPath().resolve("data").resolve("some-stats-file").toFile();
    StatisticsFile statisticsFile;
    try (PuffinWriter puffinWriter = Puffin.write(Files.localOutput(statsLocation)).build()) {
        puffinWriter.add(new Blob("some-blob-type", ImmutableList.of(1), snapshotId, snapshotSequenceNumber, ByteBuffer.wrap("blob content".getBytes(StandardCharsets.UTF_8))));
        puffinWriter.finish();
        statisticsFile = new GenericStatisticsFile(snapshotId, statsLocation.toString(), puffinWriter.fileSize(), puffinWriter.footerSize(), puffinWriter.writtenBlobsMetadata().stream().map(GenericBlobMetadata::from).collect(ImmutableList.toImmutableList()));
    }
    Transaction transaction = table.newTransaction();
    transaction.updateStatistics().setStatistics(snapshotId, statisticsFile).commit();
    transaction.commitTransaction();
    SparkActions.get().deleteOrphanFiles(table).olderThan(System.currentTimeMillis() + 1000).execute();
    assertThat(statsLocation.exists()).as("stats file should exist").isTrue();
    assertThat(statsLocation.length()).as("stats file length").isEqualTo(statisticsFile.fileSizeInBytes());
    transaction = table.newTransaction();
    transaction.updateStatistics().removeStatistics(statisticsFile.snapshotId()).commit();
    transaction.commitTransaction();
    DeleteOrphanFiles.Result result = SparkActions.get().deleteOrphanFiles(table).olderThan(System.currentTimeMillis() + 1000).execute();
    Iterable<String> orphanFileLocations = result.orphanFileLocations();
    assertThat(orphanFileLocations).as("Should be orphan files").hasSize(1);
    assertThat(Iterables.getOnlyElement(orphanFileLocations)).as("Deleted file").isEqualTo(statsLocation.toURI().toString());
    assertThat(statsLocation.exists()).as("stats file should be deleted").isFalse();
}

