    writeAndValidate(new Schema(Lists.newArrayList(SUPPORTED_PRIMITIVES.field("id"), SUPPORTED_PRIMITIVES.field("data"))), 10, 0L, RandomData.DEFAULT_NULL_PERCENTAGE, true, 2, record -> {
        if (record.get("data") != null) {
            record.put("data", Strings.padEnd((String) record.get("data"), 512, 'a'));
        } else {
            record.put("data", Strings.padEnd("", 512, 'a'));
        }
        return record;
    });
}

