@Test
public void testIncrementalScanOptions() throws IOException {
    String tableLocation = temp.newFolder("iceberg-table").toString();
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.unpartitioned();
    Map<String, String> options = Maps.newHashMap();
    Table table = tables.create(SCHEMA, spec, options, tableLocation);
    List<SimpleRecord> expectedRecords = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"), new SimpleRecord(4, "d"));
    for (SimpleRecord record : expectedRecords) {
        Dataset<Row> originalDf = spark.createDataFrame(Lists.newArrayList(record), SimpleRecord.class);
        originalDf.select("id", "data").write().format("iceberg").mode("append").save(tableLocation);
    }
    List<Long> snapshotIds = SnapshotUtil.currentAncestorIds(table);
    // start-snapshot-id and snapshot-id are both configured.
    assertThatThrownBy(() -> {
        spark.read().format("iceberg").option("snapshot-id", snapshotIds.get(3).toString()).option("start-snapshot-id", snapshotIds.get(3).toString()).load(tableLocation).explain();
    }).as("Check both start-snapshot-id and snapshot-id are configured").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot set start-snapshot-id and end-snapshot-id for incremental scans");
    // end-snapshot-id and as-of-timestamp are both configured.
    assertThatThrownBy(() -> {
        spark.read().format("iceberg").option(SparkReadOptions.AS_OF_TIMESTAMP, Long.toString(table.snapshot(snapshotIds.get(3)).timestampMillis())).option("end-snapshot-id", snapshotIds.get(2).toString()).load(tableLocation).explain();
    }).as("Check both start-snapshot-id and snapshot-id are configured").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot set start-snapshot-id and end-snapshot-id for incremental scans");
    // only end-snapshot-id is configured.
    assertThatThrownBy(() -> {
        spark.read().format("iceberg").option("end-snapshot-id", snapshotIds.get(2).toString()).load(tableLocation).explain();
    }).as("Check both start-snapshot-id and snapshot-id are configured").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot set only end-snapshot-id for incremental scans");
    // test (1st snapshot, current snapshot] incremental scan.
    List<SimpleRecord> result = spark.read().format("iceberg").option("start-snapshot-id", snapshotIds.get(3).toString()).load(tableLocation).orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Records should match", expectedRecords.subList(1, 4), result);
    // test (2nd snapshot, 3rd snapshot] incremental scan.
    Dataset<Row> resultDf = spark.read().format("iceberg").option("start-snapshot-id", snapshotIds.get(2).toString()).option("end-snapshot-id", snapshotIds.get(1).toString()).load(tableLocation);
    List<SimpleRecord> result1 = resultDf.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Records should match", expectedRecords.subList(2, 3), result1);
    Assert.assertEquals("Unprocessed count should match record count", 1, resultDf.count());
}

