    expected.addAll(deletesA.first().stream().map(d -> toRow.apply(d, deletesA.second())).collect(Collectors.toList()));
    expected.addAll(deletesB.first().stream().map(d -> toRow.apply(d, deletesB.second())).collect(Collectors.toList()));
    // Sort and compare
    Comparator<Object[]> comp = (o1, o2) -> {
        int result = Integer.compare((int) o1[0], (int) o2[0]);
        if (result != 0) {
            return result;
        } else {
            return ((String) o1[2]).compareTo((String) o2[2]);
        }
    };
    actual.sort(comp);
    expected.sort(comp);
    assertEquals("Position Delete table should contain expected rows", expected, actual);
    dropTable(tableName);
}

