@Test
public void testSnapshotSelectionByBranchWithSchemaChange() throws IOException {
    String tableLocation = temp.newFolder("iceberg-table").toString();
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.unpartitioned();
    Table table = tables.create(SCHEMA, spec, tableLocation);
    // produce the first snapshot
    List<SimpleRecord> firstBatchRecords = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> firstDf = spark.createDataFrame(firstBatchRecords, SimpleRecord.class);
    firstDf.select("id", "data").write().format("iceberg").mode("append").save(tableLocation);
    table.manageSnapshots().createBranch("branch", table.currentSnapshot().snapshotId()).commit();
    Dataset<Row> branchSnapshotResult = spark.read().format("iceberg").option("branch", "branch").load(tableLocation);
    List<SimpleRecord> branchSnapshotRecords = branchSnapshotResult.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    List<SimpleRecord> expectedRecords = Lists.newArrayList();
    expectedRecords.addAll(firstBatchRecords);
    Assert.assertEquals("Current snapshot rows should match", expectedRecords, branchSnapshotRecords);
    // Deleting a column to indicate schema change
    table.updateSchema().deleteColumn("data").commit();
    // The data should not have the deleted column
    assertThat(spark.read().format("iceberg").option("branch", "branch").load(tableLocation).orderBy("id").collectAsList()).containsExactly(RowFactory.create(1), RowFactory.create(2), RowFactory.create(3));
    // re-introducing the column should not let the data re-appear
    table.updateSchema().addColumn("data", Types.StringType.get()).commit();
    assertThat(spark.read().format("iceberg").option("branch", "branch").load(tableLocation).orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList()).containsExactly(new SimpleRecord(1, null), new SimpleRecord(2, null), new SimpleRecord(3, null));
}

@Test
public void testWritingToBranchAfterSchemaChange() throws IOException {
    String tableLocation = temp.newFolder("iceberg-table").toString();
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.unpartitioned();
    Table table = tables.create(SCHEMA, spec, tableLocation);
