    Assert.assertEquals("Current snapshot rows should match", expectedRecords, branchSnapshotRecords);
    // Deleting and add a new column of the same type to indicate schema change
    table.updateSchema().deleteColumn("data").addColumn("zip", Types.IntegerType.get()).commit();
    assertThat(spark.read().format("iceberg").option("branch", "branch").load(tableLocation).orderBy("id").collectAsList()).containsExactly(RowFactory.create(1, null), RowFactory.create(2, null), RowFactory.create(3, null));
