    List<Row> records = Lists.newArrayList(RowFactory.create(4, 12345), RowFactory.create(5, 54321), RowFactory.create(6, 67890));
    Dataset<Row> dataFrame = spark.createDataFrame(records, SparkSchemaUtil.convert(new Schema(optional(1, "id", Types.IntegerType.get()), optional(2, "zip", Types.IntegerType.get()))));
    dataFrame.select("id", "zip").write().format("iceberg").option("branch", "branch").mode("append").save(tableLocation);
    assertThat(spark.read().format("iceberg").option("branch", "branch").load(tableLocation).collectAsList()).hasSize(6).contains(RowFactory.create(1, null), RowFactory.create(2, null), RowFactory.create(3, null)).containsAll(records);
