@Test
public void testCommitUnknownException() throws IOException {
    File parent = temp.newFolder(format.toString());
    File location = new File(parent, "commitunknown");
    String targetLocation = locationWithBranch(location);
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.builderFor(SCHEMA).identity("data").build();
    Table table = tables.create(SCHEMA, spec, location.toString());
    List<SimpleRecord> records = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.select("id", "data").write().format("iceberg").option(SparkWriteOptions.WRITE_FORMAT, format.toString()).mode(SaveMode.Append).save(location.toString());
    createBranch(table);
    table.refresh();
    List<SimpleRecord> records2 = Lists.newArrayList(new SimpleRecord(4, "d"), new SimpleRecord(5, "e"), new SimpleRecord(6, "f"));
    Dataset<Row> df2 = spark.createDataFrame(records2, SimpleRecord.class);
    AppendFiles append = table.newFastAppend();
    if (branch != null) {
        append.toBranch(branch);
    }
    AppendFiles spyAppend = spy(append);
    doAnswer(invocation -> {
        append.commit();
        throw new CommitStateUnknownException(new RuntimeException("Datacenter on Fire"));
    }).when(spyAppend).commit();
    Table spyTable = spy(table);
    when(spyTable.newAppend()).thenReturn(spyAppend);
    SparkTable sparkTable = new SparkTable(spyTable, false);
    String manualTableName = "unknown_exception";
    ManualSource.setTable(manualTableName, sparkTable);
    // Although an exception is thrown here, write and commit have succeeded
    assertThatThrownBy(() -> df2.select("id", "data").sort("data").write().format("org.apache.iceberg.spark.source.ManualSource").option(ManualSource.TABLE_NAME, manualTableName).mode(SaveMode.Append).save(targetLocation)).as("Should throw a Commit State Unknown Exception").isInstanceOf(SparkException.class).hasMessageContaining("Writing job aborted").cause().isInstanceOf(CommitStateUnknownException.class).hasMessageContaining("Datacenter on Fire");
    // Since write and commit succeeded, the rows should be readable
    Dataset<Row> result = spark.read().format("iceberg").load(targetLocation);
    List<SimpleRecord> actual = result.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Number of rows should match", records.size() + records2.size(), actual.size());
    assertThat(actual).describedAs("Result rows should match").containsExactlyInAnyOrder(ImmutableList.<SimpleRecord>builder().addAll(records).addAll(records2).build().toArray(new SimpleRecord[0]));
}

