    DataFile dataFile = DataFiles.builder(table.spec()).withPath(temp.newFile().toString()).withFileSizeInBytes(10).withRecordCount(1).withFormat(FileFormat.PARQUET).build();
    table.newRowDelta().addRows(dataFile).addDeletes(eqDeletes).commit();
