public void testDateAndTimestampWithPartition() {
    sql("CREATE TABLE %s (id bigint, data string, d date, ts timestamp) USING iceberg PARTITIONED BY (id)", tableName);
    sql("INSERT INTO %s VALUES (1, '1', date('2021-11-10'), null)," + "(1, '2', date('2021-11-11'), timestamp('2021-11-11 22:22:22')), " + "(2, '3', date('2021-11-12'), timestamp('2021-11-12 22:22:22')), " + "(2, '4', date('2021-11-13'), timestamp('2021-11-13 22:22:22')), " + "(3, '5', null, timestamp('2021-11-14 22:22:22')), " + "(3, '6', date('2021-11-14'), null)", tableName);
    String select = "SELECT max(d), min(d), count(d), max(ts), min(ts), count(ts) FROM %s";
    List<Object[]> explain = sql("EXPLAIN " + select, tableName);
    String explainString = explain.get(0)[0].toString().toLowerCase(Locale.ROOT);
    boolean explainContainsPushDownAggregates = false;
    if (explainString.contains("max(d)") && explainString.contains("min(d)") && explainString.contains("count(d)") && explainString.contains("max(ts)") && explainString.contains("min(ts)") && explainString.contains("count(ts)")) {
        explainContainsPushDownAggregates = true;
    }
    Assert.assertTrue("explain should contain the pushed down aggregates", explainContainsPushDownAggregates);
    List<Object[]> actual = sql(select, tableName);
    List<Object[]> expected = Lists.newArrayList();
    expected.add(new Object[] { Date.valueOf("2021-11-14"), Date.valueOf("2021-11-10"), 5L, Timestamp.valueOf("2021-11-14 22:22:22.0"), Timestamp.valueOf("2021-11-11 22:22:22.0"), 4L });
    assertEquals("min/max/count push down", expected, actual);
}

