@Test
public void testJoinsWithMultipleTransformTypes() throws NoSuchTableException {
    String createTableStmt = "CREATE TABLE %s (" + "  id BIGINT, int_col INT, date_col1 DATE, date_col2 DATE, date_col3 DATE," + "  timestamp_col TIMESTAMP, string_col STRING, dep STRING)" + "USING iceberg " + "PARTITIONED BY (" + "  years(date_col1), months(date_col2), days(date_col3), hours(timestamp_col), " + "  bucket(8, int_col), dep)" + "TBLPROPERTIES (%s)";
    sql(createTableStmt, tableName, tablePropsAsString(TABLE_PROPERTIES));
    sql(createTableStmt, tableName(OTHER_TABLE_NAME), tablePropsAsString(TABLE_PROPERTIES));
    Table table = validationCatalog.loadTable(tableIdent);
    Dataset<Row> dataDF = randomDataDF(table.schema(), 16);
    // write to the first table 1 time to generate 1 file per partition
    append(tableName, dataDF);
    // write to the second table 2 times to generate 2 files per partition
    append(tableName(OTHER_TABLE_NAME), dataDF);
    append(tableName(OTHER_TABLE_NAME), dataDF);
    // Spark SPJ support is limited at the moment and requires all source partitioning columns,
    // which were projected in the query, to be part of the join condition
    // suppose a table is partitioned by `p1`, `bucket(8, pk)`
    // queries covering `p1` and `pk` columns must include equality predicates
    // on both `p1` and `pk` to benefit from SPJ
    // this is a temporary Spark limitation that will be removed in a future release
    assertPartitioningAwarePlan(1, /* expected num of shuffles with SPJ */
    3, /* expected num of shuffles without SPJ */
    "SELECT t1.id " + "FROM %s t1 " + "INNER JOIN %s t2 " + "ON t1.id = t2.id AND t1.dep = t2.dep " + "ORDER BY t1.id", tableName, tableName(OTHER_TABLE_NAME));
    assertPartitioningAwarePlan(1, /* expected num of shuffles with SPJ */
    3, /* expected num of shuffles without SPJ */
    "SELECT t1.id, t1.int_col, t1.date_col1 " + "FROM %s t1 " + "INNER JOIN %s t2 " + "ON t1.id = t2.id AND t1.int_col = t2.int_col AND t1.date_col1 = t2.date_col1 " + "ORDER BY t1.id, t1.int_col, t1.date_col1", tableName, tableName(OTHER_TABLE_NAME));
    assertPartitioningAwarePlan(1, /* expected num of shuffles with SPJ */
    3, /* expected num of shuffles without SPJ */
    "SELECT t1.id, t1.timestamp_col, t1.string_col " + "FROM %s t1 " + "INNER JOIN %s t2 " + "ON t1.id = t2.id AND t1.timestamp_col = t2.timestamp_col AND t1.string_col = t2.string_col " + "ORDER BY t1.id, t1.timestamp_col, t1.string_col", tableName, tableName(OTHER_TABLE_NAME));
    assertPartitioningAwarePlan(1, /* expected num of shuffles with SPJ */
    3, /* expected num of shuffles without SPJ */
    "SELECT t1.id, t1.date_col1, t1.date_col2, t1.date_col3 " + "FROM %s t1 " + "INNER JOIN %s t2 " + "ON t1.id = t2.id AND t1.date_col1 = t2.date_col1 AND t1.date_col2 = t2.date_col2 AND t1.date_col3 = t2.date_col3 " + "ORDER BY t1.id, t1.date_col1, t1.date_col2, t1.date_col3", tableName, tableName(OTHER_TABLE_NAME));
    assertPartitioningAwarePlan(1, /* expected num of shuffles with SPJ */
    3, /* expected num of shuffles without SPJ */
    "SELECT t1.id, t1.int_col, t1.timestamp_col, t1.dep " + "FROM %s t1 " + "INNER JOIN %s t2 " + "ON t1.id = t2.id AND t1.int_col = t2.int_col AND t1.timestamp_col = t2.timestamp_col AND t1.dep = t2.dep " + "ORDER BY t1.id, t1.int_col, t1.timestamp_col, t1.dep", tableName, tableName(OTHER_TABLE_NAME));
}

@Test
public void testJoinsWithCompatibleSpecEvolution() {
    // create a table with an empty spec
    sql("CREATE TABLE %s (id BIGINT, int_col INT, dep STRING)" + "USING iceberg " + "TBLPROPERTIES (%s)", tableName, tablePropsAsString(TABLE_PROPERTIES));
    Table table = validationCatalog.loadTable(tableIdent);
    // evolve the spec in the first table by adding `dep`
    table.updateSpec().addField("dep").commit();
    // insert data into the first table partitioned by `dep`
    sql("REFRESH TABLE %s", tableName);
    sql("INSERT INTO %s VALUES (1L, 100, 'software')", tableName);
    // evolve the spec in the first table by adding `bucket(int_col, 8)`
    table.updateSpec().addField(Expressions.bucket("int_col", 8)).commit();
    // insert data into the first table partitioned by `dep`, `bucket(8, int_col)`
    sql("REFRESH TABLE %s", tableName);
    sql("INSERT INTO %s VALUES (2L, 200, 'hr')", tableName);
    // create another table partitioned by `other_dep`
    sql("CREATE TABLE %s (other_id BIGINT, other_int_col INT, other_dep STRING)" + "USING iceberg " + "PARTITIONED BY (other_dep)" + "TBLPROPERTIES (%s)", tableName(OTHER_TABLE_NAME), tablePropsAsString(TABLE_PROPERTIES));
    // insert data into the second table partitioned by 'other_dep'
    sql("INSERT INTO %s VALUES (1L, 100, 'software')", tableName(OTHER_TABLE_NAME));
    sql("INSERT INTO %s VALUES (2L, 200, 'hr')", tableName(OTHER_TABLE_NAME));
    // SPJ would apply as the grouping keys are compatible
    // the first table: `dep` (an intersection of all active partition fields across scanned specs)
    // the second table: `other_dep` (the only partition field).
    assertPartitioningAwarePlan(1, /* expected num of shuffles with SPJ */
    3, /* expected num of shuffles without SPJ */
    "SELECT * " + "FROM %s " + "INNER JOIN %s " + "ON id = other_id AND int_col = other_int_col AND dep = other_dep " + "ORDER BY id, int_col, dep", tableName, tableName(OTHER_TABLE_NAME));
}

