@Test
public void addPartitionToPartitionedSnapshotIdInheritanceEnabledInTwoRuns() {
    createPartitionedFileTable("parquet");
    createIcebergTable("id Integer, name String, dept String, subdept String", "PARTITIONED BY (id)");
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' 'true')", tableName, TableProperties.SNAPSHOT_ID_INHERITANCE_ENABLED);
    sql("CALL %s.system.add_files('%s', '`parquet`.`%s`', map('id', 1))", catalogName, tableName, fileTableDir.getAbsolutePath());
    sql("CALL %s.system.add_files('%s', '`parquet`.`%s`', map('id', 2))", catalogName, tableName, fileTableDir.getAbsolutePath());
    assertEquals("Iceberg table contains correct data", sql("SELECT id, name, dept, subdept FROM %s WHERE id < 3 ORDER BY id", sourceTableName), sql("SELECT id, name, dept, subdept FROM %s ORDER BY id", tableName));
    // verify manifest file name has uuid pattern
    String manifestPath = (String) sql("select path from %s.manifests", tableName).get(0)[0];
    Pattern uuidPattern = Pattern.compile("[a-f0-9]{8}(?:-[a-f0-9]{4}){4}[a-f0-9]{8}");
    Matcher matcher = uuidPattern.matcher(manifestPath);
    Assert.assertTrue("verify manifest path has uuid", matcher.find());
}

