    List<String> callStatementsWithComments = Lists.newArrayList("/* bracketed comment */  CALL cat.system.func('${spark.extra.prop}')", "/**/  CALL cat.system.func('${spark.extra.prop}')", "-- single line comment \n CALL cat.system.func('${spark.extra.prop}')", "-- multiple \n-- single line \n-- comments \n CALL cat.system.func('${spark.extra.prop}')", "/* select * from multiline_comment \n where x like '%sql%'; */ CALL cat.system.func('${spark.extra.prop}')", "/* {\"app\": \"dbt\", \"dbt_version\": \"1.0.1\", \"profile_name\": \"profile1\", \"target_name\": \"dev\", " + "\"node_id\": \"model.profile1.stg_users\"} \n*/ CALL cat.system.func('${spark.extra.prop}')", "/* Some multi-line comment \n" + "*/ CALL /* inline comment */ cat.system.func('${spark.extra.prop}') -- ending comment", "CALL -- a line ending comment\n" + "cat.system.func('${spark.extra.prop}')");
    for (String sqlText : callStatementsWithComments) {
        CallStatement call = (CallStatement) parser.parsePlan(sqlText);
        Assert.assertEquals(ImmutableList.of("cat", "system", "func"), JavaConverters.seqAsJavaList(call.name()));
        Assert.assertEquals(1, call.args().size());
        checkArg(call, 0, "value", DataTypes.StringType);
    }
}

