    assertThatThrownBy(() -> sql("CALL %s.custom.cherrypick_snapshot('n', 't', 1L)", catalogName)).as("Should not resolve procedures in arbitrary namespaces").isInstanceOf(NoSuchProcedureException.class).hasMessageContaining("not found");
