@Test
public void testTimestampsBasedQuery() {
    createTableWithTwoColumns();
    long beginning = System.currentTimeMillis();
    sql("INSERT INTO %s VALUES (1, 'a')", tableName);
    Table table = validationCatalog.loadTable(tableIdent);
    Snapshot snap0 = table.currentSnapshot();
    long afterFirstInsert = waitUntilAfter(snap0.timestampMillis());
    sql("INSERT INTO %s VALUES (2, 'b')", tableName);
    table.refresh();
    Snapshot snap1 = table.currentSnapshot();
    sql("INSERT OVERWRITE %s VALUES (-2, 'b')", tableName);
    table.refresh();
    Snapshot snap2 = table.currentSnapshot();
    long afterInsertOverwrite = waitUntilAfter(snap2.timestampMillis());
    List<Object[]> returns = sql("CALL %s.system.create_changelog_view(table => '%s', " + "options => map('%s', '%s','%s', '%s'))", catalogName, tableName, SparkReadOptions.START_TIMESTAMP, beginning, SparkReadOptions.END_TIMESTAMP, afterInsertOverwrite);
    assertEquals("Rows should match", ImmutableList.of(row(1, "a", INSERT, 0, snap0.snapshotId()), row(2, "b", INSERT, 1, snap1.snapshotId()), row(-2, "b", INSERT, 2, snap2.snapshotId()), row(2, "b", DELETE, 2, snap2.snapshotId())), sql("select * from %s order by _change_ordinal, id", returns.get(0)[0]));
    // query the timestamps starting from the second insert
    returns = sql("CALL %s.system.create_changelog_view(table => '%s', " + "options => map('%s', '%s', '%s', '%s'))", catalogName, tableName, SparkReadOptions.START_TIMESTAMP, afterFirstInsert, SparkReadOptions.END_TIMESTAMP, afterInsertOverwrite);
    assertEquals("Rows should match", ImmutableList.of(row(2, "b", INSERT, 0, snap1.snapshotId()), row(-2, "b", INSERT, 1, snap2.snapshotId()), row(2, "b", DELETE, 1, snap2.snapshotId())), sql("select * from %s order by _change_ordinal, id", returns.get(0)[0]));
}

