        LogicalPlan parsed = parsePlan("DELETE FROM %s WHERE dep = 'hr'", commitTarget());
        DeleteFromIcebergTable analyzed = (DeleteFromIcebergTable) spark.sessionState().analyzer().execute(parsed);
        Assert.assertTrue("Should have rewrite plan", analyzed.rewritePlan().isDefined());
        DeleteFromIcebergTable optimized = (DeleteFromIcebergTable) OptimizeMetadataOnlyDeleteFromIcebergTable.apply(analyzed);
        Assert.assertTrue("Should discard rewrite plan", optimized.rewritePlan().isEmpty());
    });
    sql("DELETE FROM %s WHERE dep = 'hr'", commitTarget());
    assertEquals("Should have expected rows", ImmutableList.of(row(1, "hardware"), row(2, "hardware")), sql("SELECT * FROM %s ORDER BY id", selectTarget()));
}

