@Test
public void testFastForwardBranchUsingPositionalArgs() {
    sql("CREATE TABLE %s (id int NOT NULL, data string) USING iceberg", tableName);
    sql("INSERT INTO TABLE %s VALUES (1, 'a')", tableName);
    sql("INSERT INTO TABLE %s VALUES (2, 'b')", tableName);
    Table table = validationCatalog.loadTable(tableIdent);
    table.refresh();
    Snapshot currSnapshot = table.currentSnapshot();
    long sourceRef = currSnapshot.snapshotId();
    String newBranch = "testBranch";
    String tableNameWithBranch = String.format("%s.branch_%s", tableName, newBranch);
    sql("ALTER TABLE %s CREATE BRANCH %s", tableName, newBranch);
    sql("INSERT INTO TABLE %s VALUES(3,'c')", tableNameWithBranch);
    table.refresh();
    long updatedRef = table.snapshot(newBranch).snapshotId();
    assertEquals("Main branch should not have the newly inserted record.", ImmutableList.of(row(1, "a"), row(2, "b")), sql("SELECT * FROM %s order by id", tableName));
    assertEquals("Test branch should have the newly inserted record.", ImmutableList.of(row(1, "a"), row(2, "b"), row(3, "c")), sql("SELECT * FROM %s order by id", tableNameWithBranch));
    List<Object[]> output = sql("CALL %s.system.fast_forward('%s', '%s', '%s')", catalogName, tableIdent, SnapshotRef.MAIN_BRANCH, newBranch);
    assertThat(Arrays.stream(output.get(0)).collect(Collectors.toList()).get(0)).isEqualTo(SnapshotRef.MAIN_BRANCH);
    assertThat(Arrays.stream(output.get(0)).collect(Collectors.toList()).get(1)).isEqualTo(sourceRef);
    assertThat(Arrays.stream(output.get(0)).collect(Collectors.toList()).get(2)).isEqualTo(updatedRef);
    assertEquals("Main branch should have the newly inserted record.", ImmutableList.of(row(1, "a"), row(2, "b"), row(3, "c")), sql("SELECT * FROM %s order by id", tableName));
}

