@Test
public void testMergeWithNullActionConditions() {
    createAndInitTable("id INT, v STRING", "{ \"id\": 1, \"v\": \"v1\" }\n" + "{ \"id\": 2, \"v\": \"v2\" }");
    createOrReplaceView("source", "{ \"id\": 1, \"v\": \"v1_1\" }\n" + "{ \"id\": 2, \"v\": \"v2_2\" }\n" + "{ \"id\": 3, \"v\": \"v3_3\" }");
    // all conditions are NULL and will never match any rows
    sql("MERGE INTO %s t USING source " + "ON t.id == source.id " + "WHEN MATCHED AND source.id = 1 AND NULL THEN " + "  UPDATE SET v = source.v " + "WHEN MATCHED AND source.v = 'v1_1' AND NULL THEN " + "  DELETE " + "WHEN NOT MATCHED AND source.id = 3 AND NULL THEN " + "  INSERT (v, id) VALUES (source.v, source.id)", commitTarget());
    ImmutableList<Object[]> expectedRows1 = ImmutableList.of(// kept
    row(1, "v1"), // kept
    row(2, "v2"));
    assertEquals("Output should match", expectedRows1, sql("SELECT * FROM %s ORDER BY v", selectTarget()));
    // only the update and insert conditions are NULL
    sql("MERGE INTO %s t USING source " + "ON t.id == source.id " + "WHEN MATCHED AND source.id = 1 AND NULL THEN " + "  UPDATE SET v = source.v " + "WHEN MATCHED AND source.v = 'v1_1' THEN " + "  DELETE " + "WHEN NOT MATCHED AND source.id = 3 AND NULL THEN " + "  INSERT (v, id) VALUES (source.v, source.id)", commitTarget());
    ImmutableList<Object[]> expectedRows2 = ImmutableList.of(// kept
    row(2, "v2"));
    assertEquals("Output should match", expectedRows2, sql("SELECT * FROM %s ORDER BY v", selectTarget()));
}

