@Test
public void testMergeUpdatesNestedStructFields() {
    createAndInitTable("id INT, s STRUCT<c1:INT,c2:STRUCT<a:ARRAY<INT>,m:MAP<STRING, STRING>>>", "{ \"id\": 1, \"s\": { \"c1\": 2, \"c2\": { \"a\": [1,2], \"m\": { \"a\": \"b\"} } } } }");
    createOrReplaceView("source", "{ \"id\": 1, \"c1\": -2 }");
    // update primitive, array, map columns inside a struct
    sql("MERGE INTO %s t USING source " + "ON t.id == source.id " + "WHEN MATCHED THEN " + "  UPDATE SET t.s.c1 = source.c1, t.s.c2.a = array(-1, -2), t.s.c2.m = map('k', 'v')", commitTarget());
    assertEquals("Output should match", ImmutableList.of(row(1, row(-2, row(ImmutableList.of(-1, -2), ImmutableMap.of("k", "v"))))), sql("SELECT * FROM %s ORDER BY id", selectTarget()));
    // set primitive, array, map columns to NULL (proper casts should be in place)
    sql("MERGE INTO %s t USING source " + "ON t.id == source.id " + "WHEN MATCHED THEN " + "  UPDATE SET t.s.c1 = NULL, t.s.c2 = NULL", commitTarget());
    assertEquals("Output should match", ImmutableList.of(row(1, row(null, null))), sql("SELECT * FROM %s ORDER BY id", selectTarget()));
    // update all fields in a struct
    sql("MERGE INTO %s t USING source " + "ON t.id == source.id " + "WHEN MATCHED THEN " + "  UPDATE SET t.s = named_struct('c1', 100, 'c2', named_struct('a', array(1), 'm', map('x', 'y')))", commitTarget());
    assertEquals("Output should match", ImmutableList.of(row(1, row(100, row(ImmutableList.of(1), ImmutableMap.of("x", "y"))))), sql("SELECT * FROM %s ORDER BY id", selectTarget()));
}

