    Assume.assumeTrue("WAP branch only works for table identifier without branch", branch == null);
    createAndInitTable("id INT", "{\"id\": -1}");
    ImmutableList<Object[]> originalRows = ImmutableList.of(row(-1));
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' = 'true')", tableName, TableProperties.WRITE_AUDIT_PUBLISH_ENABLED);
    spark.range(0, 5).coalesce(1).createOrReplaceTempView("source");
    ImmutableList<Object[]> expectedRows = ImmutableList.of(row(-1), row(0), row(1), row(2), row(3), row(4));
    withSQLConf(ImmutableMap.of(SparkSQLProperties.WAP_BRANCH, "wap"), () -> {
        sql("MERGE INTO %s t USING source s ON t.id = s.id " + "WHEN MATCHED THEN UPDATE SET *" + "WHEN NOT MATCHED THEN INSERT *", tableName);
        assertEquals("Should have expected rows when reading table", expectedRows, sql("SELECT * FROM %s ORDER BY id", tableName));
        assertEquals("Should have expected rows when reading WAP branch", expectedRows, sql("SELECT * FROM %s.branch_wap ORDER BY id", tableName));
        assertEquals("Should not modify main branch", originalRows, sql("SELECT * FROM %s.branch_main ORDER BY id", tableName));
    });
    spark.range(3, 6).coalesce(1).createOrReplaceTempView("source2");
    ImmutableList<Object[]> expectedRows2 = ImmutableList.of(row(-1), row(0), row(1), row(2), row(5));
