@Test
public void testCommitUnknownException() {
    createAndInitTable("id INT, dep STRING, category STRING");
    // write unpartitioned files
    append(tableName, "{ \"id\": 1, \"dep\": \"hr\", \"category\": \"c1\"}");
    createBranchIfNeeded();
    append(commitTarget(), "{ \"id\": 2, \"dep\": \"hr\", \"category\": \"c1\" }\n" + "{ \"id\": 3, \"dep\": \"hr\", \"category\": \"c1\" }");
    Table table = validationCatalog.loadTable(tableIdent);
    RowDelta newRowDelta = table.newRowDelta();
    if (branch != null) {
        newRowDelta.toBranch(branch);
    }
    RowDelta spyNewRowDelta = spy(newRowDelta);
    doAnswer(invocation -> {
        newRowDelta.commit();
        throw new CommitStateUnknownException(new RuntimeException("Datacenter on Fire"));
    }).when(spyNewRowDelta).commit();
    Table spyTable = spy(table);
    when(spyTable.newRowDelta()).thenReturn(spyNewRowDelta);
    SparkTable sparkTable = branch == null ? new SparkTable(spyTable, false) : new SparkTable(spyTable, branch, false);
    ImmutableMap<String, String> config = ImmutableMap.of("type", "hive", "default-namespace", "default");
    spark.conf().set("spark.sql.catalog.dummy_catalog", "org.apache.iceberg.spark.source.TestSparkCatalog");
    config.forEach((key, value) -> spark.conf().set("spark.sql.catalog.dummy_catalog." + key, value));
    Identifier ident = Identifier.of(new String[] { "default" }, "table");
    TestSparkCatalog.setTable(ident, sparkTable);
    // Although an exception is thrown here, write and commit have succeeded
    assertThatThrownBy(() -> sql("DELETE FROM %s WHERE id = 2", "dummy_catalog.default.table")).as("Should throw a Commit State Unknown Exception").isInstanceOf(SparkException.class).hasMessageContaining("Writing job aborted").cause().isInstanceOf(CommitStateUnknownException.class).hasMessageContaining("Datacenter on Fire");
    // Since write and commit succeeded, the rows should be readable
    assertEquals("Should have expected rows", ImmutableList.of(row(1, "hr", "c1"), row(3, "hr", "c1")), sql("SELECT * FROM %s ORDER BY id", "dummy_catalog.default.table"));
}

@Test
public void testAggregatePushDownInMergeOnReadDelete() {
    createAndInitTable("id LONG, data INT");
    sql("INSERT INTO TABLE %s VALUES (1, 1111), (1, 2222), (2, 3333), (2, 4444), (3, 5555), (3, 6666) ", tableName);
    createBranchIfNeeded();
    sql("DELETE FROM %s WHERE data = 1111", commitTarget());
    String select = "SELECT max(data), min(data), count(data) FROM %s";
    List<Object[]> explain = sql("EXPLAIN " + select, selectTarget());
    String explainString = explain.get(0)[0].toString().toLowerCase(Locale.ROOT);
    boolean explainContainsPushDownAggregates = false;
    if (explainString.contains("max(data)") || explainString.contains("min(data)") || explainString.contains("count(data)")) {
        explainContainsPushDownAggregates = true;
    }
    Assert.assertFalse("min/max/count not pushed down for deleted", explainContainsPushDownAggregates);
    List<Object[]> actual = sql(select, selectTarget());
    List<Object[]> expected = Lists.newArrayList();
    expected.add(new Object[] { 6666, 2222, 5L });
    assertEquals("min/max/count push down", expected, actual);
}

