@Test
public void testRemoveOrphanFilesWithStatisticFiles() throws Exception {
    sql("CREATE TABLE %s USING iceberg " + "TBLPROPERTIES('format-version'='2') " + "AS SELECT 10 int, 'abc' data", tableName);
    Table table = Spark3Util.loadIcebergTable(spark, tableName);
    String statsFileName = "stats-file-" + UUID.randomUUID();
    File statsLocation = new File(new URI(table.location())).toPath().resolve("data").resolve(statsFileName).toFile();
    StatisticsFile statisticsFile;
    try (PuffinWriter puffinWriter = Puffin.write(Files.localOutput(statsLocation)).build()) {
        long snapshotId = table.currentSnapshot().snapshotId();
        long snapshotSequenceNumber = table.currentSnapshot().sequenceNumber();
        puffinWriter.add(new Blob("some-blob-type", ImmutableList.of(1), snapshotId, snapshotSequenceNumber, ByteBuffer.wrap("blob content".getBytes(StandardCharsets.UTF_8))));
        puffinWriter.finish();
        statisticsFile = new GenericStatisticsFile(snapshotId, statsLocation.toString(), puffinWriter.fileSize(), puffinWriter.footerSize(), puffinWriter.writtenBlobsMetadata().stream().map(GenericBlobMetadata::from).collect(ImmutableList.toImmutableList()));
    }
    Transaction transaction = table.newTransaction();
    transaction.updateStatistics().setStatistics(statisticsFile.snapshotId(), statisticsFile).commit();
    transaction.commitTransaction();
    // wait to ensure files are old enough
    waitUntilAfter(System.currentTimeMillis());
    Timestamp currentTimestamp = Timestamp.from(Instant.ofEpochMilli(System.currentTimeMillis()));
    List<Object[]> output = sql("CALL %s.system.remove_orphan_files(" + "table => '%s'," + "older_than => TIMESTAMP '%s')", catalogName, tableIdent, currentTimestamp);
    assertThat(output).as("Should be no orphan files").isEmpty();
    assertThat(statsLocation.exists()).as("stats file should exist").isTrue();
    assertThat(statsLocation.length()).as("stats file length").isEqualTo(statisticsFile.fileSizeInBytes());
    transaction = table.newTransaction();
    transaction.updateStatistics().removeStatistics(statisticsFile.snapshotId()).commit();
    transaction.commitTransaction();
    output = sql("CALL %s.system.remove_orphan_files(" + "table => '%s'," + "older_than => TIMESTAMP '%s')", catalogName, tableIdent, currentTimestamp);
    assertThat(output).as("Should be orphan files").hasSize(1);
    assertThat(Iterables.getOnlyElement(output)).as("Deleted files").containsExactly(statsLocation.toURI().toString());
    assertThat(statsLocation.exists()).as("stats file should be deleted").isFalse();
}

