@Test
public void testRewriteDataFilesWithInvalidInputs() {
    createTable();
    // create 2 files under non-partitioned table
    insertData(2);
    // Test for invalid strategy
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', options => map('min-input-files','2'), " + "strategy => 'temp')", catalogName, tableIdent)).as("Should reject calls with unsupported strategy error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("unsupported strategy: temp. Only binpack or sort is supported");
    // Test for sort_order with binpack strategy
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', strategy => 'binpack', " + "sort_order => 'c1 ASC NULLS FIRST')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Must use only one rewriter type (bin-pack, sort, zorder)");
    // Test for sort strategy without any (default/user defined) sort_order
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', strategy => 'sort')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot sort data without a valid sort order");
    // Test for sort_order with invalid null order
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', strategy => 'sort', " + "sort_order => 'c1 ASC none')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Unable to parse sortOrder:");
    // Test for sort_order with invalid sort direction
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', strategy => 'sort', " + "sort_order => 'c1 none NULLS FIRST')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Unable to parse sortOrder:");
    // Test for sort_order with invalid column name
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', strategy => 'sort', " + "sort_order => 'col1 DESC NULLS FIRST')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(ValidationException.class).hasMessageContaining("Cannot find field 'col1' in struct:" + " struct<1: c1: optional int, 2: c2: optional string, 3: c3: optional string>");
    // Test with invalid filter column col1
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', " + "where => 'col1 = 3')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot parse predicates in where option: col1 = 3");
    // Test for z_order with invalid column name
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', strategy => 'sort', " + "sort_order => 'zorder(col1)')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot find column 'col1' in table schema (case sensitive = false): " + "struct<1: c1: optional int, 2: c2: optional string, 3: c3: optional string>");
    // Test for z_order with sort_order
    assertThatThrownBy(() -> sql("CALL %s.system.rewrite_data_files(table => '%s', strategy => 'sort', " + "sort_order => 'c1,zorder(c2,c3)')", catalogName, tableIdent)).as("Should reject calls with error message").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot mix identity sort columns and a Zorder sort expression:" + " c1,zorder(c2,c3)");
}

