@Test
public void testInvalidSnapshotsCases() throws IOException {
    String location = temp.newFolder().toString();
    sql("CREATE TABLE %s (id bigint NOT NULL, data string) USING parquet LOCATION '%s'", SOURCE_NAME, location);
    assertThatThrownBy(() -> sql("CALL %s.system.snapshot('foo')", catalogName)).as("Should reject calls without all required args").isInstanceOf(AnalysisException.class).hasMessageContaining("Missing required parameters");
    assertThatThrownBy(() -> sql("CALL %s.system.snapshot('n', 't', map('foo', 'bar'))", catalogName)).as("Should reject calls with invalid arg types").isInstanceOf(AnalysisException.class).hasMessageContaining("Wrong arg type");
    assertThatThrownBy(() -> sql("CALL %s.system.snapshot('%s', 'fable', 'loc', map(2, 1, 1))", catalogName, SOURCE_NAME)).as("Should reject calls with invalid map args").isInstanceOf(AnalysisException.class).hasMessageContaining("cannot resolve 'map");
    assertThatThrownBy(() -> sql("CALL %s.system.snapshot('', 'dest')", catalogName)).as("Should reject calls with empty table identifier").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot handle an empty identifier");
    assertThatThrownBy(() -> sql("CALL %s.system.snapshot('src', '')", catalogName)).as("Should reject calls with empty table identifier").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Cannot handle an empty identifier");
}

