@Test
public void testCreateTagUseDefaultConfig() throws NoSuchTableException {
    Table table = insertRows();
    long snapshotId = table.currentSnapshot().snapshotId();
    String tagName = "t1";
    assertThatThrownBy(() -> sql("ALTER TABLE %s CREATE TAG %s AS OF VERSION %d", tableName, tagName, -1)).as("unknown snapshot").isInstanceOf(ValidationException.class).hasMessageContaining("unknown snapshot: -1");
    sql("ALTER TABLE %s CREATE TAG %s", tableName, tagName);
    table.refresh();
    SnapshotRef ref = table.refs().get(tagName);
    Assert.assertEquals("The tag needs to point to a specific snapshot id.", snapshotId, ref.snapshotId());
    Assert.assertNull("The tag needs to have the default max ref age, which is null.", ref.maxRefAgeMs());
    assertThatThrownBy(() -> sql("ALTER TABLE %s CREATE TAG %s", tableName, tagName)).as("Cannot create an exist tag").isInstanceOf(IllegalArgumentException.class).hasMessageContaining("already exists");
    assertThatThrownBy(() -> sql("ALTER TABLE %s CREATE TAG %s", tableName, "123")).as("Non-conforming tag name").isInstanceOf(IcebergParseException.class).hasMessageContaining("mismatched input '123'");
    table.manageSnapshots().removeTag(tagName).commit();
    List<SimpleRecord> records = ImmutableList.of(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.writeTo(tableName).append();
    snapshotId = table.currentSnapshot().snapshotId();
    sql("ALTER TABLE %s CREATE TAG %s AS OF VERSION %d", tableName, tagName, snapshotId);
    table.refresh();
    ref = table.refs().get(tagName);
    Assert.assertEquals("The tag needs to point to a specific snapshot id.", snapshotId, ref.snapshotId());
    Assert.assertNull("The tag needs to have the default max ref age, which is null.", ref.maxRefAgeMs());
}

