    append(tableName, "{ \"id\": 1, \"dep\": \"hr\" }\n" + "{ \"id\": 2, \"dep\": \"hardware\" }\n" + "{ \"id\": null, \"dep\": \"hr\" }");
    createBranchIfNeeded();
    createOrReplaceView("updated_id", Arrays.asList(-1, -2, null), Encoders.INT());
    createOrReplaceView("updated_dep", Arrays.asList("software", "hr"), Encoders.STRING());
    // the file filter subquery (nested loop lef-anti join) returns 0 records
    sql("UPDATE %s SET id = -1 WHERE id NOT IN (SELECT * FROM updated_id)", commitTarget());
    assertEquals("Should have expected rows", ImmutableList.of(row(1, "hr"), row(2, "hardware"), row(null, "hr")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST", selectTarget()));
    sql("UPDATE %s SET id = -1 WHERE id NOT IN (SELECT * FROM updated_id WHERE value IS NOT NULL)", commitTarget());
    assertEquals("Should have expected rows", ImmutableList.of(row(-1, "hardware"), row(-1, "hr"), row(null, "hr")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST, dep", selectTarget()));
    sql("UPDATE %s SET id = 5 WHERE id NOT IN (SELECT * FROM updated_id) OR dep IN ('software', 'hr')", commitTarget());
    assertEquals("Should have expected rows", ImmutableList.of(row(-1, "hardware"), row(5, "hr"), row(5, "hr")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST, dep", selectTarget()));
}

