    append(commitTarget(), "{ \"id\": 0, \"dep\": \"hr\" }\n" + "{ \"id\": 1, \"dep\": \"hr\" }\n" + "{ \"id\": 2, \"dep\": \"hr\" }");
    append(commitTarget(), "{ \"id\": 0, \"dep\": \"ops\" }\n" + "{ \"id\": 1, \"dep\": \"ops\" }\n" + "{ \"id\": 2, \"dep\": \"ops\" }");
    createOrReplaceView("updated_id", Arrays.asList(1, 100), Encoders.INT());
