    List<Object[]> originalData = currentData();
    double originalFilesC2 = percentFilesRequired(table, "c2", "foo23");
    double originalFilesC3 = percentFilesRequired(table, "c3", "bar21");
    double originalFilesC2C3 = percentFilesRequired(table, new String[] { "c2", "c3" }, new String[] { "foo23", "bar23" });
    Assert.assertTrue("Should require all files to scan c2", originalFilesC2 > 0.99);
    Assert.assertTrue("Should require all files to scan c3", originalFilesC3 > 0.99);
    long dataSizeBefore = testDataSize(table);
    RewriteDataFiles.Result result = basicRewrite(table).zOrder("c2", "c3").option(SizeBasedFileRewriter.MAX_FILE_SIZE_BYTES, Integer.toString((averageFileSize(table) / 2) + 2)).// Divide files in 2
    option(RewriteDataFiles.TARGET_FILE_SIZE_BYTES, Integer.toString(averageFileSize(table) / 2)).option(SizeBasedFileRewriter.MIN_INPUT_FILES, "1").execute();
    Assert.assertEquals("Should have 1 fileGroups", 1, result.rewriteResults().size());
    assertThat(result.rewrittenBytesCount()).isEqualTo(dataSizeBefore);
    int zOrderedFilesTotal = Iterables.size(table.currentSnapshot().addedDataFiles(table.io()));
    Assert.assertTrue("Should have written 40+ files", zOrderedFilesTotal >= 40);
    table.refresh();
    List<Object[]> postRewriteData = currentData();
    assertEquals("We shouldn't have changed the data", originalData, postRewriteData);
    shouldHaveSnapshots(table, 2);
    shouldHaveACleanCache(table);
    double filesScannedC2 = percentFilesRequired(table, "c2", "foo23");
    double filesScannedC3 = percentFilesRequired(table, "c3", "bar21");
    double filesScannedC2C3 = percentFilesRequired(table, new String[] { "c2", "c3" }, new String[] { "foo23", "bar23" });
    Assert.assertTrue("Should have reduced the number of files required for c2", filesScannedC2 < originalFilesC2);
    Assert.assertTrue("Should have reduced the number of files required for c3", filesScannedC3 < originalFilesC3);
    Assert.assertTrue("Should have reduced the number of files required for a c2,c3 predicate", filesScannedC2C3 < originalFilesC2C3);
}

