    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' '%s')", TABLE_NAME, DELETE_DEFAULT_FILE_FORMAT, format);
    for (Map.Entry<String, String> entry : tableProperties.entrySet()) {
        sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' '%s')", TABLE_NAME, entry.getKey(), entry.getValue());
    }
    List<SimpleRecord> expectedOrigin = Lists.newArrayList();
    for (int i = 0; i < 1000; i++) {
        expectedOrigin.add(new SimpleRecord(i, "hello world" + i));
    }
