@Test
public void testIncrementalScanOptions() throws IOException {
    String tableLocation = temp.newFolder("iceberg-table").toString();
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.unpartitioned();
    Map<String, String> options = Maps.newHashMap();
    Table table = tables.create(SCHEMA, spec, options, tableLocation);
    List<SimpleRecord> expectedRecords = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"), new SimpleRecord(4, "d"));
    for (SimpleRecord record : expectedRecords) {
        Dataset<Row> originalDf = spark.createDataFrame(Lists.newArrayList(record), SimpleRecord.class);
        originalDf.select("id", "data").write().format("iceberg").mode("append").save(tableLocation);
    }
    List<Long> snapshotIds = SnapshotUtil.currentAncestorIds(table);
    // start-snapshot-id and snapshot-id are both configured.
    assertThatThrownBy(() -> spark.read().format("iceberg").option("snapshot-id", snapshotIds.get(3).toString()).option("start-snapshot-id", snapshotIds.get(3).toString()).load(tableLocation).explain()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set start-snapshot-id and end-snapshot-id for incremental scans when either snapshot-id or as-of-timestamp is set");
    // end-snapshot-id and as-of-timestamp are both configured.
    assertThatThrownBy(() -> spark.read().format("iceberg").option(SparkReadOptions.AS_OF_TIMESTAMP, Long.toString(table.snapshot(snapshotIds.get(3)).timestampMillis())).option("end-snapshot-id", snapshotIds.get(2).toString()).load(tableLocation).explain()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set start-snapshot-id and end-snapshot-id for incremental scans when either snapshot-id or as-of-timestamp is set");
    // only end-snapshot-id is configured.
    assertThatThrownBy(() -> spark.read().format("iceberg").option("end-snapshot-id", snapshotIds.get(2).toString()).load(tableLocation).explain()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set only end-snapshot-id for incremental scans. Please, set start-snapshot-id too.");
    // test (1st snapshot, current snapshot] incremental scan.
    Dataset<Row> unboundedIncrementalResult = spark.read().format("iceberg").option("start-snapshot-id", snapshotIds.get(3).toString()).load(tableLocation);
    List<SimpleRecord> result1 = unboundedIncrementalResult.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    assertThat(result1).as("Records should match").isEqualTo(expectedRecords.subList(1, 4));
    assertThat(unboundedIncrementalResult.count()).as("Unprocessed count should match record count").isEqualTo(3);
    Row row1 = unboundedIncrementalResult.agg(functions.min("id"), functions.max("id")).head();
    assertThat(row1.getInt(0)).as("min value should match").isEqualTo(2);
    assertThat(row1.getInt(1)).as("max value should match").isEqualTo(4);
    // test (2nd snapshot, 3rd snapshot] incremental scan.
    Dataset<Row> incrementalResult = spark.read().format("iceberg").option("start-snapshot-id", snapshotIds.get(2).toString()).option("end-snapshot-id", snapshotIds.get(1).toString()).load(tableLocation);
    List<SimpleRecord> result2 = incrementalResult.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    assertThat(result2).as("Records should match").isEqualTo(expectedRecords.subList(2, 3));
    assertThat(incrementalResult.count()).as("Unprocessed count should match record count").isEqualTo(1);
    Row row2 = incrementalResult.agg(functions.min("id"), functions.max("id")).head();
    assertThat(row2.getInt(0)).as("min value should match").isEqualTo(3);
    assertThat(row2.getInt(1)).as("max value should match").isEqualTo(3);
}

