    Assert.assertEquals("Actual results should have two row", 2, nonFiltered.size());
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actual.get(i));
    }
}

