    table.refresh();
    List<Row> updatedRecords = Lists.newArrayList(RowFactory.create(1, "A"), RowFactory.create(2, "A"), RowFactory.create(3, "B"), RowFactory.create(4, "B"), RowFactory.create(5, "C"));
    Dataset<Row> resultDf2 = spark.read().format("iceberg").load(loadLocation(tableIdentifier));
    Assert.assertEquals("Records should match", updatedRecords, resultDf2.orderBy("id").collectAsList());
    Dataset<Row> resultDf3 = spark.read().format("iceberg").option(SparkReadOptions.AS_OF_TIMESTAMP, tsBeforeDropColumn).load(loadLocation(tableIdentifier));
    Assert.assertEquals("Records should match", originalRecords, resultDf3.orderBy("id").collectAsList());
    Assert.assertEquals("Schemas should match", originalSparkSchema, resultDf3.schema());
    // At tsAfterDropColumn, there has been a schema change, but no new snapshot,
    // so the snapshot as of tsAfterDropColumn is the same as that as of tsBeforeDropColumn.
    Dataset<Row> resultDf4 = spark.read().format("iceberg").option(SparkReadOptions.AS_OF_TIMESTAMP, tsAfterDropColumn).load(loadLocation(tableIdentifier));
    Assert.assertEquals("Records should match", originalRecords, resultDf4.orderBy("id").collectAsList());
    Assert.assertEquals("Schemas should match", originalSparkSchema, resultDf4.schema());
}

