public void testAllManifestTableSnapshotFiltering() {
    TableIdentifier tableIdentifier = TableIdentifier.of("db", "all_manifest_snapshot_filtering");
    Table table = createTable(tableIdentifier, SCHEMA, SPEC);
    Table manifestTable = loadTable(tableIdentifier, "all_manifests");
    Dataset<Row> df = spark.createDataFrame(Lists.newArrayList(new SimpleRecord(1, "a")), SimpleRecord.class);
    List<Pair<Long, ManifestFile>> snapshotIdToManifests = Lists.newArrayList();
    df.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    table.refresh();
    Snapshot snapshot1 = table.currentSnapshot();
    snapshotIdToManifests.addAll(snapshot1.allManifests(table.io()).stream().map(manifest -> Pair.of(snapshot1.snapshotId(), manifest)).collect(Collectors.toList()));
    df.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    table.refresh();
    Snapshot snapshot2 = table.currentSnapshot();
    Assert.assertEquals("Should have two manifests", 2, snapshot2.allManifests(table.io()).size());
    snapshotIdToManifests.addAll(snapshot2.allManifests(table.io()).stream().map(manifest -> Pair.of(snapshot2.snapshotId(), manifest)).collect(Collectors.toList()));
    // Add manifests that will not be selected
    df.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    df.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    StringJoiner snapshotIds = new StringJoiner(",", "(", ")");
    snapshotIds.add(String.valueOf(snapshot1.snapshotId()));
    snapshotIds.add(String.valueOf(snapshot2.snapshotId()));
    snapshotIds.toString();
    List<Row> actual = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "all_manifests")).filter("reference_snapshot_id in " + snapshotIds).orderBy("path").collectAsList();
    table.refresh();
    List<GenericData.Record> expected = snapshotIdToManifests.stream().map(snapshotManifest -> manifestRecord(manifestTable, snapshotManifest.first(), snapshotManifest.second())).sorted(Comparator.comparing(o -> o.get("path").toString())).collect(Collectors.toList());
    Assert.assertEquals("Manifests table should have 3 manifest rows", 3, actual.size());
    for (int i = 0; i < expected.size(); i += 1) {
        TestHelpers.assertEqualsSafe(manifestTable.schema().asStruct(), expected.get(i), actual.get(i));
    }
}

@Test
public void testTableWithInt96Timestamp() throws IOException {
    File parquetTableDir = temp.newFolder("table_timestamp_int96");
    String parquetTableLocation = parquetTableDir.toURI().toString();
    Schema schema = new Schema(optional(1, "id", Types.LongType.get()), optional(2, "tmp_col", Types.TimestampType.withZone()));
    spark.conf().set(SQLConf.PARQUET_OUTPUT_TIMESTAMP_TYPE().key(), "INT96");
    LocalDateTime start = LocalDateTime.of(2000, 1, 31, 0, 0, 0);
    LocalDateTime end = LocalDateTime.of(2100, 1, 1, 0, 0, 0);
    long startSec = start.toEpochSecond(ZoneOffset.UTC);
    long endSec = end.toEpochSecond(ZoneOffset.UTC);
    Column idColumn = functions.expr("id");
    Column secondsColumn = functions.expr("(id % " + (endSec - startSec) + " + " + startSec + ")").as("seconds");
    Column timestampColumn = functions.expr("cast( seconds as timestamp) as tmp_col");
    for (Boolean useDict : new Boolean[] { true, false }) {
        for (Boolean useVectorization : new Boolean[] { true, false }) {
            spark.sql("DROP TABLE IF EXISTS parquet_table");
            spark.range(0, 5000, 100, 1).select(idColumn, secondsColumn).select(idColumn, timestampColumn).write().format("parquet").option("parquet.enable.dictionary", useDict).mode("overwrite").option("path", parquetTableLocation).saveAsTable("parquet_table");
            TableIdentifier tableIdentifier = TableIdentifier.of("db", "table_with_timestamp_int96");
            Table table = createTable(tableIdentifier, schema, PartitionSpec.unpartitioned());
            table.updateProperties().set(TableProperties.PARQUET_VECTORIZATION_ENABLED, useVectorization.toString()).commit();
            String stagingLocation = table.location() + "/metadata";
            SparkTableUtil.importSparkTable(spark, new org.apache.spark.sql.catalyst.TableIdentifier("parquet_table"), table, stagingLocation);
            // validate we get the expected results back
            testWithFilter("tmp_col < to_timestamp('2000-01-31 08:30:00')", tableIdentifier);
            testWithFilter("tmp_col <= to_timestamp('2000-01-31 08:30:00')", tableIdentifier);
            testWithFilter("tmp_col == to_timestamp('2000-01-31 08:30:00')", tableIdentifier);
            testWithFilter("tmp_col > to_timestamp('2000-01-31 08:30:00')", tableIdentifier);
            testWithFilter("tmp_col >= to_timestamp('2000-01-31 08:30:00')", tableIdentifier);
            dropTable(tableIdentifier);
        }
    }
}

