        Assert.assertEquals(1, scanDF.javaRDD().getNumPartitions());
        scanDF.writeTo(posDeletesTableName).option(SparkWriteOptions.REWRITTEN_FILE_SCAN_TASK_SET_ID, fileSetID).append();
        commit(tab, posDeletesTable, fileSetID, 1);
    }
    // Select deletes from unpartitioned data
    // Compare values without 'delete_file_path' as these have been rewritten
    GenericRecord partitionRecordTemplate = GenericRecord.create(Partitioning.partitionType(tab));
    Record unpartitionedRecord = partitionRecordTemplate.copy("data", null);
    StructLikeSet expectedUnpartitioned = expected(tab, deletesUnpartitioned.first(), unpartitionedRecord, specId0, null);
    StructLikeSet actualUnpartitioned = actual(tableName, tab, "partition.data IS NULL", NON_PATH_COLS);
    Assert.assertEquals("Position Delete table should contain expected rows", expectedUnpartitioned, actualUnpartitioned);
    // Read/write back new partition spec (data)
    for (String partValue : ImmutableList.of("a", "b")) {
        try (CloseableIterable<ScanTask> tasks = tasks(posDeletesTable, "data", partValue)) {
            String fileSetID = UUID.randomUUID().toString();
            stageTask(tab, fileSetID, tasks);
            Dataset<Row> scanDF = spark.read().format("iceberg").option(SparkReadOptions.SCAN_TASK_SET_ID, fileSetID).option(SparkReadOptions.FILE_OPEN_COST, Integer.MAX_VALUE).load(posDeletesTableName);
            Assert.assertEquals(1, scanDF.javaRDD().getNumPartitions());
            scanDF.writeTo(posDeletesTableName).option(SparkWriteOptions.REWRITTEN_FILE_SCAN_TASK_SET_ID, fileSetID).append();
            // commit the rewrite
            commit(tab, posDeletesTable, fileSetID, 1);
        }
    }
    // Select deletes from new spec (data)
    Record partitionA = partitionRecordTemplate.copy("data", "a");
    Record partitionB = partitionRecordTemplate.copy("data", "b");
    StructLikeSet expectedAll = StructLikeSet.create(TypeUtil.selectNot(posDeletesTable.schema(), ImmutableSet.of(MetadataColumns.FILE_PATH_COLUMN_ID)).asStruct());
    expectedAll.addAll(expected(tab, deletesA.first(), partitionA, specId1, null));
    expectedAll.addAll(expected(tab, deletesB.first(), partitionB, specId1, null));
    StructLikeSet actualAll = actual(tableName, tab, "partition.data = 'a' OR partition.data = 'b'", NON_PATH_COLS);
    Assert.assertEquals("Position Delete table should contain expected rows", expectedAll, actualAll);
    dropTable(tableName);
}

