@Test
public void testIdentityPartitionedTable() throws NoSuchTableException {
    sql("CREATE TABLE %s (id BIGINT, data STRING, date DATE, ts TIMESTAMP) " + "USING iceberg " + "PARTITIONED BY (date)", tableName);
    configurePlanningMode(planningMode);
    Dataset<Row> df = spark.range(1, 100).withColumn("date", date_add(expr("DATE '1970-01-01'"), expr("CAST(id % 4 AS INT)"))).withColumn("ts", expr("TO_TIMESTAMP(date)")).withColumn("data", expr("CAST(date AS STRING)")).select("id", "data", "date", "ts");
    df.coalesce(1).writeTo(tableName).option(SparkWriteOptions.FANOUT_ENABLED, "true").append();
    sql("CREATE TABLE dim (id BIGINT, date DATE) USING parquet");
    Dataset<Row> dimDF = spark.range(1, 10).withColumn("date", expr("DATE '1970-01-02'")).select("id", "date");
    dimDF.coalesce(1).write().mode("append").insertInto("dim");
    String query = String.format("SELECT f.* FROM %s f JOIN dim d ON f.date = d.date AND d.id = 1 ORDER BY id", tableName);
    assertQueryContainsRuntimeFilter(query);
    deleteNotMatchingFiles(Expressions.equal("date", 1), 3);
    assertEquals("Should have expected rows", sql("SELECT * FROM %s WHERE date = DATE '1970-01-02' ORDER BY id", tableName), sql(query));
}

