@Test
public void testLoadFunctions() throws NoSuchFunctionException {
    for (String[] namespace : ImmutableList.of(EMPTY_NAMESPACE, SYSTEM_NAMESPACE)) {
        Identifier identifier = Identifier.of(namespace, "iceberg_version");
        UnboundFunction func = asFunctionCatalog.loadFunction(identifier);
        assertThat(func).isNotNull().isInstanceOf(UnboundFunction.class).isExactlyInstanceOf(IcebergVersionFunction.class);
    }
    assertThatThrownBy(() -> asFunctionCatalog.loadFunction(Identifier.of(DEFAULT_NAMESPACE, "iceberg_version"))).isInstanceOf(NoSuchFunctionException.class).hasMessageStartingWith(String.format("Cannot load function: %s.default.iceberg_version", catalogName));
    Identifier undefinedFunction = Identifier.of(SYSTEM_NAMESPACE, "undefined_function");
    assertThatThrownBy(() -> asFunctionCatalog.loadFunction(undefinedFunction)).isInstanceOf(NoSuchFunctionException.class).hasMessageStartingWith(String.format("Cannot load function: %s.system.undefined_function", catalogName));
    assertThatThrownBy(() -> sql("SELECT undefined_function(1, 2)")).isInstanceOf(AnalysisException.class).hasMessageStartingWith("[UNRESOLVED_ROUTINE] Cannot resolve function `undefined_function` on search path");
}

