public void testDescribeExpression() {
    Expression refExpression = equal("id", 1);
    assertThat(Spark3Util.describe(refExpression)).isEqualTo("id = 1");
    Expression yearExpression = greaterThan(year("ts"), 10);
    assertThat(Spark3Util.describe(yearExpression)).isEqualTo("year(ts) > 10");
    Expression monthExpression = greaterThanOrEqual(month("ts"), 10);
    assertThat(Spark3Util.describe(monthExpression)).isEqualTo("month(ts) >= 10");
    Expression dayExpression = lessThan(day("ts"), 10);
    assertThat(Spark3Util.describe(dayExpression)).isEqualTo("day(ts) < 10");
    Expression hourExpression = lessThanOrEqual(hour("ts"), 10);
    assertThat(Spark3Util.describe(hourExpression)).isEqualTo("hour(ts) <= 10");
    Expression bucketExpression = in(bucket("id", 5), 3);
    assertThat(Spark3Util.describe(bucketExpression)).isEqualTo("bucket[5](id) IN (3)");
    Expression truncateExpression = notIn(truncate("name", 3), "abc");
    assertThat(Spark3Util.describe(truncateExpression)).isEqualTo("truncate[3](name) NOT IN ('abc')");
    Expression andExpression = and(refExpression, yearExpression);
    assertThat(Spark3Util.describe(andExpression)).isEqualTo("(id = 1 AND year(ts) > 10)");
}

@Test
public void testTimeTravel() {
    sql("CREATE TABLE %s (id INT, dep STRING) USING iceberg", tableName);
    Table table = validationCatalog.loadTable(tableIdent);
    sql("INSERT INTO TABLE %s VALUES (1, 'hr')", tableName);
    table.refresh();
    Snapshot firstSnapshot = table.currentSnapshot();
    waitUntilAfter(firstSnapshot.timestampMillis());
    sql("INSERT INTO TABLE %s VALUES (2, 'hr')", tableName);
    table.refresh();
    Snapshot secondSnapshot = table.currentSnapshot();
    waitUntilAfter(secondSnapshot.timestampMillis());
    sql("INSERT INTO TABLE %s VALUES (3, 'hr')", tableName);
    table.refresh();
    try {
        TABLE_CACHE.add("key", table);
        assertEquals("Should have expected rows in 3rd snapshot", ImmutableList.of(row(1, "hr"), row(2, "hr"), row(3, "hr")), sql("SELECT * FROM testcache.key ORDER BY id"));
        assertEquals("Should have expected rows in 2nd snapshot", ImmutableList.of(row(1, "hr"), row(2, "hr")), sql("SELECT * FROM testcache.`key#at_timestamp_%s` ORDER BY id", secondSnapshot.timestampMillis()));
        assertEquals("Should have expected rows in 1st snapshot", ImmutableList.of(row(1, "hr")), sql("SELECT * FROM testcache.`key#snapshot_id_%d` ORDER BY id", firstSnapshot.snapshotId()));
    } finally {
        TABLE_CACHE.remove("key");
    }
}

@Test
public void testAlterTable() throws NoSuchTableException {
    BaseCatalog catalog = (BaseCatalog) spark.sessionState().catalogManager().catalog(catalogName);
    Identifier identifier = Identifier.of(tableIdent.namespace().levels(), tableIdent.name());
    String fieldName = "location";
    String propsKey = "note";
    String propsValue = "jazz";
    Table table = catalog.alterTable(identifier, TableChange.addColumn(new String[] { fieldName }, DataTypes.StringType, true), TableChange.setProperty(propsKey, propsValue));
    Assert.assertNotNull("Should return updated table", table);
    StructField expectedField = DataTypes.createStructField(fieldName, DataTypes.StringType, true);
    Assert.assertEquals("Adding a column to a table should return the updated table with the new column", table.schema().fields()[2], expectedField);
    Assert.assertTrue("Adding a property to a table should return the updated table with the new property", table.properties().containsKey(propsKey));
    Assert.assertEquals("Altering a table to add a new property should add the correct value", propsValue, table.properties().get(propsKey));
}

