    createAndInitUnpartitionedTable();
    createOrReplaceView("deleted_id", Collections.singletonList(1), Encoders.INT());
    sql("ALTER TABLE %s SET TBLPROPERTIES('%s' '%s')", tableName, DELETE_ISOLATION_LEVEL, "snapshot");
    sql("INSERT INTO TABLE %s VALUES (1, 'hr')", tableName);
    createBranchIfNeeded();
    Table table = Spark3Util.loadIcebergTable(spark, tableName);
    ExecutorService executorService = MoreExecutors.getExitingExecutorService((ThreadPoolExecutor) Executors.newFixedThreadPool(2));
    AtomicInteger barrier = new AtomicInteger(0);
    AtomicBoolean shouldAppend = new AtomicBoolean(true);
    // delete thread
    Future<?> deleteFuture = executorService.submit(() -> {
        for (int numOperations = 0; numOperations < Integer.MAX_VALUE; numOperations++) {
            while (barrier.get() < numOperations * 2) {
                sleep(10);
            }
            sql("DELETE FROM %s WHERE id IN (SELECT * FROM deleted_id)", commitTarget());
            barrier.incrementAndGet();
        }
    });
    // append thread
    Future<?> appendFuture = executorService.submit(() -> {
        GenericRecord record = GenericRecord.create(SnapshotUtil.schemaFor(table, branch));
        // id
        record.set(0, 1);
        // dep
        record.set(1, "hr");
        for (int numOperations = 0; numOperations < Integer.MAX_VALUE; numOperations++) {
            while (shouldAppend.get() && barrier.get() < numOperations * 2) {
                sleep(10);
            }
            if (!shouldAppend.get()) {
                return;
            }
            for (int numAppends = 0; numAppends < 5; numAppends++) {
                DataFile dataFile = writeDataFile(table, ImmutableList.of(record));
                AppendFiles appendFiles = table.newFastAppend().appendFile(dataFile);
                if (branch != null) {
                    appendFiles.toBranch(branch);
                }
                appendFiles.commit();
                sleep(10);
            }
            barrier.incrementAndGet();
        }
    });
    try {
        assertThatThrownBy(deleteFuture::get).isInstanceOf(ExecutionException.class).cause().isInstanceOf(IllegalStateException.class).hasMessageContaining("the table has been concurrently modified");
    } finally {
        shouldAppend.set(false);
        appendFuture.cancel(true);
    }
    executorService.shutdown();
    Assert.assertTrue("Timeout", executorService.awaitTermination(2, TimeUnit.MINUTES));
}

