@Test
public void testCreateTagWithRetain() throws NoSuchTableException {
    Table table = insertRows();
    long firstSnapshotId = table.currentSnapshot().snapshotId();
    long maxRefAge = 10L;
    List<SimpleRecord> records = ImmutableList.of(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.writeTo(tableName).append();
    for (String timeUnit : TIME_UNITS) {
        String tagName = "t1" + timeUnit;
        sql("ALTER TABLE %s CREATE TAG %s AS OF VERSION %d RETAIN %d %s", tableName, tagName, firstSnapshotId, maxRefAge, timeUnit);
        table.refresh();
        SnapshotRef ref = table.refs().get(tagName);
        Assert.assertEquals("The tag needs to point to a specific snapshot id.", firstSnapshotId, ref.snapshotId());
        Assert.assertEquals("The tag needs to have the correct max ref age.", TimeUnit.valueOf(timeUnit.toUpperCase(Locale.ENGLISH)).toMillis(maxRefAge), ref.maxRefAgeMs().longValue());
    }
    String tagName = "t1";
    assertThatThrownBy(() -> sql("ALTER TABLE %s CREATE TAG %s AS OF VERSION %d RETAIN", tableName, tagName, firstSnapshotId, maxRefAge)).isInstanceOf(IcebergParseException.class).hasMessageContaining("mismatched input");
    assertThatThrownBy(() -> sql("ALTER TABLE %s CREATE TAG %s RETAIN %s DAYS", tableName, tagName, "abc")).isInstanceOf(IcebergParseException.class).hasMessageContaining("mismatched input");
    assertThatThrownBy(() -> sql("ALTER TABLE %s CREATE TAG %s AS OF VERSION %d RETAIN %d SECONDS", tableName, tagName, firstSnapshotId, maxRefAge)).isInstanceOf(IcebergParseException.class).hasMessageContaining("mismatched input 'SECONDS' expecting {'DAYS', 'HOURS', 'MINUTES'}");
}

