@Test
public void showViews() throws NoSuchTableException {
    insertRows(6);
    String sql = String.format("SELECT * from %s", tableName);
    sql("CREATE VIEW v1 AS %s", sql);
    sql("CREATE VIEW prefixV2 AS %s", sql);
    sql("CREATE VIEW prefixV3 AS %s", sql);
    sql("CREATE GLOBAL TEMPORARY VIEW globalViewForListing AS %s", sql);
    sql("CREATE TEMPORARY VIEW tempViewForListing AS %s", sql);
    // spark stores temp views case-insensitive by default
    Object[] tempView = row("", "tempviewforlisting", true);
    assertThat(sql("SHOW VIEWS")).contains(row(NAMESPACE.toString(), "prefixV2", false), row(NAMESPACE.toString(), "prefixV3", false), row(NAMESPACE.toString(), "v1", false), tempView);
    assertThat(sql("SHOW VIEWS IN %s", catalogName)).contains(row(NAMESPACE.toString(), "prefixV2", false), row(NAMESPACE.toString(), "prefixV3", false), row(NAMESPACE.toString(), "v1", false), tempView);
    assertThat(sql("SHOW VIEWS IN %s.%s", catalogName, NAMESPACE)).contains(row(NAMESPACE.toString(), "prefixV2", false), row(NAMESPACE.toString(), "prefixV3", false), row(NAMESPACE.toString(), "v1", false), tempView);
    assertThat(sql("SHOW VIEWS LIKE 'pref*'")).contains(row(NAMESPACE.toString(), "prefixV2", false), row(NAMESPACE.toString(), "prefixV3", false));
    assertThat(sql("SHOW VIEWS LIKE 'non-existing'")).isEmpty();
    assertThat(sql("SHOW VIEWS IN spark_catalog.default")).contains(tempView);
    assertThat(sql("SHOW VIEWS IN global_temp")).contains(// spark stores temp views case-insensitive by default
    row("global_temp", "globalviewforlisting", true), tempView);
    sql("USE spark_catalog");
    assertThat(sql("SHOW VIEWS")).contains(tempView);
    assertThat(sql("SHOW VIEWS IN default")).contains(tempView);
}

