    // trino view should show up in the view versions & history
    assertThat(view.history()).hasSize(2);
    assertThat(view.history()).element(0).extracting(ViewHistoryEntry::versionId).isEqualTo(1);
    assertThat(view.history()).element(1).extracting(ViewHistoryEntry::versionId).isEqualTo(2);
    assertThat(view.versions()).hasSize(2);
    assertThat(view.versions()).element(0).extracting(ViewVersion::versionId).isEqualTo(1);
    assertThat(view.versions()).element(1).extracting(ViewVersion::versionId).isEqualTo(2);
    assertThat(Lists.newArrayList(view.versions()).get(0).representations()).hasSize(1).first().asInstanceOf(InstanceOfAssertFactories.type(SQLViewRepresentation.class)).isEqualTo(ImmutableSQLViewRepresentation.builder().dialect("trino").sql(sql).build());
    assertThat(Lists.newArrayList(view.versions()).get(1).representations()).hasSize(1).first().asInstanceOf(InstanceOfAssertFactories.type(SQLViewRepresentation.class)).isEqualTo(ImmutableSQLViewRepresentation.builder().dialect("spark").sql(sql).build());
}

