    List<String> deletedFiles = Lists.newArrayList();
    // Expire `B` commit.
    ExpireSnapshots.Result firstResult = SparkActions.get().expireSnapshots(table).deleteWith(deletedFiles::add).expireSnapshotId(snapshotB.snapshotId()).execute();
