    writeRecords(4, SCALE, 4);
    table.updateProperties().set(TableProperties.FORMAT_VERSION, "2").commit();
    RewriteDataFilesSparkAction basicRewrite = basicRewrite(table).binPack();
    List<Long> expected = toGroupStream(table, basicRewrite).mapToLong(RewriteFileGroup::sizeInBytes).boxed().collect(Collectors.toList());
