@Test
public void testAllEntriesTable() throws Exception {
    TableIdentifier tableIdentifier = TableIdentifier.of("db", "entries_test");
    Table table = createTable(tableIdentifier, SCHEMA, PartitionSpec.unpartitioned());
    Table entriesTable = loadTable(tableIdentifier, "all_entries");
    Dataset<Row> df1 = spark.createDataFrame(Lists.newArrayList(new SimpleRecord(1, "a")), SimpleRecord.class);
    Dataset<Row> df2 = spark.createDataFrame(Lists.newArrayList(new SimpleRecord(1, "b")), SimpleRecord.class);
    df1.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    // delete the first file to test that not only live files are listed
    table.newDelete().deleteFromRowFilter(Expressions.equal("id", 1)).commit();
    // add a second file
    df2.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    // ensure table data isn't stale
    table.refresh();
    Dataset<Row> entriesTableDs = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "all_entries")).orderBy("snapshot_id");
    List<Row> actual = TestHelpers.selectNonDerived(entriesTableDs).collectAsList();
    List<GenericData.Record> expected = Lists.newArrayList();
    for (ManifestFile manifest : Iterables.concat(Iterables.transform(table.snapshots(), s -> s.allManifests(table.io())))) {
        InputFile in = table.io().newInputFile(manifest.path());
        try (CloseableIterable<GenericData.Record> rows = Avro.read(in).project(entriesTable.schema()).build()) {
            // each row must inherit snapshot_id and sequence_number
            rows.forEach(row -> {
                if (row.get("snapshot_id").equals(table.currentSnapshot().snapshotId())) {
                    // data sequence number
                    row.put(2, 3L);
                    // file sequence number
                    row.put(3, 3L);
                } else {
                    // data sequence number
                    row.put(2, 1L);
                    // file sequence number
                    row.put(3, 1L);
                }
                GenericData.Record file = (GenericData.Record) row.get("data_file");
                TestHelpers.asMetadataRecord(file);
                expected.add(row);
            });
        }
    }
    expected.sort(Comparator.comparing(o -> (Long) o.get("snapshot_id")));
    assertThat(expected).as("Entries table should have 3 rows").hasSize(3);
    assertThat(actual).as("Actual results should have 3 rows").hasSize(3);
    for (int i = 0; i < expected.size(); i += 1) {
        TestHelpers.assertEqualsSafe(TestHelpers.nonDerivedSchema(entriesTableDs), expected.get(i), actual.get(i));
    }
}

