    assertThat(actual).as("Actual results should have two rows").hasSize(2);
    GenericRecordBuilder builder = new GenericRecordBuilder(AvroSchemaUtil.convert(partitionsTable.schema(), "partitions"));
    GenericRecordBuilder partitionBuilder = new GenericRecordBuilder(AvroSchemaUtil.convert(partitionsTable.schema().findType("partition").asStructType(), "partition"));
    List<GenericData.Record> expected = Lists.newArrayList();
    expected.add(builder.set("partition", partitionBuilder.set("id", 1).build()).set("record_count", 3L).set("file_count", 1).set("total_data_file_size_in_bytes", totalSizeInBytes(table.snapshot(firstCommitId).addedDataFiles(table.io()))).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", table.snapshot(firstCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", firstCommitId).build());
    expected.add(builder.set("partition", partitionBuilder.set("id", 2).build()).set("record_count", 3L).set("file_count", 1).set("total_data_file_size_in_bytes", totalSizeInBytes(table.snapshot(firstCommitId).addedDataFiles(table.io()))).set("position_delete_record_count", // should be incremented now
    2L).set("position_delete_file_count", // should be incremented now
    2).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", table.snapshot(posDeleteCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", posDeleteCommitId).build());
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actual.get(i));
    }
    // test equality delete
    DeleteFile eqDeleteFile1 = writeEqDeleteFile(table, "d");
    DeleteFile eqDeleteFile2 = writeEqDeleteFile(table, "f");
    table.newRowDelta().addDeletes(eqDeleteFile1).addDeletes(eqDeleteFile2).commit();
    table.refresh();
    long eqDeleteCommitId = table.currentSnapshot().snapshotId();
    actual = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).orderBy("partition.id").collectAsList();
    assertThat(actual).as("Actual results should have two rows").hasSize(2);
    expected.remove(0);
    expected.add(0, builder.set("partition", partitionBuilder.set("id", 1).build()).set("record_count", 3L).set("file_count", 1).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", // should be incremented now
    2L).set("equality_delete_file_count", // should be incremented now
    2).set("last_updated_at", table.snapshot(eqDeleteCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", eqDeleteCommitId).build());
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actual.get(i));
    }
}

@Test
