    assertThat(Spark3Util.describe(buildSortOrder("truncate[3]", schema, 1))).as("Sort order isn't correct.").isEqualTo("truncate(data, 3) DESC NULLS FIRST");
    assertThat(Spark3Util.describe(buildSortOrder("year", schema, 2))).as("Sort order isn't correct.").isEqualTo("years(time) DESC NULLS FIRST");
